async fn registered_request_context(
    processor: &MessageProcessor,
    connection_id: ConnectionId,
    canonical_method: &'static str,
) -> crate::request_context::RequestContext {
    let connection = processor
        .session_manager
        .connection_context(connection_id)
        .await
        .expect("test connection context");
    crate::request_context::RequestContext::new(
        &connection,
        None,
        crate::request_context::CanonicalMethod::rpc(canonical_method),
    )
}

async fn test_execution_authorization_admission(
    processor: &MessageProcessor,
    connection_id: ConnectionId,
    workspace_id: &str,
    thread_id: &str,
) -> crate::authorization::ExecutionAuthorizationAdmission {
    ensure_test_superuser_execution_authority(processor.crud_store.as_ref()).await;
    let request = registered_request_context(
        processor,
        connection_id,
        pioneer_protocol::constants::methods::TURN_START,
    )
    .await;
    let action = crate::authorization::ResourceAction::AgentTurnStart;
    let action_gate = crate::authorization::AuthorizationService::new().authorize_action(
        request.principal().kind,
        request.principal().role_key.as_ref(),
        action,
    );
    let proof =
        match crate::authorization::AuthorizationResolver::new((*processor.crud_store).clone())
            .authorize_thread(
                request.principal(),
                &action_gate,
                action,
                thread_id,
                Some(workspace_id),
            )
            .await
            .expect("test thread authorization should resolve")
        {
            crate::authorization::ProofResolution::Authorized(proof) => proof,
            crate::authorization::ProofResolution::Denied(decision) => {
                panic!("test thread authorization should be allowed: {decision:?}")
            }
        };
    let revision =
        pioneer_crud::current_policy_generation(&processor.crud_store.database_connection())
            .await
            .expect("test policy generation should load")
            .get();
    crate::authorization::ExecutionAuthorizationAdmission::from_authorized_thread(
        &request, &proof, revision,
    )
    .expect("test execution admission should bind the authorized thread")
}

async fn persist_test_execution_authorization_context(
    processor: &MessageProcessor,
    connection_id: ConnectionId,
    workspace_id: &str,
    root_thread_id: &str,
    turn_id: &str,
) {
    let connection = processor
        .session_manager
        .connection_context(connection_id)
        .await
        .expect("test connection context");
    persist_test_execution_authorization_context_for_principal(
        processor,
        connection.principal(),
        workspace_id,
        root_thread_id,
        turn_id,
    )
    .await;
}

async fn persist_test_execution_authorization_context_for_principal(
    processor: &MessageProcessor,
    principal: &crate::auth::AuthenticatedSessionPrincipal,
    workspace_id: &str,
    root_thread_id: &str,
    turn_id: &str,
) {
    persist_test_execution_authorization_context_for_principal_with_profile(
        processor,
        principal,
        workspace_id,
        root_thread_id,
        turn_id,
        &default_test_permission_profile(),
    )
    .await;
}

async fn persist_test_execution_authorization_context_for_principal_with_profile(
    processor: &MessageProcessor,
    principal: &crate::auth::AuthenticatedSessionPrincipal,
    workspace_id: &str,
    root_thread_id: &str,
    turn_id: &str,
    permission_profile: &pioneer_protocol::TurnPermissionProfileSnapshot,
) {
    ensure_test_superuser_execution_authority(processor.crud_store.as_ref()).await;
    let mut context = crate::authorization::ExecutionAuthorizationContext::for_test(
        principal,
        workspace_id,
        root_thread_id,
        permission_profile,
        None,
    );
    context.bind_test_provider_authority(
        "openai",
        "test-model",
        processor
            .provider_registry
            .authority_fingerprint_for_workspace(workspace_id, "openai")
            .as_str(),
    );
    let encoded = context
        .to_persisted_json()
        .expect("test execution authorization should serialize");
    assert!(
        processor
            .crud_store
            .set_turn_execution_authorization_context(turn_id, encoded.as_str())
            .await
            .expect("test execution authorization should persist")
    );
}

async fn ensure_test_superuser_execution_turn(
    processor: &MessageProcessor,
    workspace_id: &str,
    thread_id: &str,
    turn_id: &str,
) {
    ensure_test_superuser_execution_authority(processor.crud_store.as_ref()).await;
    let principal = authenticated_test_superuser();
    if processor
        .crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("test execution turn lookup should succeed")
        .is_none()
    {
        let timestamp = now_timestamp_secs();
        let thread = Thread {
            workspace_id: workspace_id.to_owned(),
            id: thread_id.to_owned(),
            name: None,
            preview: String::new(),
            preview_author: None,
            mode: ThreadMode::Agent,
            model: "test-model".to_owned(),
            model_provider: "openai".to_owned(),
            reasoning_effort: None,
            created_at: timestamp,
            updated_at: timestamp,
            status: ThreadStatus::Active,
            origin_kind: ThreadOriginKind::User,
            sidebar_visibility: ThreadSidebarVisibility::Visible,
            agent_nickname: None,
            agent_role: None,
            visibility: None,
            turns: Vec::new(),
        };
        let turn = Turn {
            id: turn_id.to_owned(),
            status: TurnStatus::InProgress,
            turn_kind: Default::default(),
            origin: TurnOrigin::User,
            mode: Default::default(),
            author: None,
            reply_to_turn_id: None,
            mentions: Vec::new(),
            message_revision: 0,
            message_deleted: false,
            error: None,
            prompt_manifest: None,
            permission_profile: default_test_permission_profile(),
        };
        processor
            .crud_store
            .materialize_turn_start(
                &thread,
                SandboxMode::FullAccess,
                &turn,
                &[],
                pioneer_protocol::PersistedActorRef::Principal(principal.principal_id.clone()),
            )
            .await
            .expect("test execution turn should materialize");
    }
    if processor
        .crud_store
        .get_turn_execution_authorization_context(turn_id)
        .await
        .expect("test execution authorization lookup should succeed")
        .is_none()
    {
        persist_test_execution_authorization_context_for_principal(
            processor,
            authenticated_test_superuser().as_ref(),
            workspace_id,
            thread_id,
            turn_id,
        )
        .await;
    }
}

async fn bind_test_execution_skill_grants(
    processor: &MessageProcessor,
    turn_id: &str,
    skill_ids: impl IntoIterator<Item = pioneer_protocol::SkillId>,
) {
    let encoded = processor
        .crud_store
        .get_turn_execution_authorization_context(turn_id)
        .await
        .expect("test execution authorization should load")
        .expect("test execution authorization should exist");
    let mut context =
        crate::authorization::ExecutionAuthorizationContext::from_persisted_json(encoded.as_str())
            .expect("test execution authorization should decode");
    context.bind_test_skill_grants(skill_ids);
    let encoded = context
        .to_persisted_json()
        .expect("skill-authorized test execution should serialize");
    assert!(
        processor
            .crud_store
            .set_turn_execution_authorization_context(turn_id, encoded.as_str())
            .await
            .expect("skill-authorized test execution should persist")
    );
}

async fn persist_test_cli_execution_authorization_context(
    crud_store: &CrudStore,
    workspace_id: &str,
    root_thread_id: &str,
    turn_id: &str,
    runtime_id: &str,
    runtime_kind: &str,
) {
    ensure_test_superuser_execution_authority(crud_store).await;
    let runtime_kind = match runtime_kind {
        "codex" => CLIAgentRuntimeKind::Codex,
        "claude" => CLIAgentRuntimeKind::Claude,
        other => panic!("unsupported test CLI runtime kind `{other}`"),
    };
    let execution_backend = AgentExecutionBackend::CLIAgentRuntime {
        runtime_id: runtime_id.to_owned(),
        runtime_kind,
    };
    let principal = authenticated_test_superuser();
    let context = crate::authorization::ExecutionAuthorizationContext::for_test(
        principal.as_ref(),
        workspace_id,
        root_thread_id,
        &default_test_permission_profile(),
        Some(&execution_backend),
    );
    let encoded = context
        .to_persisted_json()
        .expect("test CLI execution authorization should serialize");
    assert!(
        crud_store
            .set_turn_execution_authorization_context(turn_id, encoded.as_str())
            .await
            .expect("test CLI execution authorization should persist")
    );
    if crud_store
        .get_turn_execution_security_snapshot(turn_id)
        .await
        .expect("test CLI execution security lookup should succeed")
        .is_none()
    {
        assert!(
            crud_store
                .set_turn_execution_security_snapshot(
                    turn_id,
                    &pioneer_protocol::TurnExecutionSecuritySnapshot::unrestricted_full_access(
                        "/tmp/project",
                        chrono::Utc::now().timestamp_millis(),
                    ),
                )
                .await
                .expect("test CLI execution security snapshot should persist")
        );
    }
}

async fn persist_test_cli_instruction_projection(
    crud_store: &CrudStore,
    turn_id: &str,
    runtime_kind: CLIAgentRuntimeKind,
) {
    let instruction_text =
        "## Pioneer CLI Runtime Instructions\n\nContinue the interrupted Pioneer turn.";
    let instruction_fingerprint = Sha256::digest(instruction_text.as_bytes())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let (runtime_kind_label, transport_kind) = match runtime_kind {
        CLIAgentRuntimeKind::Codex => (
            "codex",
            CLIRuntimeElevatedInstructionTransport::CodexTurnCollaborationMode,
        ),
        CLIAgentRuntimeKind::Claude => (
            "claude",
            CLIRuntimeElevatedInstructionTransport::ClaudeAppendSystemPromptFile,
        ),
    };
    let now = chrono::Utc::now().fixed_offset();
    crud_store
        .insert_cli_runtime_instruction_projection_if_absent(NewCliRuntimeInstructionProjection {
            turn_id: turn_id.to_owned(),
            runtime_kind: runtime_kind_label.to_owned(),
            transport_kind: transport_kind.as_str().to_owned(),
            instruction_text: instruction_text.to_owned(),
            instruction_fingerprint,
            section_ids_json: r#"["pioneer_cli_runtime_instructions"]"#.to_owned(),
            compiler_version: "recovery-test".to_owned(),
            created_at: now,
            updated_at: now,
        })
        .await
        .expect("test CLI runtime instruction projection should persist");
}

