#[derive(Default)]
struct RecordingThreadEpisodicIngestor {
    calls: TokioMutex<Vec<ThreadEpisodicCommittedItem>>,
    fail: bool,
}

#[async_trait]
impl ThreadEpisodicIngestor for RecordingThreadEpisodicIngestor {
    async fn ingest_committed_item(
        &self,
        item: ThreadEpisodicCommittedItem,
    ) -> anyhow::Result<ThreadEpisodicIngestionOutcome> {
        self.calls.lock().await.push(item);
        if self.fail {
            anyhow::bail!("forced thread episodic ingestion failure");
        }
        Ok(ThreadEpisodicIngestionOutcome::Accepted)
    }
}

async fn wait_for_episodic_ingestor_calls(
    ingestor: &RecordingThreadEpisodicIngestor,
    expected: usize,
) {
    timeout(Duration::from_secs(2), async {
        loop {
            if ingestor.calls.lock().await.len() >= expected {
                break;
            }
            tokio::task::yield_now().await;
        }
    })
    .await
    .expect("optional episodic outbox delivery should complete");
}

#[derive(Default)]
struct RecordingCliRuntimeSession {
    thread_starts: TokioMutex<Vec<CLIAgentRuntimeThreadOpenParams>>,
    thread_resumes: TokioMutex<Vec<(String, CLIAgentRuntimeThreadOpenParams)>>,
    turn_starts: TokioMutex<Vec<CLIAgentRuntimeTurnStartParams>>,
    next_native_turn_id: TokioMutex<Option<String>>,
    responses: TokioMutex<Vec<(JsonValue, JsonValue)>>,
    response_errors: TokioMutex<Vec<(JsonValue, i64, String, Option<JsonValue>)>>,
    interrupts: TokioMutex<Vec<(Option<String>, Option<String>)>>,
    thread_compactions: TokioMutex<Vec<CLIAgentRuntimeThreadCompactRequest>>,
    thread_compact_result: TokioMutex<Option<CLIAgentRuntimeThreadCompactResult>>,
    thread_name_sets: TokioMutex<Vec<CLIAgentRuntimeThreadNameSetRequest>>,
    thread_name_set_result: TokioMutex<Option<CLIAgentRuntimeThreadNameSetResult>>,
    thread_name_set_error: TokioMutex<Option<String>>,
    thread_forks: TokioMutex<Vec<CLIAgentRuntimeThreadForkRequest>>,
    thread_fork_result: TokioMutex<Option<CLIAgentRuntimeThreadForkResult>>,
    turn_steers: TokioMutex<Vec<CLIAgentRuntimeTurnSteerRequest>>,
    turn_steer_result: TokioMutex<Option<CLIAgentRuntimeTurnSteerResult>>,
    turn_observation: TokioMutex<Option<CLIAgentRuntimeTurnObservation>>,
    turn_liveness_probe: TokioMutex<Option<CLIAgentRuntimeTurnLivenessProbe>>,
    mcp_preparations: TokioMutex<Vec<(String, String)>>,
    projected_mcp_store: TokioMutex<Option<Arc<CrudStore>>>,
    mcp_retargets: TokioMutex<Vec<(String, String, String)>>,
    goal_resets: TokioMutex<Vec<String>>,
    goal_clears: TokioMutex<Vec<String>>,
    closes: AtomicUsize,
    event_log: TokioMutex<Option<Arc<TokioMutex<Vec<String>>>>>,
}

impl RecordingCliRuntimeSession {
    async fn set_event_log(&self, event_log: Arc<TokioMutex<Vec<String>>>) {
        *self.event_log.lock().await = Some(event_log);
    }

    async fn record_event(&self, event: &str) {
        if let Some(event_log) = self.event_log.lock().await.clone() {
            event_log.lock().await.push(event.to_owned());
        }
    }

    async fn set_next_native_turn_id(&self, native_turn_id: impl Into<String>) {
        *self.next_native_turn_id.lock().await = Some(native_turn_id.into());
    }

    async fn enable_projected_mcp_metadata(&self, crud_store: Arc<CrudStore>) {
        *self.projected_mcp_store.lock().await = Some(crud_store);
    }
}

#[async_trait]
impl CLIAgentRuntimeSession for RecordingCliRuntimeSession {
    async fn close(&self) -> anyhow::Result<()> {
        self.closes.fetch_add(1, Ordering::SeqCst);
        Ok(())
    }

    fn supports_thread_name_sync(&self) -> bool {
        true
    }

    async fn start_thread(
        &self,
        params: CLIAgentRuntimeThreadOpenParams,
        _timeout: Duration,
    ) -> anyhow::Result<CLIAgentRuntimeThreadOpenSnapshot> {
        self.record_event("native_thread_start").await;
        self.thread_starts.lock().await.push(params.clone());
        Ok(CLIAgentRuntimeThreadOpenSnapshot {
            native_thread_id: "native_thread_default".to_owned(),
            cwd: Some(params.cwd.clone()),
            model: params.model.clone(),
            raw: json!({
                "thread": {
                    "id": "native_thread_default",
                    "cwd": params.cwd,
                    "model": params.model
                }
            }),
        })
    }

    async fn resume_thread(
        &self,
        native_thread_id: &str,
        params: CLIAgentRuntimeThreadOpenParams,
        _timeout: Duration,
    ) -> anyhow::Result<CLIAgentRuntimeThreadOpenSnapshot> {
        self.thread_resumes
            .lock()
            .await
            .push((native_thread_id.to_owned(), params.clone()));
        Ok(CLIAgentRuntimeThreadOpenSnapshot {
            native_thread_id: native_thread_id.to_owned(),
            cwd: Some(params.cwd.clone()),
            model: params.model.clone(),
            raw: json!({
                "thread": {
                    "id": native_thread_id,
                    "cwd": params.cwd,
                    "model": params.model
                }
            }),
        })
    }

    async fn start_turn(
        &self,
        params: CLIAgentRuntimeTurnStartParams,
        _timeout: Duration,
    ) -> anyhow::Result<CLIAgentRuntimeTurnStartSnapshot> {
        self.turn_starts.lock().await.push(params.clone());
        let native_turn_id = self
            .next_native_turn_id
            .lock()
            .await
            .take()
            .unwrap_or_else(|| "native_turn_default".to_owned());
        Ok(CLIAgentRuntimeTurnStartSnapshot {
            native_thread_id: params.native_thread_id,
            native_turn_id: native_turn_id.clone(),
            raw: json!({
                "turn": {
                    "id": native_turn_id
                }
            }),
        })
    }

    async fn prepare_mcp_turn(
        &self,
        pioneer_thread_id: &str,
        pioneer_turn_id: &str,
    ) -> anyhow::Result<Option<CLIAgentRuntimeMcpTurnMetadata>> {
        self.mcp_preparations
            .lock()
            .await
            .push((pioneer_thread_id.to_owned(), pioneer_turn_id.to_owned()));
        let Some(crud_store) = self.projected_mcp_store.lock().await.clone() else {
            return Ok(None);
        };
        let projection = crud_store
            .get_turn_mcp_projection(pioneer_turn_id)
            .await?
            .ok_or_else(|| anyhow::anyhow!("test CLI MCP projection is missing"))?;
        Ok(Some(CLIAgentRuntimeMcpTurnMetadata {
            adapter_kind: "recording_cli_mcp".to_owned(),
            manifest_hash: projection.manifest_hash,
            projection_fingerprint: "a".repeat(64),
            provider_contract_fingerprint: "b".repeat(64),
            isolation_contract_fingerprint: "c".repeat(64),
            session_generation: 1,
            projection_activation_generation: 1,
        }))
    }

    async fn retarget_mcp_turn(
        &self,
        pioneer_turn_id: &str,
        native_thread_id: &str,
        native_turn_id: &str,
    ) -> anyhow::Result<()> {
        self.mcp_retargets.lock().await.push((
            pioneer_turn_id.to_owned(),
            native_thread_id.to_owned(),
            native_turn_id.to_owned(),
        ));
        Ok(())
    }

    async fn reset_native_thread_goal(&self, native_thread_id: &str) -> anyhow::Result<()> {
        self.goal_resets
            .lock()
            .await
            .push(native_thread_id.to_owned());
        Ok(())
    }

    async fn clear_native_thread_goal(&self, native_thread_id: &str) -> anyhow::Result<()> {
        self.goal_clears
            .lock()
            .await
            .push(native_thread_id.to_owned());
        Ok(())
    }

    async fn respond_to_request(
        &self,
        native_request_id: JsonValue,
        response: JsonValue,
    ) -> anyhow::Result<()> {
        self.responses
            .lock()
            .await
            .push((native_request_id, response));
        Ok(())
    }

    async fn fail_request(
        &self,
        native_request_id: JsonValue,
        code: i64,
        message: String,
        data: Option<JsonValue>,
    ) -> anyhow::Result<()> {
        self.response_errors
            .lock()
            .await
            .push((native_request_id, code, message, data));
        Ok(())
    }

    async fn interrupt_turn(
        &self,
        native_thread_id: Option<&str>,
        native_turn_id: Option<&str>,
    ) -> anyhow::Result<()> {
        self.interrupts.lock().await.push((
            native_thread_id.map(str::to_owned),
            native_turn_id.map(str::to_owned),
        ));
        Ok(())
    }

    async fn load_turn_snapshot(
        &self,
        _native_thread_id: &str,
        _native_turn_id: &str,
    ) -> anyhow::Result<Option<CLIAgentRuntimeTurnObservation>> {
        Ok(self.turn_observation.lock().await.clone())
    }

    async fn probe_turn_liveness(
        &self,
        _native_thread_id: &str,
        _native_turn_id: &str,
    ) -> anyhow::Result<CLIAgentRuntimeTurnLivenessProbe> {
        Ok(self
            .turn_liveness_probe
            .lock()
            .await
            .unwrap_or(CLIAgentRuntimeTurnLivenessProbe::SnapshotRequired))
    }

    async fn thread_compact(
        &self,
        request: CLIAgentRuntimeThreadCompactRequest,
    ) -> anyhow::Result<CLIAgentRuntimeThreadCompactResult> {
        self.thread_compactions.lock().await.push(request.clone());
        Ok(self.thread_compact_result.lock().await.clone().unwrap_or(
            CLIAgentRuntimeThreadCompactResult {
                native_thread_id: request.native_thread_id,
                raw: Some(json!({"ok": true})),
            },
        ))
    }

    async fn set_thread_name(
        &self,
        request: CLIAgentRuntimeThreadNameSetRequest,
    ) -> anyhow::Result<CLIAgentRuntimeThreadNameSetResult> {
        self.thread_name_sets.lock().await.push(request.clone());
        if let Some(message) = self.thread_name_set_error.lock().await.clone() {
            anyhow::bail!("{message}");
        }
        Ok(self.thread_name_set_result.lock().await.clone().unwrap_or(
            CLIAgentRuntimeThreadNameSetResult {
                native_thread_id: request.native_thread_id,
                raw: Some(json!({"ok": true})),
            },
        ))
    }

    async fn fork_thread(
        &self,
        request: CLIAgentRuntimeThreadForkRequest,
    ) -> anyhow::Result<CLIAgentRuntimeThreadForkResult> {
        self.thread_forks.lock().await.push(request.clone());
        Ok(self.thread_fork_result.lock().await.clone().unwrap_or(
            CLIAgentRuntimeThreadForkResult {
                native_thread_id: format!("{}-fork", request.native_thread_id),
                native_cwd: None,
                native_model: None,
                raw: Some(json!({"ok": true})),
            },
        ))
    }

    async fn steer_turn(
        &self,
        request: CLIAgentRuntimeTurnSteerRequest,
    ) -> anyhow::Result<CLIAgentRuntimeTurnSteerResult> {
        self.turn_steers.lock().await.push(request.clone());
        Ok(self
            .turn_steer_result
            .lock()
            .await
            .clone()
            .unwrap_or(CLIAgentRuntimeTurnSteerResult {
                native_thread_id: request.native_thread_id,
                native_turn_id: request.native_turn_id,
                raw: Some(json!({"ok": true})),
            }))
    }
}

struct StaticCliRuntimeSessionFactory {
    session: Arc<RecordingCliRuntimeSession>,
    launch_specs: Option<Arc<TokioMutex<Vec<CliSessionLaunchSpec>>>>,
}

#[async_trait]
impl CLIAgentRuntimeSessionFactory for StaticCliRuntimeSessionFactory {
    async fn start_session_with_launch_spec(
        &self,
        _instance: &crate::cli_runtime::session_instance::CliSessionInstanceId,
        launch_spec: &CliSessionLaunchSpec,
    ) -> anyhow::Result<Arc<dyn CLIAgentRuntimeSession>> {
        if let Some(launch_specs) = self.launch_specs.as_ref() {
            launch_specs.lock().await.push(launch_spec.clone());
        }
        Ok(self.session.clone())
    }
}

fn test_cli_runtime_manager(
    session: Arc<RecordingCliRuntimeSession>,
) -> Arc<CLIAgentRuntimeManager> {
    test_cli_runtime_manager_with_launch_specs(session, None)
}

fn test_cli_runtime_manager_with_launch_specs(
    session: Arc<RecordingCliRuntimeSession>,
    launch_specs: Option<Arc<TokioMutex<Vec<CliSessionLaunchSpec>>>>,
) -> Arc<CLIAgentRuntimeManager> {
    Arc::new(
        CLIAgentRuntimeManager::new(
            Arc::new(StaticCliRuntimeSessionFactory {
                session,
                launch_specs,
            }),
            Duration::from_secs(60),
        )
        .expect("CLI runtime manager should build"),
    )
}

fn with_enabled_test_cli_runtime_catalog(processor: MessageProcessor) -> MessageProcessor {
    let runtime_home = std::env::temp_dir().join(format!(
        "pioneer-message-cli-runtime-{}",
        pioneer_protocol::generate_id(21)
    ));
    std::fs::create_dir_all(runtime_home.as_path())
        .expect("test CLI runtime home should be created");
    let app_config = pioneer_config::AppConfig::load().expect("test app config should load");
    let settings_name = crate::settings::normalize_settings_file_name(
        app_config.gateway.settings_file_name.as_str(),
    )
    .expect("test Gateway settings file name should be valid");
    let settings_path = runtime_home.join(settings_name.as_str());
    let mut settings = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        app_config.gateway.settings_version,
        settings_name.as_str(),
    )
    .expect("test Gateway settings should load");
    settings
        .set_cli_runtime_settings_for_tests(pioneer_protocol::GatewayCliRuntimeSettings::default())
        .expect("test CLI runtime catalog should be accepted");
    crate::settings::save_gateway_settings(settings_path.as_path(), &settings)
        .expect("test CLI runtime catalog should persist");
    processor.with_runtime_home_for_tests(runtime_home)
}

fn supported_test_cli_mcp_readiness(
    runtime_kind: CLIAgentRuntimeKind,
) -> pioneer_protocol::CliMcpAdapterReadiness {
    let (injection, projection_update) = match runtime_kind {
        CLIAgentRuntimeKind::Codex => (
            pioneer_protocol::CliMcpInjectionKind::CodexManagedStdioMcp,
            pioneer_protocol::CliMcpProjectionUpdateKind::CodexRestartAppServerResumeThread,
        ),
        CLIAgentRuntimeKind::Claude => (
            pioneer_protocol::CliMcpInjectionKind::ClaudeStrictStdioMcp,
            pioneer_protocol::CliMcpProjectionUpdateKind::ClaudeRestartProcessResumeSession,
        ),
    };
    pioneer_protocol::CliMcpAdapterReadiness {
        supported: true,
        injection,
        projection_update,
        strict_isolation: true,
        contract_fingerprint: "d".repeat(64),
        local_executable_fingerprint: "e".repeat(64),
        provider_version: Some("recording-runtime".to_owned()),
        max_tools: 1_024,
        max_schema_bytes: 8 * 1_024 * 1_024,
        diagnostics: Vec::new(),
    }
}

struct CliRuntimeSecurityHarness {
    rx: mpsc::Receiver<Message>,
    connection_id: ConnectionId,
    thread_manager: Arc<ThreadManager>,
    provider_registry: Arc<pioneer_provider::ProviderRegistry>,
    crud_store: Arc<CrudStore>,
    workspace_id: String,
    cli_session: Arc<RecordingCliRuntimeSession>,
    cli_manager: Arc<CLIAgentRuntimeManager>,
    self_improvement_supervisor:
        Arc<crate::self_improvement::supervisor::SelfImprovementSupervisor>,
    processor: Arc<MessageProcessor>,
}

async fn setup_cli_runtime_security_harness() -> CliRuntimeSecurityHarness {
    // Security tests normally consume each response immediately, while the
    // self-improvement vertical E2E intentionally leaves several real
    // Composer children running at once. Keep the test transport bounded but
    // large enough that durable lifecycle notifications cannot deadlock the
    // producer before the next response drain.
    let (tx, rx) = mpsc::channel(512);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let provider_registry = test_provider();
    let self_improvement_supervisor = Arc::new(
        crate::self_improvement::supervisor::SelfImprovementSupervisor::new(
            crud_store.clone(),
            provider_registry.clone(),
            workspace_manager.clone(),
            std::collections::BTreeMap::new(),
            1024 * 1024,
        ),
    );
    let runtime_home = unique_temp_dir("cli_runtime_security");
    std::fs::create_dir_all(&runtime_home).expect("CLI runtime test home must exist");
    let cli_manager = test_cli_runtime_manager(cli_session.clone());
    let processor = with_enabled_test_cli_runtime_catalog(
        MessageProcessor::new(
            thread_manager.clone(),
            provider_registry.clone(),
            session_manager,
            workspace_manager.clone(),
            crud_store.clone(),
            test_gateway_secrets(),
            test_summary_config(),
            test_context_budget(),
            test_tool_loop_config(),
        )
        .with_cli_runtime_manager_for_tests(cli_manager.clone())
        .with_runtime_home_for_tests(runtime_home)
        .with_self_improvement_supervisor(self_improvement_supervisor.clone()),
    );
    sync_test_cli_runtime_identities(&processor)
        .await
        .expect("CLI runtime security harness should project agent domain identities");

    CliRuntimeSecurityHarness {
        rx,
        connection_id,
        thread_manager,
        provider_registry,
        crud_store,
        workspace_id,
        cli_session,
        cli_manager,
        self_improvement_supervisor,
        processor: Arc::new(processor),
    }
}

#[test]
fn skill_pack_turn_normalization_is_authoritative_ordered_and_fail_closed() {
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .expect("skill pack normalization runtime")
        .block_on(async {
            let harness = setup_cli_runtime_security_harness().await;
            let pack_id = pioneer_protocol::SkillPackId::new("P".repeat(21)).expect("pack id");
            let other_pack_id =
                pioneer_protocol::SkillPackId::new("Q".repeat(21)).expect("other pack id");
            let empty_pack_id =
                pioneer_protocol::SkillPackId::new("E".repeat(21)).expect("empty pack id");
            let foreign_pack_id =
                pioneer_protocol::SkillPackId::new("F".repeat(21)).expect("foreign pack id");
            for (id, name) in [
                (other_pack_id.clone(), "other-pack"),
                (empty_pack_id.clone(), "empty-pack"),
            ] {
                harness
                    .crud_store
                    .insert_skill_pack_installation(&SkillPackInstallationRecord {
                        pack_id: id,
                        name: name.to_owned(),
                        scope_key: harness.workspace_id.clone(),
                        source_kind: "user".to_owned(),
                        created_at_unix: 1,
                        updated_at_unix: 1,
                    })
                    .await
                    .expect("insert pack");
            }
            harness
                .crud_store
                .insert_skill_pack_installation(&SkillPackInstallationRecord {
                    pack_id: foreign_pack_id.clone(),
                    name: "foreign-pack".to_owned(),
                    scope_key: "workspace_foreign".to_owned(),
                    source_kind: "user".to_owned(),
                    created_at_unix: 1,
                    updated_at_unix: 1,
                })
                .await
                .expect("insert foreign pack");

            let first_id = pioneer_protocol::SkillId::new("A".repeat(21)).expect("first id");
            let second_id = pioneer_protocol::SkillId::new("B".repeat(21)).expect("second id");
            let standalone_id =
                pioneer_protocol::SkillId::new("S".repeat(21)).expect("standalone id");
            let packed_children = [(first_id.clone(), "zeta"), (second_id.clone(), "alpha")].map(
                |(skill_id, member_key)| SkillInstallationRecord {
                    skill_id: skill_id.clone(),
                    owner: None,
                    slug: skill_id.to_string(),
                    version: None,
                    source_kind: "user".to_owned(),
                    scope_key: harness.workspace_id.clone(),
                    source_ref: format!("test:{skill_id}"),
                    install_path: format!("/tmp/{skill_id}"),
                    trust_level: "community".to_owned(),
                    fingerprint: format!("fingerprint:{skill_id}"),
                    updated_at_unix: 1,
                    pack_id: Some(pack_id.clone()),
                    pack_member_key: Some(member_key.to_owned()),
                },
            );
            harness
                .crud_store
                .insert_skill_pack_installation_with_children(
                    &SkillPackInstallationRecord {
                        pack_id: pack_id.clone(),
                        name: "writer-pack".to_owned(),
                        scope_key: harness.workspace_id.clone(),
                        source_kind: "user".to_owned(),
                        created_at_unix: 1,
                        updated_at_unix: 1,
                    },
                    &packed_children,
                )
                .await
                .expect("insert pack and children");
            harness
                .crud_store
                .insert_skill_installation(
                    &SkillInstallationRecord {
                        skill_id: standalone_id.clone(),
                        owner: None,
                        slug: standalone_id.to_string(),
                        version: None,
                        source_kind: "user".to_owned(),
                        scope_key: harness.workspace_id.clone(),
                        source_ref: format!("test:{standalone_id}"),
                        install_path: format!("/tmp/{standalone_id}"),
                        trust_level: "community".to_owned(),
                        fingerprint: format!("fingerprint:{standalone_id}"),
                        updated_at_unix: 1,
                        pack_id: None,
                        pack_member_key: None,
                    },
                    1,
                )
                .await
                .expect("insert standalone skill");

            let full = TurnCapability {
                id: pioneer_protocol::skill_pack_capability_key(&pack_id),
                kind: TurnCapabilityKind::SkillPack {
                    pack_id: pack_id.clone(),
                },
                label: Some("client-pack-label".to_owned()),
            };
            let standalone = TurnCapability {
                id: pioneer_protocol::skill_capability_key(&standalone_id),
                kind: TurnCapabilityKind::Skill {
                    skill_id: standalone_id.clone(),
                    pack_id: None,
                },
                label: Some("standalone".to_owned()),
            };
            let normalized = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[full.clone(), standalone],
                )
                .await
                .expect("normalize full pack");
            assert!(matches!(
                normalized.presentation[0].kind,
                TurnCapabilityKind::SkillPack { .. }
            ));
            let execution_ids = normalized
                .execution
                .iter()
                .filter_map(|capability| match &capability.kind {
                    TurnCapabilityKind::Skill { skill_id, pack_id } => {
                        assert!(pack_id.is_none());
                        Some(skill_id.clone())
                    }
                    _ => None,
                })
                .collect::<Vec<_>>();
            assert_eq!(
                execution_ids,
                vec![second_id.clone(), first_id.clone(), standalone_id]
            );
            assert_eq!(normalized.execution[0].label, None);
            assert_eq!(normalized.execution[1].label, None);
            assert_eq!(normalized.execution[2].label.as_deref(), Some("standalone"));
            let child_failure = harness
                .processor
                .validate_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &normalized.execution[..2],
                )
                .await;
            assert!(
                child_failure.is_err(),
                "one unavailable child must reject the complete expanded pack"
            );

            let duplicate_pack = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[full.clone(), full.clone()],
                )
                .await;
            assert!(duplicate_pack.is_err());

            let duplicate_child = TurnCapability {
                id: pioneer_protocol::skill_capability_key(&first_id),
                kind: TurnCapabilityKind::Skill {
                    skill_id: first_id.clone(),
                    pack_id: Some(pack_id.clone()),
                },
                label: None,
            };
            let duplicate_child_result = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[duplicate_child.clone(), duplicate_child],
                )
                .await;
            assert!(duplicate_child_result.is_err());

            let normalized_child = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[TurnCapability {
                        id: pioneer_protocol::skill_capability_key(&first_id),
                        kind: TurnCapabilityKind::Skill {
                            skill_id: first_id.clone(),
                            pack_id: None,
                        },
                        label: None,
                    }],
                )
                .await
                .expect("normalize legacy packed child");
            assert!(matches!(
                &normalized_child.presentation[0].kind,
                TurnCapabilityKind::Skill {
                    pack_id: Some(actual),
                    ..
                } if actual == &pack_id
            ));
            assert_eq!(normalized_child.execution[0].label, None);

            let mismatch = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[TurnCapability {
                        id: pioneer_protocol::skill_capability_key(&first_id),
                        kind: TurnCapabilityKind::Skill {
                            skill_id: first_id.clone(),
                            pack_id: Some(other_pack_id),
                        },
                        label: None,
                    }],
                )
                .await;
            assert!(mismatch.is_err());

            let mixed = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[
                        full,
                        TurnCapability {
                            id: pioneer_protocol::skill_capability_key(&first_id),
                            kind: TurnCapabilityKind::Skill {
                                skill_id: first_id,
                                pack_id: Some(pack_id.clone()),
                            },
                            label: None,
                        },
                    ],
                )
                .await;
            assert!(mixed.is_err());

            let empty = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[TurnCapability {
                        id: pioneer_protocol::skill_pack_capability_key(&empty_pack_id),
                        kind: TurnCapabilityKind::SkillPack {
                            pack_id: empty_pack_id,
                        },
                        label: None,
                    }],
                )
                .await;
            assert!(empty.is_err());

            let foreign = harness
                .processor
                .normalize_turn_skill_capabilities(
                    harness.workspace_id.as_str(),
                    &[TurnCapability {
                        id: pioneer_protocol::skill_pack_capability_key(&foreign_pack_id),
                        kind: TurnCapabilityKind::SkillPack {
                            pack_id: foreign_pack_id,
                        },
                        label: None,
                    }],
                )
                .await;
            assert!(foreign.is_err());

            let write_guard = harness.processor.acquire_skills_write_lock().await;
            let queued_capabilities = vec![TurnCapability {
                id: pioneer_protocol::skill_pack_capability_key(&pack_id),
                kind: TurnCapabilityKind::SkillPack {
                    pack_id: pack_id.clone(),
                },
                label: None,
            }];
            let queued_normalization = harness.processor.normalize_turn_skill_capabilities(
                harness.workspace_id.as_str(),
                queued_capabilities.as_slice(),
            );
            tokio::pin!(queued_normalization);
            assert!(
                timeout(Duration::from_millis(50), queued_normalization.as_mut())
                    .await
                    .is_err(),
                "turn capability normalization must wait for the shared skills write lock"
            );
            harness
                .crud_store
                .update_skill_pack_installation_name(
                    harness.workspace_id.as_str(),
                    &pack_id,
                    "authoritative-pack-name",
                    2,
                )
                .await
                .expect("rename pack while normalization is queued");
            drop(write_guard);
            let normalized_after_lock = queued_normalization
                .await
                .expect("normalize pack after lifecycle lock release");
            assert_eq!(
                normalized_after_lock
                    .pack_names
                    .get(&pack_id)
                    .map(String::as_str),
                Some("authoritative-pack-name")
            );
        });
}

struct CliRuntimeSkillPreflightHarness {
    _temp: tempfile::TempDir,
    rx: mpsc::Receiver<Message>,
    connection_id: ConnectionId,
    thread_manager: Arc<ThreadManager>,
    crud_store: Arc<CrudStore>,
    workspace_id: String,
    cli_session: Arc<RecordingCliRuntimeSession>,
    cli_manager: Arc<CLIAgentRuntimeManager>,
    processor: MessageProcessor,
    runtime_id: String,
    runtime_kind: CLIAgentRuntimeKind,
    runtime_home: std::path::PathBuf,
    native_home: std::path::PathBuf,
    system_root: std::path::PathBuf,
    user_root: std::path::PathBuf,
    registry_root: std::path::PathBuf,
    event_log: Arc<TokioMutex<Vec<String>>>,
}

async fn setup_cli_runtime_skill_preflight_harness(
    runtime_kind: CLIAgentRuntimeKind,
    native_home_is_file: bool,
) -> CliRuntimeSkillPreflightHarness {
    let temp = tempfile::tempdir().unwrap();
    let runtime_home = temp.path().join("gateway-runtime");
    let native_home = temp.path().join("native-home");
    let system_root = temp.path().join("catalog/system");
    let user_root = temp.path().join("catalog/user");
    let registry_root = temp.path().join("catalog/registry");
    std::fs::create_dir_all(&runtime_home).unwrap();
    if native_home_is_file {
        std::fs::write(&native_home, b"not a directory").unwrap();
    }

    let app_config = pioneer_config::AppConfig::load().unwrap();
    let settings_name = crate::settings::normalize_settings_file_name(
        app_config.gateway.settings_file_name.as_str(),
    )
    .unwrap();
    let settings_path = runtime_home.join(&settings_name);
    let mut settings = crate::settings::load_or_create_gateway_settings(
        &settings_path,
        app_config.gateway.settings_version,
        &settings_name,
    )
    .unwrap();
    let runtime_id = match runtime_kind {
        CLIAgentRuntimeKind::Codex => "codex_proposal_51",
        CLIAgentRuntimeKind::Claude => "claude_proposal_51",
    }
    .to_owned();
    settings
        .set_cli_runtime_settings_for_tests(pioneer_protocol::GatewayCliRuntimeSettings {
            instances: vec![pioneer_protocol::GatewayCliRuntimeInstanceSettings {
                id: runtime_id.clone(),
                kind: runtime_kind,
                display_name: format!("Proposal 51 {runtime_id}"),
                nickname: format!("proposal-51-{runtime_id}"),
                enabled: true,
                binary_path: "recording-runtime".to_owned(),
                home_path: native_home.to_string_lossy().into_owned(),
                shadow_home_path: None,
            }],
        })
        .unwrap();
    crate::settings::save_gateway_settings(&settings_path, &settings).unwrap();

    let (tx, rx) = mpsc::channel(512);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let mut tool_loop_config =
        test_tool_loop_config_with_roots(&system_root, &user_root, temp.path(), &registry_root);
    tool_loop_config.skills.security.allow_untrusted_install = true;
    let cli_manager = test_cli_runtime_manager(cli_session.clone());
    let processor = MessageProcessor::new(
        thread_manager.clone(),
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        tool_loop_config,
    )
    .with_runtime_home_for_tests(runtime_home.clone())
    .with_cli_runtime_manager_for_tests(cli_manager.clone());
    let event_log = processor.cli_runtime_skill_preflight_test_events();
    cli_session.set_event_log(event_log.clone()).await;

    CliRuntimeSkillPreflightHarness {
        _temp: temp,
        rx,
        connection_id,
        thread_manager,
        crud_store,
        workspace_id,
        cli_session,
        cli_manager,
        processor,
        runtime_id,
        runtime_kind,
        runtime_home,
        native_home,
        system_root,
        user_root,
        registry_root,
        event_log,
    }
}

fn cli_runtime_turn_start_request_with_capabilities(
    request_id: &str,
    thread_id: &str,
    turn_id: &str,
    runtime_id: &str,
    runtime_kind: CLIAgentRuntimeKind,
    capabilities: Vec<JsonValue>,
) -> String {
    let mut request: JsonValue = serde_json::from_str(&cli_runtime_turn_start_request(
        request_id,
        thread_id,
        turn_id,
        cli_runtime_execution_backend(runtime_id, runtime_kind),
        "full_access",
        "use selected skill",
        None,
    ))
    .unwrap();
    request["params"]["capabilities"] = JsonValue::Array(capabilities);
    serde_json::from_value::<pioneer_protocol::TurnStartParams>(request["params"].clone())
        .expect("proposal 51 turn/start fixture must match protocol");
    request.to_string()
}

fn cli_runtime_skill_test_id(slug: &str, source_kind: &str) -> pioneer_protocol::SkillId {
    let suffix = match source_kind {
        "system" => 'S',
        "user" => 'U',
        "registry" => 'R',
        other => panic!("unsupported CLI runtime skill source kind `{other}`"),
    };
    let mut value = slug
        .chars()
        .filter(char::is_ascii_alphanumeric)
        .collect::<String>();
    value.truncate(20);
    while value.len() < 20 {
        value.push(suffix);
    }
    value.push(suffix);
    pioneer_protocol::SkillId::new(value).expect("valid CLI runtime skill test ID")
}

fn cli_runtime_skill_capability(slug: &str, source_kind: &str) -> JsonValue {
    let skill_id = cli_runtime_skill_test_id(slug, source_kind);
    serde_json::to_value(pioneer_protocol::TurnCapability {
        id: format!("skill:{skill_id}"),
        kind: pioneer_protocol::TurnCapabilityKind::Skill {
            skill_id,
            pack_id: None,
        },
        label: Some(slug.to_owned()),
    })
    .unwrap()
}

async fn seed_cli_runtime_skill_installation(
    harness: &CliRuntimeSkillPreflightHarness,
    slug: &str,
    source_kind: &str,
    install_path: &std::path::Path,
) -> pioneer_protocol::SkillId {
    let skill_id = cli_runtime_skill_test_id(slug, source_kind);
    harness
        .crud_store
        .insert_skill_installation(
            &SkillInstallationRecord {
                skill_id: skill_id.clone(),
                owner: slug.split_once('/').map(|(owner, _)| owner.to_owned()),
                slug: slug.rsplit('/').next().unwrap_or(slug).to_owned(),
                version: None,
                source_kind: source_kind.to_owned(),
                scope_key: harness.workspace_id.clone(),
                source_ref: format!("test:cli:{source_kind}:{slug}"),
                install_path: install_path.display().to_string(),
                trust_level: if source_kind == "system" {
                    "internal".to_owned()
                } else {
                    "community".to_owned()
                },
                fingerprint: format!("cli-test-fingerprint-{skill_id}"),
                updated_at_unix: 1,
                pack_id: None,
                pack_member_key: None,
            },
            1,
        )
        .await
        .expect("seed CLI runtime skill installation");
    skill_id
}

fn write_test_skill_with_declared_name(
    root: &std::path::Path,
    slug: &str,
    name: &str,
) -> std::path::PathBuf {
    let skill_dir = root.join("tests").join(slug);
    std::fs::create_dir_all(&skill_dir).unwrap();
    std::fs::write(
        skill_dir.join("SKILL.md"),
        format!(
            "---\nname: {name}\nslug: {slug}\ndescription: {slug} description\n---\n# {slug}\n"
        ),
    )
    .unwrap();
    skill_dir
}

async fn seed_cli_runtime_skill_preflight_thread(
    harness: &CliRuntimeSkillPreflightHarness,
    thread_id: &str,
) {
    let started = harness
        .thread_manager
        .thread_start_seeded(
            harness.connection_id,
            harness.workspace_id.clone(),
            ThreadStartParams {
                thread_id: thread_id.to_owned(),
                workspace_id: harness.workspace_id.clone(),
                name: Some("Proposal 51 skill preflight".to_owned()),
                model: Some(
                    match harness.runtime_kind {
                        CLIAgentRuntimeKind::Codex => "o4-mini",
                        CLIAgentRuntimeKind::Claude => "claude-sonnet",
                    }
                    .to_owned(),
                ),
                model_provider: Some("openai".to_owned()),
                sandbox: Some(SandboxMode::FullAccess),
                mode: Some(ThreadMode::Agent),
                origin_kind: None,
                sidebar_visibility: None,
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await
        .unwrap();
    harness
        .crud_store
        .upsert_thread_model(
            &started.response.thread,
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("persist CLI runtime skill preflight authorization root");
}

#[test]
fn capability_persistence_order_materializes_before_skill_install_and_native_start() {
    tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .enable_all()
        .build()
        .expect("capability persistence order test runtime should build")
        .block_on(async {
            tokio::spawn(capability_persistence_order_impl())
                .await
                .expect("capability persistence order test task should finish");
        });
}

fn run_standard_stack_message_test<F>(name: &'static str, future: F)
where
    F: std::future::Future<Output = ()> + Send + 'static,
{
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(2)
        .thread_stack_size(8 * 1024 * 1024)
        .enable_all()
        .build()
        .unwrap_or_else(|error| panic!("{name} runtime should build: {error}"));
    let result = runtime.block_on(async move { tokio::spawn(future).await });
    // Test futures may leave best-effort blocking index work behind. Give it
    // a bounded grace period instead of waiting indefinitely during shutdown.
    runtime.shutdown_timeout(Duration::from_secs(5));
    result.unwrap_or_else(|error| panic!("{name} task should finish: {error}"));
}

async fn capability_persistence_order_impl() {
    for runtime_kind in [CLIAgentRuntimeKind::Codex, CLIAgentRuntimeKind::Claude] {
        let harness = setup_cli_runtime_skill_preflight_harness(runtime_kind, false).await;
        let alpha_path = write_test_skill(&harness.user_root, "alpha", "", "# alpha\n");
        let beta_path = write_test_skill(&harness.registry_root, "beta", "", "# beta\n");
        let alpha_id = seed_cli_runtime_skill_installation(
            &harness,
            "tests/alpha",
            "user",
            alpha_path.as_path(),
        )
        .await;
        let beta_id = seed_cli_runtime_skill_installation(
            &harness,
            "tests/beta",
            "registry",
            beta_path.as_path(),
        )
        .await;
        let thread_id = format!("thread_preflight_{runtime_kind:?}").to_ascii_lowercase();
        let turn_id = format!("turn_preflight_{runtime_kind:?}").to_ascii_lowercase();
        seed_cli_runtime_skill_preflight_thread(&harness, &thread_id).await;
        harness
            .processor
            .agent_manager
            .ensure_thread(&thread_id, &harness.workspace_id)
            .await
            .expect("agent thread should be registered for committed subscription");
        let mut committed_rx = harness
            .processor
            .agent_manager
            .subscribe_committed(&thread_id)
            .await
            .expect("committed subscription should exist");
        let request_id = generate_test_request_id(
            "p51order",
            match runtime_kind {
                CLIAgentRuntimeKind::Codex => "codex",
                CLIAgentRuntimeKind::Claude => "claude",
            },
        );
        let request = cli_runtime_turn_start_request_with_capabilities(
            &request_id,
            &thread_id,
            &turn_id,
            &harness.runtime_id,
            runtime_kind,
            vec![
                cli_runtime_skill_capability("tests/beta", "registry"),
                cli_runtime_skill_capability("tests/alpha", "user"),
            ],
        );
        harness
            .processor
            .process_request_for_connection(harness.connection_id, &request)
            .await;
        let native_turn = wait_for_recorded_cli_runtime_turn_start(&harness.cli_session).await;

        assert_eq!(
            harness.event_log.lock().await.as_slice(),
            [
                "thread_manager_turn_start",
                "preflight_complete",
                "native_thread_start"
            ]
        );
        assert_eq!(
            std::fs::read(harness.native_home.join("skills/alpha/SKILL.md")).unwrap(),
            std::fs::read(harness.user_root.join("tests/alpha/SKILL.md")).unwrap()
        );
        assert_eq!(
            std::fs::read(harness.native_home.join("skills/beta/SKILL.md")).unwrap(),
            std::fs::read(harness.registry_root.join("tests/beta/SKILL.md")).unwrap()
        );
        assert!(
            harness
                .runtime_home
                .join(pioneer_skills::EXTERNAL_RUNTIME_RECEIPT_FILE_NAME)
                .exists()
        );
        assert!(
            harness
                .crud_store
                .get_turn(&thread_id, &turn_id)
                .await
                .unwrap()
                .is_some()
        );
        let skill_bindings = harness
            .crud_store
            .find_turn_skill_bindings(&turn_id)
            .await
            .expect("must read persisted CLI runtime turn skill bindings");
        assert_eq!(skill_bindings.len(), 2);
        assert_eq!(skill_bindings[0].skill_id, alpha_id);
        assert_eq!(skill_bindings[0].skill_owner.as_deref(), Some("tests"));
        assert_eq!(skill_bindings[0].skill_slug, "alpha");
        assert_eq!(skill_bindings[0].source_kind, "user");
        assert_eq!(
            skill_bindings[0].resolved_reason,
            "explicit_composer_capability"
        );
        assert_eq!(skill_bindings[1].skill_id, beta_id);
        assert_eq!(skill_bindings[1].skill_owner.as_deref(), Some("tests"));
        assert_eq!(skill_bindings[1].skill_slug, "beta");
        assert_eq!(skill_bindings[1].source_kind, "registry");
        assert_eq!(
            skill_bindings[1].resolved_reason,
            "explicit_composer_capability"
        );
        assert!(
            skill_bindings
                .iter()
                .all(|binding| !binding.fingerprint.is_empty())
        );
        let committed_capabilities = timeout(Duration::from_secs(1), committed_rx.recv())
            .await
            .expect("committed empty MCP capability event should arrive")
            .expect("committed lane should stay open");
        assert!(matches!(
            committed_capabilities,
            AgentDurableEvent::TurnCapabilitiesResolved {
                turn_id: committed_turn_id,
                accepted,
                rejected,
                mcp_bindings,
                ..
            } if committed_turn_id == turn_id
                && accepted.is_empty()
                && rejected.is_empty()
                && mcp_bindings.is_empty()
        ));
        let committed_skills = timeout(Duration::from_secs(1), committed_rx.recv())
            .await
            .expect("committed skill binding event should arrive")
            .expect("committed lane should stay open");
        assert!(matches!(
            committed_skills,
            AgentDurableEvent::TurnSkillsResolved {
                turn_id: committed_turn_id,
                bindings,
                ..
            } if committed_turn_id == turn_id && bindings.len() == 2
        ));
        if matches!(runtime_kind, CLIAgentRuntimeKind::Codex) {
            let input = native_turn.input.as_array().unwrap();
            let skill_items = input
                .iter()
                .filter(|item| item["type"] == "skill")
                .cloned()
                .collect::<Vec<_>>();
            assert_eq!(
                skill_items,
                vec![
                    json!({
                        "type": "skill",
                        "name": "beta",
                        "path": harness.native_home.join("skills/beta/SKILL.md")
                    }),
                    json!({
                        "type": "skill",
                        "name": "alpha",
                        "path": harness.native_home.join("skills/alpha/SKILL.md")
                    }),
                ]
            );
            let instructions = native_turn.elevated_instructions.text();
            assert!(instructions.contains("native Codex skill"));
            let beta = instructions
                .find("- $beta")
                .expect("Codex elevated instructions should include beta");
            let alpha = instructions
                .find("- $alpha")
                .expect("Codex elevated instructions should include alpha");
            assert!(beta < alpha, "selected Codex skill order must be preserved");
            assert!(input.iter().all(|item| {
                item["type"] != "text"
                    || item["text"]
                        .as_str()
                        .is_none_or(|text| !text.contains("native Codex skill"))
            }));
        } else {
            let input = native_turn.input.as_array().unwrap();
            assert!(input.iter().all(|item| item["type"] != "skill"));
            let instructions = native_turn.elevated_instructions.text();
            assert!(instructions.contains("native Skill tool"));
            let beta = instructions
                .find("- beta")
                .expect("Claude elevated instructions should include beta");
            let alpha = instructions
                .find("- alpha")
                .expect("Claude elevated instructions should include alpha");
            assert!(
                beta < alpha,
                "selected Claude skill order must be preserved"
            );
            assert!(input.iter().all(|item| {
                item["type"] != "text"
                    || item["text"]
                        .as_str()
                        .is_none_or(|text| !text.contains("native Skill tool"))
            }));
        }
    }
}

#[test]
fn gateway_cli_skill_full_turn_first_noop_update_and_zero_skill_matrix() {
    run_standard_stack_message_test(
        "gateway CLI skill full-turn matrix test",
        gateway_cli_skill_full_turn_first_noop_update_and_zero_skill_matrix_impl(),
    );
}

async fn gateway_cli_skill_full_turn_first_noop_update_and_zero_skill_matrix_impl() {
    for runtime_kind in [CLIAgentRuntimeKind::Codex, CLIAgentRuntimeKind::Claude] {
        let harness = setup_cli_runtime_skill_preflight_harness(runtime_kind, false).await;
        let source = write_test_skill(&harness.user_root, "lifecycle", "", "# first\n");
        let lifecycle_id = seed_cli_runtime_skill_installation(
            &harness,
            "tests/lifecycle",
            "user",
            source.as_path(),
        )
        .await;
        std::fs::create_dir_all(source.join("references")).unwrap();
        std::fs::write(source.join("references/guide.txt"), b"guide-v1\n").unwrap();
        let receipt_path = harness
            .runtime_home
            .join(pioneer_skills::EXTERNAL_RUNTIME_RECEIPT_FILE_NAME);
        let destination = harness.native_home.join("skills/lifecycle");
        let mut first_receipt_snapshot = None;
        let mut first_destination_snapshot = None;

        for (index, expected_turn_count) in [(1, 1), (2, 2)] {
            let thread_id = format!("thread_full_turn_{runtime_kind:?}_{index}").to_lowercase();
            let turn_id = format!("turn_full_turn_{runtime_kind:?}_{index}").to_lowercase();
            seed_cli_runtime_skill_preflight_thread(&harness, &thread_id).await;
            let request_id =
                generate_test_request_id("p51full", format!("{runtime_kind:?}{index}").as_str());
            let request = cli_runtime_turn_start_request_with_capabilities(
                &request_id,
                &thread_id,
                &turn_id,
                &harness.runtime_id,
                runtime_kind,
                vec![cli_runtime_skill_capability("tests/lifecycle", "user")],
            );
            harness
                .processor
                .process_request_for_connection(harness.connection_id, &request)
                .await;
            wait_for_recorded_cli_runtime_turn_count(&harness.cli_session, expected_turn_count)
                .await;
            let bindings = harness
                .crud_store
                .find_turn_skill_bindings(&turn_id)
                .await
                .expect("must read persisted CLI runtime turn skill bindings");
            assert_eq!(bindings.len(), 1);
            assert_eq!(bindings[0].skill_id, lifecycle_id);
            assert_eq!(bindings[0].skill_owner.as_deref(), Some("tests"));
            assert_eq!(bindings[0].skill_slug, "lifecycle");
            assert_eq!(bindings[0].source_kind, "user");
            assert_eq!(bindings[0].resolved_reason, "explicit_composer_capability");
            assert!(!bindings[0].fingerprint.is_empty());
            let receipt_snapshot = std::fs::read(&receipt_path).unwrap();
            let destination_snapshot = std::fs::read(destination.join("SKILL.md")).unwrap();
            if index == 1 {
                first_receipt_snapshot = Some(receipt_snapshot);
                first_destination_snapshot = Some(destination_snapshot);
            } else {
                assert_eq!(Some(receipt_snapshot), first_receipt_snapshot);
                assert_eq!(Some(destination_snapshot), first_destination_snapshot);
            }
        }

        let first_receipt_bytes = first_receipt_snapshot.unwrap();
        let first_receipt = pioneer_skills::read_external_runtime_receipt(&receipt_path).unwrap();
        assert_eq!(first_receipt.entries.len(), 1);
        assert_eq!(first_receipt.entries[0].skill_id, lifecycle_id);
        assert_eq!(first_receipt.entries[0].owner.as_deref(), Some("tests"));
        assert_eq!(first_receipt.entries[0].slug, "lifecycle");
        assert_eq!(first_receipt.entries[0].install_name, "lifecycle");
        assert_eq!(
            first_receipt.entries[0].native_skills_root,
            harness
                .native_home
                .join("skills")
                .to_string_lossy()
                .into_owned()
        );
        assert_eq!(
            std::fs::read(destination.join("SKILL.md")).unwrap(),
            std::fs::read(source.join("SKILL.md")).unwrap()
        );
        assert_eq!(
            std::fs::read(destination.join("references/guide.txt")).unwrap(),
            b"guide-v1\n"
        );
        assert_eq!(std::fs::read(&receipt_path).unwrap(), first_receipt_bytes);

        sleep(Duration::from_millis(2)).await;
        std::fs::write(
            source.join("SKILL.md"),
            b"---\nname: lifecycle\nslug: lifecycle\ndescription: updated\n---\n# updated\n",
        )
        .unwrap();
        std::fs::write(source.join("references/guide.txt"), b"guide-v2\n").unwrap();
        let update_thread = format!("thread_full_turn_{runtime_kind:?}_3").to_lowercase();
        let update_turn = format!("turn_full_turn_{runtime_kind:?}_3").to_lowercase();
        seed_cli_runtime_skill_preflight_thread(&harness, &update_thread).await;
        let update_request_id = generate_test_request_id("p51full", "update");
        let update_request = cli_runtime_turn_start_request_with_capabilities(
            &update_request_id,
            &update_thread,
            &update_turn,
            &harness.runtime_id,
            runtime_kind,
            vec![cli_runtime_skill_capability("tests/lifecycle", "user")],
        );
        harness
            .processor
            .process_request_for_connection(harness.connection_id, &update_request)
            .await;
        wait_for_recorded_cli_runtime_turn_count(&harness.cli_session, 3).await;
        let updated_bindings = harness
            .crud_store
            .find_turn_skill_bindings(&update_turn)
            .await
            .expect("must read updated CLI runtime turn skill bindings");
        assert_eq!(updated_bindings.len(), 1);
        assert_eq!(updated_bindings[0].skill_id, lifecycle_id);
        assert_eq!(updated_bindings[0].skill_slug, "lifecycle");

        let updated_receipt = pioneer_skills::read_external_runtime_receipt(&receipt_path).unwrap();
        assert_ne!(
            updated_receipt.entries[0].source_folder_hash,
            first_receipt.entries[0].source_folder_hash
        );
        assert_eq!(
            std::fs::read(destination.join("SKILL.md")).unwrap(),
            std::fs::read(source.join("SKILL.md")).unwrap()
        );
        assert_eq!(
            std::fs::read(destination.join("references/guide.txt")).unwrap(),
            b"guide-v2\n"
        );

        let receipt_after_update = std::fs::read(&receipt_path).unwrap();
        let destination_after_update = std::fs::read(destination.join("SKILL.md")).unwrap();
        let zero_thread = format!("thread_full_turn_{runtime_kind:?}_zero").to_lowercase();
        let zero_turn = format!("turn_full_turn_{runtime_kind:?}_zero").to_lowercase();
        seed_cli_runtime_skill_preflight_thread(&harness, &zero_thread).await;
        let zero_request_id = generate_test_request_id("p51full", "zero");
        let zero_request = cli_runtime_turn_start_request_with_capabilities(
            &zero_request_id,
            &zero_thread,
            &zero_turn,
            &harness.runtime_id,
            runtime_kind,
            Vec::new(),
        );
        harness
            .processor
            .process_request_for_connection(harness.connection_id, &zero_request)
            .await;
        wait_for_recorded_cli_runtime_turn_count(&harness.cli_session, 4).await;
        assert!(
            harness
                .crud_store
                .find_turn_skill_bindings(&zero_turn)
                .await
                .expect("must read zero-skill CLI runtime turn bindings")
                .is_empty()
        );
        assert_eq!(std::fs::read(&receipt_path).unwrap(), receipt_after_update);
        assert_eq!(
            std::fs::read(destination.join("SKILL.md")).unwrap(),
            destination_after_update
        );
    }
}

