#[test]
fn cli_runtime_skill_preflight_collision_and_copy_failure_do_not_start_turn() {
    run_standard_stack_message_test(
        "CLI skill preflight failure test",
        cli_runtime_skill_preflight_collision_and_copy_failure_do_not_start_turn_impl(),
    );
}

async fn cli_runtime_skill_preflight_collision_and_copy_failure_do_not_start_turn_impl() {
    let mut collision =
        setup_cli_runtime_skill_preflight_harness(CLIAgentRuntimeKind::Codex, false).await;
    let first_path =
        write_test_skill_with_declared_name(&collision.user_root, "first", "same skill");
    let second_path =
        write_test_skill_with_declared_name(&collision.registry_root, "second", "same@skill");
    seed_cli_runtime_skill_installation(&collision, "tests/first", "user", first_path.as_path())
        .await;
    seed_cli_runtime_skill_installation(
        &collision,
        "tests/second",
        "registry",
        second_path.as_path(),
    )
    .await;
    seed_cli_runtime_skill_preflight_thread(&collision, "thread_collision_preflight").await;
    let collision_request_id = generate_test_request_id("p51collision", "fail");
    let request = cli_runtime_turn_start_request_with_capabilities(
        &collision_request_id,
        "thread_collision_preflight",
        "turn_collision_preflight",
        &collision.runtime_id,
        collision.runtime_kind,
        vec![
            cli_runtime_skill_capability("tests/first", "user"),
            cli_runtime_skill_capability("tests/second", "registry"),
        ],
    );
    collision
        .processor
        .process_request_for_connection(collision.connection_id, &request)
        .await;
    let error = recv_error_by_id(&mut collision.rx, &collision_request_id).await;
    assert_public_error(
        &error,
        PublicErrorCode::Internal,
        PublicErrorStage::Admission,
    );
    assert!(!collision.native_home.join("skills").exists());
    assert!(collision.cli_session.thread_starts.lock().await.is_empty());
    assert!(
        collision
            .crud_store
            .get_turn("thread_collision_preflight", "turn_collision_preflight")
            .await
            .unwrap()
            .is_none()
    );

    let mut copy_failure =
        setup_cli_runtime_skill_preflight_harness(CLIAgentRuntimeKind::Codex, true).await;
    let copy_failure_path = write_test_skill(
        &copy_failure.user_root,
        "copy-failure",
        "",
        "# copy failure\n",
    );
    seed_cli_runtime_skill_installation(
        &copy_failure,
        "tests/copy-failure",
        "user",
        copy_failure_path.as_path(),
    )
    .await;
    seed_cli_runtime_skill_preflight_thread(&copy_failure, "thread_copy_failure_preflight").await;
    let copy_request_id = generate_test_request_id("p51copy", "failure");
    let request = cli_runtime_turn_start_request_with_capabilities(
        &copy_request_id,
        "thread_copy_failure_preflight",
        "turn_copy_failure_preflight",
        &copy_failure.runtime_id,
        copy_failure.runtime_kind,
        vec![cli_runtime_skill_capability("tests/copy-failure", "user")],
    );
    copy_failure
        .processor
        .process_request_for_connection(copy_failure.connection_id, &request)
        .await;
    let error = recv_error_by_id(&mut copy_failure.rx, &copy_request_id).await;
    assert_public_error(
        &error,
        PublicErrorCode::Internal,
        PublicErrorStage::Admission,
    );
    assert!(
        copy_failure
            .cli_session
            .thread_starts
            .lock()
            .await
            .is_empty()
    );
    assert_eq!(
        copy_failure.event_log.lock().await.as_slice(),
        ["thread_manager_turn_start"]
    );
    let (_workspace_id, blocked_turn) = copy_failure
        .crud_store
        .get_turn(
            "thread_copy_failure_preflight",
            "turn_copy_failure_preflight",
        )
        .await
        .expect("copy failure turn should load")
        .expect("copy failure turn should remain durable");
    assert_eq!(blocked_turn.status, TurnStatus::Blocked);
    assert!(
        blocked_turn
            .error
            .as_deref()
            .is_some_and(|error| error.contains("failed to prepare CLI runtime skill"))
    );
}

#[test]
fn cli_runtime_skill_preflight_mcp_and_resolver_failures_have_zero_side_effects() {
    run_standard_stack_message_test(
        "combined CLI preflight failure test",
        cli_runtime_skill_preflight_mcp_and_resolver_failures_have_zero_side_effects_impl(),
    );
}

async fn cli_runtime_skill_preflight_mcp_and_resolver_failures_have_zero_side_effects_impl() {
    for (suffix, capabilities, expected_code) in [
        (
            "mcp",
            vec![
                serde_json::to_value(pioneer_protocol::TurnCapability {
                    id: "mcp-server:workspace:server".to_owned(),
                    kind: pioneer_protocol::TurnCapabilityKind::McpServer {
                        name: "server".to_owned(),
                        scope_kind: McpScopeKind::Workspace,
                    },
                    label: None,
                })
                .unwrap(),
            ],
            PublicErrorCode::Internal,
        ),
        (
            "missing",
            vec![cli_runtime_skill_capability("tests/missing", "user")],
            PublicErrorCode::InvalidInput,
        ),
    ] {
        let mut harness =
            setup_cli_runtime_skill_preflight_harness(CLIAgentRuntimeKind::Codex, false).await;
        let thread_id = format!("thread_{suffix}_preflight");
        let turn_id = format!("turn_{suffix}_preflight");
        let request_id = generate_test_request_id("p51failure", suffix);
        seed_cli_runtime_skill_preflight_thread(&harness, &thread_id).await;
        let request = cli_runtime_turn_start_request_with_capabilities(
            &request_id,
            &thread_id,
            &turn_id,
            &harness.runtime_id,
            harness.runtime_kind,
            capabilities,
        );
        harness
            .processor
            .process_request_for_connection(harness.connection_id, &request)
            .await;
        let error = recv_error_by_id(&mut harness.rx, &request_id).await;
        assert_public_error(&error, expected_code, PublicErrorStage::Admission);
        assert!(harness.cli_session.thread_starts.lock().await.is_empty());
        assert!(harness.cli_session.turn_starts.lock().await.is_empty());
        assert!(harness.event_log.lock().await.is_empty());
        assert!(!harness.native_home.join("skills").exists());
        assert!(
            !harness
                .runtime_home
                .join(pioneer_skills::EXTERNAL_RUNTIME_RECEIPT_FILE_NAME)
                .exists()
        );
        assert!(
            harness
                .crud_store
                .get_turn(&thread_id, &turn_id)
                .await
                .unwrap()
                .is_none()
        );
    }
}

async fn seed_cli_runtime_security_thread(
    harness: &CliRuntimeSecurityHarness,
    thread_id: &str,
    name: &str,
    model: &str,
    model_provider: &str,
    sandbox: Option<SandboxMode>,
) {
    let started = harness
        .thread_manager
        .thread_start_seeded(
            harness.connection_id,
            harness.workspace_id.clone(),
            ThreadStartParams {
                thread_id: thread_id.to_owned(),
                workspace_id: harness.workspace_id.clone(),
                name: Some(name.to_owned()),
                model: Some(model.to_owned()),
                model_provider: Some(model_provider.to_owned()),
                sandbox,
                mode: Some(ThreadMode::Agent),
                origin_kind: None,
                sidebar_visibility: None,
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await
        .expect("thread/start should seed CLI runtime security regression thread");
    harness
        .crud_store
        .upsert_thread_model(
            &started.response.thread,
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("persist CLI runtime security authorization root");
}

async fn seed_vertical_self_improvement_thread(
    harness: &mut CliRuntimeSecurityHarness,
    thread_id: &str,
    name: &str,
    model: &str,
    model_provider: &str,
    origin_kind: ThreadOriginKind,
) {
    let request_id = generate_test_request_id("verticalthread", thread_id);
    harness
        .processor
        .process_request_for_connection(
            harness.connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id.clone(),
                "method": "thread/start",
                "params": {
                    "thread_id": thread_id,
                    "workspace_id": harness.workspace_id.as_str(),
                    "name": name,
                    "model": model,
                    "model_provider": model_provider,
                    "sandbox": SandboxMode::FullAccess,
                    "mode": "Agent",
                    "origin_kind": origin_kind,
                    "sidebar_visibility": "visible",
                    "visibility": "workspace"
                }
            })
            .to_string(),
        )
        .await;
    let response = recv_response_by_id(&mut harness.rx, request_id.as_str()).await;
    let started: ThreadStartResponse =
        serde_json::from_value(response.result).expect("vertical thread/start must decode");
    assert_eq!(started.thread.id, thread_id);
    assert_eq!(started.thread.origin_kind, origin_kind);
    assert_eq!(
        started.thread.visibility,
        Some(pioneer_protocol::ThreadVisibility::Workspace),
        "self-improvement vertical source runtime draft must be explicitly workspace-visible"
    );
}

fn cli_runtime_execution_backend(runtime_id: &str, runtime_kind: CLIAgentRuntimeKind) -> JsonValue {
    serde_json::to_value(AgentExecutionBackend::CLIAgentRuntime {
        runtime_id: runtime_id.to_owned(),
        runtime_kind,
    })
    .expect("execution backend should serialize")
}

fn cli_runtime_turn_start_request(
    request_id: &str,
    thread_id: &str,
    turn_id: &str,
    execution_backend: JsonValue,
    permission_mode: &str,
    text: &str,
    cli_runtime_options: Option<JsonValue>,
) -> String {
    let mut params = json!({
        "thread_id": thread_id,
        "turn_id": turn_id,
        "mode": "Agent",
        "execution_backend": execution_backend,
        "permission_profile": {
            "mode": permission_mode
        },
        "input": [{
            "type": "text",
            "text": text
        }]
    });
    if let Some(options) = cli_runtime_options {
        params["cli_runtime_options"] = options;
    }
    json!({
        "jsonrpc": "2.0",
        "id": request_id,
        "method": "turn/start",
        "params": params
    })
    .to_string()
}

async fn process_cli_runtime_turn_start(
    harness: &CliRuntimeSecurityHarness,
    turn_start_request: &str,
) {
    harness
        .processor
        .process_request_for_connection(harness.connection_id, turn_start_request)
        .await;
}

async fn assert_cli_runtime_start_sandbox_none(
    cli_session: &RecordingCliRuntimeSession,
    expected_approval_policy: &str,
) {
    let thread_starts = cli_session.thread_starts.lock().await;
    assert_eq!(thread_starts.len(), 1);
    assert_eq!(
        thread_starts[0].approval_policy.as_deref(),
        Some(expected_approval_policy)
    );
    assert!(thread_starts[0].sandbox.is_none());
    drop(thread_starts);

    let turn_start = wait_for_recorded_cli_runtime_turn_start(cli_session).await;
    assert_eq!(
        turn_start.approval_policy.as_deref(),
        Some(expected_approval_policy)
    );
    assert!(turn_start.sandbox.is_none());
}

async fn wait_for_recorded_cli_runtime_turn_start(
    cli_session: &RecordingCliRuntimeSession,
) -> CLIAgentRuntimeTurnStartParams {
    timeout(Duration::from_secs(2), async {
        loop {
            if let Some(turn_start) = cli_session.turn_starts.lock().await.first().cloned() {
                return turn_start;
            }
            sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .expect("CLI runtime turn/start should be recorded")
}

async fn wait_for_recorded_cli_runtime_turn_count(
    cli_session: &RecordingCliRuntimeSession,
    expected: usize,
) {
    timeout(Duration::from_secs(2), async {
        loop {
            if cli_session.turn_starts.lock().await.len() >= expected {
                return;
            }
            sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .unwrap_or_else(|_| panic!("expected {expected} recorded CLI runtime turn starts"));
}

