fn ready_gateway_voice_supervisor(
    transcript: &str,
) -> Arc<crate::voice::supervisor::VoiceInputSupervisor> {
    let supervisor = test_gateway_voice_supervisor();
    let desired = crate::voice::supervisor::VoiceInputDesiredState {
        enabled: true,
        provider: Some(pioneer_protocol::GatewayVoiceInputProvider::Local),
        model: Some("parakeet-tdt-0.6b-v3".to_owned()),
    };
    let applied = supervisor
        .apply_desired(desired, false)
        .expect("ready test desired state");
    supervisor
        .mark_loading(applied.generation)
        .expect("ready test loading transition");
    supervisor
        .mark_ready(
            applied.generation,
            crate::voice::supervisor::VoiceModelIdentity {
                provider: pioneer_protocol::GatewayVoiceInputProvider::Local,
                model: "parakeet-tdt-0.6b-v3".to_owned(),
            },
            crate::voice::runtime::LoadedVoiceEngine::test_stub_with_transcript(transcript),
        )
        .expect("ready test Ready transition");
    supervisor
}

fn test_gateway_voice_supervisor() -> Arc<crate::voice::supervisor::VoiceInputSupervisor> {
    Arc::new(crate::voice::supervisor::VoiceInputSupervisor::new(
        Arc::new(TestGatewayVoiceInstaller),
        Arc::new(TestGatewayVoiceEngineLoader),
    ))
}

async fn submit_test_voice_turn(
    processor: &MessageProcessor,
    connection_id: ConnectionId,
    rx: &mut mpsc::Receiver<Message>,
    workspace_id: &str,
    thread_id: &str,
    turn_id: &str,
) -> VoiceSessionResultNotification {
    let start_request_id = generate_test_request_id("voice_policy", turn_id);
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": start_request_id,
                "method": "voice/session/start",
                "params": {
                    "context": {
                        "workspace_id": workspace_id,
                        "thread_id": thread_id,
                        "turn_id": turn_id
                    },
                    "audio_format": {
                        "sample_rate_hz": 16000,
                        "channels": 1,
                        "encoding": "pcm_s16_le"
                    }
                }
            })
            .to_string(),
        )
        .await;
    let start_response = recv_response_by_id(rx, start_request_id.as_str()).await;
    let start_payload: pioneer_protocol::VoiceSessionStartResponse =
        serde_json::from_value(start_response.result).expect("voice/session/start decode");
    assert_eq!(start_payload.status, VoiceStatus::Recording);

    processor
        .process_binary_frame_for_connection(
            connection_id,
            voice_test_frame(start_payload.session_id.as_str(), 0, 960, 12_000).as_slice(),
        )
        .await
        .expect("registered voice connection");
    let _ = recv_notification_by_method(rx, events::VOICE_CHUNK_ACK).await;

    let finalize_request_id = generate_test_request_id("voice_policy_finalize", turn_id);
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": finalize_request_id,
                "method": "voice/session/finalize",
                "params": {
                    "session_id": start_payload.session_id,
                    "context": {
                        "workspace_id": workspace_id,
                        "thread_id": thread_id,
                        "turn_id": turn_id
                    }
                }
            })
            .to_string(),
        )
        .await;
    let finalize_response = recv_response_by_id(rx, finalize_request_id.as_str()).await;
    let finalize_payload: pioneer_protocol::VoiceSessionFinalizeResponse =
        serde_json::from_value(finalize_response.result).expect("voice/session/finalize decode");
    assert_eq!(finalize_payload.status, VoiceStatus::Transcribing);

    let result = recv_notification_by_method(rx, events::VOICE_SESSION_RESULT).await;
    serde_json::from_value(result.params.expect("voice/session/result params"))
        .expect("voice/session/result decode")
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn first_voice_turn_materializes_runtime_draft() {
    let (tx, mut rx) = mpsc::channel(64);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_voice_input_supervisor(ready_gateway_voice_supervisor("first voice message"));
    let thread_id = "thr_first_voice_runtime_draft";
    let turn_id = "turn_first_voice_runtime_draft";

    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": "firstvoicedraftstart1",
                "method": "thread/start",
                "params": {
                    "thread_id": thread_id,
                    "workspace_id": workspace_id
                }
            })
            .to_string(),
        )
        .await;
    let _ = recv_response_by_id(&mut rx, "firstvoicedraftstart1").await;
    let _ = recv_notification_by_method(&mut rx, events::THREAD_STARTED).await;
    assert!(
        crud_store
            .get_thread_model(thread_id)
            .await
            .expect("voice draft lookup should succeed")
            .is_none(),
        "voice draft must remain in memory before transcription submits its first turn"
    );

    let result = submit_test_voice_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        thread_id,
        turn_id,
    )
    .await;
    assert_eq!(
        result.outcome,
        VoiceSessionOutcome::TurnStarted,
        "voice execution failed: {:?}",
        result.error
    );
    assert_eq!(result.turn_id.as_deref(), Some(turn_id));
    assert!(
        crud_store
            .get_thread_model(thread_id)
            .await
            .expect("materialized voice thread lookup should succeed")
            .is_some(),
        "the first voice turn must materialize its runtime draft"
    );
    assert!(
        crud_store
            .get_turn(thread_id, turn_id)
            .await
            .expect("materialized voice turn lookup should succeed")
            .is_some(),
        "the thread and first voice turn must commit together"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn voice_turn_start_replay_does_not_dispatch_provider_again() {
    let (tx, mut rx) = mpsc::channel(128);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let provider = Arc::new(CaptureSummaryProvider::new("voice replay answer"));
    let processor = MessageProcessor::new(
        thread_manager.clone(),
        Arc::new(pioneer_provider::ProviderRegistry::with_provider(
            "openai",
            provider.clone(),
        )),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_voice_input_supervisor(ready_gateway_voice_supervisor("same durable voice request"));
    let thread_id = "thr_voice_admission_replay";
    let turn_id = "turn_voice_admission_replay";
    let started = thread_manager
        .thread_start_seeded(
            connection_id,
            workspace_id.clone(),
            ThreadStartParams {
                thread_id: thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                name: None,
                model: Some("test-model".to_owned()),
                model_provider: Some("openai".to_owned()),
                sandbox: None,
                mode: Some(ThreadMode::Agent),
                origin_kind: Some(ThreadOriginKind::User),
                sidebar_visibility: Some(ThreadSidebarVisibility::Visible),
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await;
    let started = started.expect("voice replay TaskRun thread should start");
    crud_store
        .upsert_thread_model(
            &started.response.thread,
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("persist voice replay authorization target");

    let first = submit_test_voice_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        thread_id,
        turn_id,
    )
    .await;
    assert_eq!(first.outcome, VoiceSessionOutcome::TurnStarted);
    let first_status = wait_for_turn_status(
        crud_store.clone(),
        thread_id,
        turn_id,
        TurnStatus::Completed,
    )
    .await;
    assert_eq!(
        first_status,
        TurnStatus::Completed,
        "voice Turn did not finish: provider_calls={}, finalization_intent={:?}",
        provider.call_count(),
        crud_store.has_turn_finalization_intent(turn_id).await
    );
    let provider_calls_after_first_turn = provider.call_count();
    assert!(provider_calls_after_first_turn > 0);

    let replay = submit_test_voice_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        thread_id,
        turn_id,
    )
    .await;
    assert_eq!(replay.outcome, VoiceSessionOutcome::TurnStarted);
    assert_eq!(replay.turn_id.as_deref(), Some(turn_id));
    assert_eq!(
        provider.call_count(),
        provider_calls_after_first_turn,
        "an exact voice admission replay must not start a second provider execution"
    );

    let (_, turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("voice replay Turn lookup should succeed")
        .expect("voice replay Turn should exist");
    assert_eq!(turn.status, TurnStatus::Completed);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn collaborative_voice_composer_admits_detached_task() {
    let (tx, mut rx) = mpsc::channel(128);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let provider = Arc::new(CaptureSummaryProvider::new("must run in child"));
    let processor = MessageProcessor::new(
        thread_manager.clone(),
        Arc::new(pioneer_provider::ProviderRegistry::with_provider(
            "openai",
            provider.clone(),
        )),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_voice_input_supervisor(ready_gateway_voice_supervisor(
        "run this voice command asynchronously",
    ));
    let parent_thread_id = "thr_voice_collaborative";
    let started = thread_manager
        .thread_start_seeded(
            connection_id,
            workspace_id.clone(),
            ThreadStartParams {
                thread_id: parent_thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                name: None,
                model: Some("test-model".to_owned()),
                model_provider: Some("openai".to_owned()),
                sandbox: None,
                mode: Some(ThreadMode::Agent),
                origin_kind: Some(ThreadOriginKind::Collaborative),
                sidebar_visibility: Some(ThreadSidebarVisibility::Visible),
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await
        .expect("collaborative thread should start");
    crud_store
        .upsert_thread_model(
            &started.response.thread,
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("persist collaborative voice authorization root");

    let turn_id = "turn_voice_detached";
    let result = submit_test_voice_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        parent_thread_id,
        turn_id,
    )
    .await;
    assert_eq!(result.outcome, VoiceSessionOutcome::TurnStarted);
    assert_eq!(result.turn_id.as_deref(), Some(turn_id));

    let tasks = processor
        .task_runtime
        .service()
        .list_tasks(TaskListParams {
            workspace_id: workspace_id.clone(),
            owner_kind: Some(TaskOwnerKind::Thread),
            owner_id: Some(parent_thread_id.to_owned()),
            limit: Some(10),
            ..Default::default()
        })
        .await
        .expect("voice Composer task should be queryable");
    assert_eq!(tasks.tasks.len(), 1);
    assert_eq!(
        tasks.tasks[0].created_by_turn_id.as_deref(),
        Some(turn_id),
        "voice Task must retain the parent message turn as its causal source"
    );
    assert_eq!(
        provider.call_count(),
        0,
        "collaborative voice must not dispatch an agent turn in the parent thread"
    );
    let (_, parent_turn) = crud_store
        .get_turn(parent_thread_id, turn_id)
        .await
        .expect("parent voice message turn lookup should succeed")
        .expect("parent voice message turn should exist");
    assert_eq!(parent_turn.status, TurnStatus::Completed);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn task_run_voice_composer_stays_foreground() {
    let (tx, mut rx) = mpsc::channel(128);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let provider = Arc::new(CaptureSummaryProvider::new("foreground child result"));
    let processor = MessageProcessor::new(
        thread_manager.clone(),
        Arc::new(pioneer_provider::ProviderRegistry::with_provider(
            "openai",
            provider.clone(),
        )),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_voice_input_supervisor(ready_gateway_voice_supervisor("continue inside this child"));
    let root_thread_id = "thr_voice_task_root";
    let root_turn_id = "turn_voice_task_root";
    ensure_test_superuser_execution_turn(
        &processor,
        workspace_id.as_str(),
        root_thread_id,
        root_turn_id,
    )
    .await;
    let child_thread_id = "thr_voice_task_run";
    let started = thread_manager
        .thread_start_seeded(
            connection_id,
            workspace_id.clone(),
            ThreadStartParams {
                thread_id: child_thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                name: None,
                model: Some("test-model".to_owned()),
                model_provider: Some("openai".to_owned()),
                sandbox: None,
                mode: Some(ThreadMode::Agent),
                origin_kind: Some(ThreadOriginKind::TaskRun),
                sidebar_visibility: Some(ThreadSidebarVisibility::Hidden),
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await
        .expect("TaskRun child thread should start");
    crud_store
        .upsert_thread_model(
            &started.response.thread,
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("persist task-run voice authorization target");
    crud_store
        .append_task_event(
            TaskEventPayload::TaskThreadLineageCreated {
                task_id: "task_voice_task_run".to_owned(),
                run_id: "run_voice_task_run".to_owned(),
                lineage: TaskThreadLineage {
                    child_thread_id: child_thread_id.to_owned(),
                    parent_thread_id: root_thread_id.to_owned(),
                    root_thread_id: root_thread_id.to_owned(),
                    depth: 1,
                    origin_kind: Some("task_run".to_owned()),
                    created_by_thread_id: Some(root_thread_id.to_owned()),
                    created_by_turn_id: Some(root_turn_id.to_owned()),
                    created_at: now_timestamp_secs(),
                },
            },
            now_timestamp_secs(),
        )
        .await
        .expect("persist task-run voice lineage");

    let turn_id = "turn_voice_task_run";
    let result = submit_test_voice_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        child_thread_id,
        turn_id,
    )
    .await;
    assert_eq!(
        result.outcome,
        VoiceSessionOutcome::TurnStarted,
        "voice execution failed: {:?}",
        result.error
    );
    assert_eq!(result.turn_id.as_deref(), Some(turn_id));

    let _ = recv_notification_by_method(&mut rx, events::TURN_COMPLETED).await;
    assert!(
        provider.call_count() >= 1,
        "voice inside a TaskRun child must execute through that child's provider"
    );
    let tasks = processor
        .task_runtime
        .service()
        .list_tasks(TaskListParams {
            workspace_id,
            owner_kind: Some(TaskOwnerKind::Thread),
            owner_id: Some(child_thread_id.to_owned()),
            limit: Some(10),
            ..Default::default()
        })
        .await
        .expect("child-owned tasks should be queryable");
    assert!(
        tasks.tasks.is_empty(),
        "foreground child voice must not be wrapped in another Composer task"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn voice_session_transcript_starts_turn_and_preserves_authorized_context_attachments() {
    let base_dir = unique_temp_dir("voice_turn_capability");
    let system_root = base_dir.join("system");
    let user_root = base_dir.join("user");
    let workspace_root = base_dir.join("workspace");
    let registry_root = base_dir.join("registry");
    std::fs::create_dir_all(&system_root).expect("create system root");
    std::fs::create_dir_all(&workspace_root).expect("create workspace root");
    std::fs::create_dir_all(&registry_root).expect("create registry root");
    let weather_path = write_test_skill(&user_root, "weather", "", "weather body");
    let (tx, mut rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let weather_skill_id = seed_test_skill_installation(
        crud_store.as_ref(),
        'V',
        workspace_id.as_str(),
        "user",
        weather_path.as_path(),
        Some("tests"),
        "weather",
    )
    .await;
    let capture_provider = Arc::new(CaptureSummaryProvider::new("voice answer"));
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "openai",
        capture_provider.clone(),
    ));
    let processor = MessageProcessor::new(
        thread_manager,
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store,
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config_with_roots(&system_root, &user_root, &workspace_root, &registry_root),
    )
    .with_voice_input_supervisor(ready_gateway_voice_supervisor(
        "voice transcript with context",
    ));
    let thread = start_thread_for_artifact_test(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        "thr_voice_turn_context",
    )
    .await;
    let artifact = ingest_user_test_artifact_for_thread(
        &processor,
        workspace_id.as_str(),
        Some(thread.thread.id.as_str()),
        "voice-artifact.txt",
    )
    .await;

    let voice_turn_id = "turn_voice_success_0001";
    let voice_context = json!({
        "workspace_id": workspace_id,
        "thread_id": thread.thread.id,
        "turn_id": voice_turn_id,
        "prepared_input": [
            {
                "type": "artifact",
                "artifactId": artifact.artifact_id.clone(),
                "versionId": artifact.version_id.clone()
            }
        ],
        "capabilities": [
            {
                "id": format!("skill:{weather_skill_id}"),
                "kind": { "type": "skill", "skillId": weather_skill_id },
                "label": "tests/weather"
            },
            {
                "id": "mcp-tool:workspace:resend:send_email",
                "kind": {
                    "type": "mcpTool",
                    "serverName": "resend",
                    "rawToolName": "send_email",
                    "scopeKind": "workspace"
                },
                "label": "resend / Send Email"
            }
        ]
    });

    let start_request_id = generate_test_request_id("voice", "start_success");
    let start_request = json!({
        "jsonrpc": "2.0",
        "id": start_request_id.clone(),
        "method": "voice/session/start",
        "params": {
            "context": {
                "workspace_id": workspace_id,
                "thread_id": thread.thread.id,
                "turn_id": voice_turn_id
            },
            "audio_format": {
                "sample_rate_hz": 16000,
                "channels": 1,
                "encoding": "pcm_s16_le"
            }
        }
    });
    processor
        .process_request_for_connection(connection_id, &start_request.to_string())
        .await;
    let start_response = recv_response_by_id(&mut rx, start_request_id.as_str()).await;
    let start_payload: pioneer_protocol::VoiceSessionStartResponse =
        serde_json::from_value(start_response.result).expect("voice/session/start decode");
    assert_eq!(start_payload.status, VoiceStatus::Recording);

    let status_request_id = generate_test_request_id("voice", "status_active");
    let status_request = json!({
        "jsonrpc": "2.0",
        "id": status_request_id.clone(),
        "method": "voice/status",
        "params": { "workspace_id": workspace_id }
    });
    processor
        .process_request_for_connection(connection_id, &status_request.to_string())
        .await;
    let status_response = recv_response_by_id(&mut rx, status_request_id.as_str()).await;
    let status_payload: pioneer_protocol::VoiceStatusResponse =
        serde_json::from_value(status_response.result).expect("voice/status decode");
    assert_eq!(status_payload.status, VoiceStatus::Recording);
    assert_eq!(
        status_payload.active_session_id.as_deref(),
        Some(start_payload.session_id.as_str())
    );

    let frame = voice_test_frame(start_payload.session_id.as_str(), 0, 960, 12_000);
    processor
        .process_binary_frame_for_connection(connection_id, frame.as_slice())
        .await
        .expect("registered voice connection");
    let ack = recv_notification_by_method(&mut rx, events::VOICE_CHUNK_ACK).await;
    let ack_payload: pioneer_protocol::VoiceChunkAckNotification =
        serde_json::from_value(ack.params.expect("voice/chunk ack params"))
            .expect("voice/chunk ack decode");
    assert_eq!(ack_payload.session_id, start_payload.session_id);
    assert_eq!(ack_payload.sequence, 0);

    let finalize_request_id = generate_test_request_id("voice", "finish_success");
    let finalize_request = json!({
        "jsonrpc": "2.0",
        "id": finalize_request_id.clone(),
        "method": "voice/session/finalize",
        "params": {
            "session_id": start_payload.session_id,
            "context": voice_context
        }
    });
    processor
        .process_request_for_connection(connection_id, &finalize_request.to_string())
        .await;
    let finalize_response = recv_response_by_id(&mut rx, finalize_request_id.as_str()).await;
    let finalize_payload: pioneer_protocol::VoiceSessionFinalizeResponse =
        serde_json::from_value(finalize_response.result).expect("voice/session/finalize decode");
    assert_eq!(finalize_payload.status, VoiceStatus::Transcribing);

    let turn_started = recv_notification_by_method(&mut rx, events::TURN_STARTED).await;
    let turn_started_payload: pioneer_protocol::TurnStartedNotification =
        serde_json::from_value(turn_started.params.expect("turn/started params"))
            .expect("turn/started decode");
    assert_eq!(turn_started_payload.turn.id, "turn_voice_success_0001");

    let mut user_message = None;
    let mut result_payload = None;
    let mut turn_completed = false;
    for _ in 0..40 {
        let payload = recv_text_timeout_context(
            &mut rx,
            Duration::from_secs(10),
            "voice turn lifecycle notification",
        )
        .await;
        let value: serde_json::Value =
            serde_json::from_str(&payload).expect("voice lifecycle payload should decode");
        let Some(method) = value.get("method").and_then(serde_json::Value::as_str) else {
            continue;
        };
        match method {
            events::ITEM_COMPLETED => {
                let notification: JsonRpcNotification = serde_json::from_value(value)
                    .expect("item/completed notification should decode");
                let completed: pioneer_protocol::ItemCompletedNotification =
                    serde_json::from_value(notification.params.expect("item/completed params"))
                        .expect("item/completed decode");
                if let TurnItem::UserMessage {
                    text, attachments, ..
                } = completed.item
                {
                    user_message = Some((text, attachments));
                }
            }
            events::VOICE_SESSION_RESULT => {
                let notification: JsonRpcNotification = serde_json::from_value(value)
                    .expect("voice/session/result notification should decode");
                result_payload = Some(
                    serde_json::from_value(
                        notification.params.expect("voice/session/result params"),
                    )
                    .expect("voice/session/result decode"),
                );
            }
            events::TURN_COMPLETED => turn_completed = true,
            _ => {}
        }
        if user_message.is_some() && result_payload.is_some() && turn_completed {
            break;
        }
    }
    let (text, attachments) = user_message.expect("voice turn must emit a user message");
    assert_eq!(text, "voice transcript with context");
    assert!(
        attachments.iter().any(|attachment| matches!(
            attachment,
            UserMessageAttachment::Artifact { artifact: resolved }
                if resolved.artifact_id == artifact.artifact_id
                    && resolved.display_name == "voice-artifact.txt"
        )),
        "voice turn must preserve prepared artifact attachment"
    );
    assert!(
        attachments.iter().any(|attachment| matches!(
            attachment,
            UserMessageAttachment::Skill { capability }
                if capability.skill_id == weather_skill_id
                    && capability.owner.as_deref() == Some("tests")
                    && capability.slug == "weather"
        )),
        "voice turn must preserve selected skill capability"
    );
    assert!(
        attachments.iter().any(|attachment| matches!(
            attachment,
            UserMessageAttachment::McpTool { capability }
                if capability.id == "mcp-tool:workspace:resend:send_email"
                    && capability.scope_kind == McpScopeKind::Workspace
        )),
        "voice turn must preserve selected MCP tool capability"
    );

    let result_payload: VoiceSessionResultNotification =
        result_payload.expect("voice turn must emit voice/session/result");
    assert_eq!(result_payload.session_id, start_payload.session_id);
    assert_eq!(result_payload.outcome, VoiceSessionOutcome::TurnStarted);
    assert_eq!(
        result_payload.turn_id.as_deref(),
        Some("turn_voice_success_0001")
    );
    assert!(result_payload.error.is_none());

    assert!(turn_completed, "voice turn must emit turn/completed");
    assert_eq!(capture_provider.call_count(), 1);
    let _ = std::fs::remove_dir_all(base_dir);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
