#[tokio::test]
async fn voice_reconfiguration_busy_blocks_all_active_states_before_persistence() {
    let runtime_home = unique_temp_dir("voice_reconfiguration_busy");
    std::fs::create_dir_all(&runtime_home).expect("runtime home");
    let (tx, mut rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store,
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_runtime_home_for_tests(runtime_home.clone());
    processor
        .voice_sessions
        .create_session(
            "voice_reconfiguration_busy_session",
            connection_id,
            pioneer_protocol::VoiceSessionStartContext {
                workspace_id: workspace_id.clone(),
                thread_id: "thread_voice_reconfiguration_busy".to_owned(),
                turn_id: "turn_voice_reconfiguration_busy".to_owned(),
            },
            pioneer_protocol::VoiceAudioFormat {
                sample_rate_hz: 16_000,
                channels: 1,
                encoding: pioneer_protocol::VoiceAudioEncoding::PcmS16Le,
            },
        )
        .expect("create active voice session");
    processor
        .voice_sessions
        .mark_recording("voice_reconfiguration_busy_session", connection_id)
        .expect("recording");

    for (state, transition) in [
        ("recording", None),
        ("finalizing", Some(false)),
        ("transcribing", Some(true)),
    ] {
        if let Some(transcribing) = transition {
            if transcribing {
                processor
                    .voice_sessions
                    .mark_transcribing("voice_reconfiguration_busy_session", connection_id)
                    .expect("transcribing");
            } else {
                processor
                    .voice_sessions
                    .mark_finalizing("voice_reconfiguration_busy_session", connection_id)
                    .expect("finalizing");
            }
        }
        let request_id = generate_test_request_id("voicebusy", state);
        processor
            .process_request_for_connection(
                connection_id,
                &json!({
                    "jsonrpc": "2.0",
                    "id": request_id.clone(),
                    "method": "settings/update",
                    "params": {
                        "update": {
                            "voice_input": {
                                "enabled": true,
                                "provider": "local",
                                "model": "small"
                            }
                        }
                    }
                })
                .to_string(),
            )
            .await;
        let error = recv_error_by_id(&mut rx, request_id.as_str()).await;
        assert_eq!(
            error
                .error
                .data
                .as_ref()
                .and_then(|data| data.get("code"))
                .and_then(JsonValue::as_str),
            Some("voice_reconfiguration_busy")
        );
    }

    let unrelated_request_id = generate_test_request_id("voicebusy", "unrelated");
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": unrelated_request_id.clone(),
                "method": "settings/update",
                "params": { "update": { "general": { "keepawake": false } } }
            })
            .to_string(),
        )
        .await;
    let _ = recv_response_by_id(&mut rx, unrelated_request_id.as_str()).await;

    let config = pioneer_config::AppConfig::load().expect("app config");
    let settings_path = runtime_home.join(config.gateway.settings_file_name.as_str());
    let settings = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        config.gateway.settings_version,
        config.gateway.settings_file_name.as_str(),
    )
    .expect("load settings after rejection");
    let rejected_snapshot = settings.snapshot(&config.gateway);
    assert!(!rejected_snapshot.voice_input.enabled);
    assert_eq!(rejected_snapshot.voice_input.model, None);
    assert!(!rejected_snapshot.general.keepawake);

    let removed = processor.voice_sessions.cleanup_connection(connection_id);
    assert_eq!(removed.len(), 1);
    assert!(
        !processor
            .voice_sessions
            .has_active_sessions()
            .expect("clean session store")
    );
    let retry_request_id = generate_test_request_id("voicebusy", "after_cleanup");
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": retry_request_id.clone(),
                "method": "settings/update",
                "params": {
                    "update": {
                        "voice_input": {
                            "enabled": true,
                            "provider": "local",
                            "model": "small"
                        }
                    }
                }
            })
            .to_string(),
        )
        .await;
    let response = recv_response_by_id(&mut rx, retry_request_id.as_str()).await;
    let payload: pioneer_protocol::GatewaySettingsUpdateResponse =
        serde_json::from_value(response.result).expect("settings update response");
    assert!(payload.settings.voice_input.enabled);
    assert_eq!(payload.settings.voice_input.model.as_deref(), Some("small"));

    let _ = std::fs::remove_dir_all(runtime_home);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn voice_settings_disable_removes_model_files_and_preserves_selection() {
    let runtime_home = unique_temp_dir("voice_settings_disable_cleanup");
    std::fs::create_dir_all(&runtime_home).expect("runtime home");
    let config = pioneer_config::AppConfig::load().expect("app config");
    let entry =
        crate::voice::model_catalog::voice_model_catalog_entry("small").expect("small voice model");
    let layout = crate::voice::model_catalog::voice_model_install_layout(
        &entry,
        &config,
        runtime_home.as_path(),
    )
    .expect("voice model layout");
    std::fs::create_dir_all(layout.install_dir.as_path()).expect("installed model");
    std::fs::create_dir_all(layout.downloads_dir.as_path()).expect("downloads dir");
    std::fs::write(layout.archive_path.as_path(), b"archive").expect("model archive");
    std::fs::write(layout.partial_archive_path.as_path(), b"partial")
        .expect("partial model archive");
    let unknown_model_dir = layout.models_root.join("custom-user-model");
    std::fs::create_dir_all(unknown_model_dir.as_path()).expect("unknown model dir");

    let settings_path = runtime_home.join(config.gateway.settings_file_name.as_str());
    let mut settings = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        config.gateway.settings_version,
        config.gateway.settings_file_name.as_str(),
    )
    .expect("initial settings");
    settings
        .apply_protocol_update(pioneer_protocol::GatewaySettingsUpdate {
            voice_input: Some(pioneer_protocol::GatewayVoiceInputSettingsUpdate {
                enabled: Some(true),
                provider: Some(Some(pioneer_protocol::GatewayVoiceInputProvider::Local)),
                model: Some(Some(entry.id.to_owned())),
                retry_install: false,
            }),
            ..pioneer_protocol::GatewaySettingsUpdate::default()
        })
        .expect("enable persisted Voice Input");
    crate::settings::save_gateway_settings(settings_path.as_path(), &settings)
        .expect("save enabled Voice Input");

    let supervisor = Arc::new(crate::voice::supervisor::VoiceInputSupervisor::new(
        Arc::new(
            crate::voice::supervisor::FilesystemVoiceModelInstaller::new(
                config.clone(),
                runtime_home.clone(),
            ),
        ),
        Arc::new(TestGatewayVoiceEngineLoader),
    ));
    let applied = supervisor
        .apply_desired(
            crate::voice::supervisor::VoiceInputDesiredState {
                enabled: true,
                provider: Some(pioneer_protocol::GatewayVoiceInputProvider::Local),
                model: Some(entry.id.to_owned()),
            },
            false,
        )
        .expect("apply enabled Voice Input");
    supervisor
        .mark_loading(applied.generation)
        .expect("mark voice model loading");
    supervisor
        .mark_ready(
            applied.generation,
            crate::voice::supervisor::VoiceModelIdentity {
                provider: pioneer_protocol::GatewayVoiceInputProvider::Local,
                model: entry.id.to_owned(),
            },
            crate::voice::runtime::LoadedVoiceEngine::test_stub(),
        )
        .expect("mark voice model ready");

    let (tx, mut rx) = mpsc::channel(16);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id))
        .await;
    let processor = MessageProcessor::new(
        Arc::new(ThreadManager::new("o4-mini", "openai")),
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store,
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_runtime_home_for_tests(runtime_home.clone())
    .with_voice_input_supervisor(supervisor);

    let request_id = generate_test_request_id("voice_settings", "disable_cleanup");
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id.clone(),
                "method": "settings/update",
                "params": {
                    "update": {
                        "voice_input": { "enabled": false }
                    }
                }
            })
            .to_string(),
        )
        .await;
    let response = recv_response_by_id(&mut rx, request_id.as_str()).await;
    let payload: pioneer_protocol::GatewaySettingsUpdateResponse =
        serde_json::from_value(response.result).expect("settings update response");

    assert!(!payload.settings.voice_input.enabled);
    assert_eq!(
        payload.settings.voice_input.model.as_deref(),
        Some(entry.id)
    );
    assert!(!layout.install_dir.exists());
    assert!(!layout.archive_path.exists());
    assert!(!layout.partial_archive_path.exists());
    assert!(unknown_model_dir.exists());
    let persisted = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        config.gateway.settings_version,
        config.gateway.settings_file_name.as_str(),
    )
    .expect("persisted disabled settings")
    .snapshot(&config.gateway);
    assert!(!persisted.voice_input.enabled);
    assert_eq!(persisted.voice_input.model.as_deref(), Some(entry.id));

    let _ = std::fs::remove_dir_all(runtime_home);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn voice_settings_two_client_race_serializes_to_one_consistent_outcome() {
    let runtime_home = unique_temp_dir("voice_settings_two_client_race");
    std::fs::create_dir_all(&runtime_home).expect("runtime home");
    let config = pioneer_config::AppConfig::load().expect("app config");
    let settings_path = runtime_home.join(config.gateway.settings_file_name.as_str());
    let mut settings = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        config.gateway.settings_version,
        config.gateway.settings_file_name.as_str(),
    )
    .expect("initial settings");
    settings
        .apply_protocol_update(pioneer_protocol::GatewaySettingsUpdate {
            voice_input: Some(pioneer_protocol::GatewayVoiceInputSettingsUpdate {
                enabled: Some(true),
                provider: Some(Some(pioneer_protocol::GatewayVoiceInputProvider::Local)),
                model: Some(Some("parakeet-tdt-0.6b-v3".to_owned())),
                retry_install: false,
            }),
            ..pioneer_protocol::GatewaySettingsUpdate::default()
        })
        .expect("persisted enabled Voice Input");
    crate::settings::save_gateway_settings(settings_path.as_path(), &settings)
        .expect("save enabled Voice Input");

    let (tx_a, mut rx_a) = mpsc::channel(32);
    let (tx_b, mut rx_b) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_a = register_authenticated_test_connection(session_manager.as_ref(), tx_a).await;
    let connection_b = register_authenticated_test_connection(session_manager.as_ref(), tx_b).await;
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_a, Some(workspace_id.clone()))
        .await;
    session_manager
        .set_connection_workspace(connection_b, Some(workspace_id.clone()))
        .await;
    let processor = Arc::new(
        MessageProcessor::new(
            Arc::new(ThreadManager::new("o4-mini", "openai")),
            test_provider(),
            session_manager,
            workspace_manager,
            crud_store,
            test_gateway_secrets(),
            test_summary_config(),
            test_context_budget(),
            test_tool_loop_config(),
        )
        .with_runtime_home_for_tests(runtime_home.clone())
        .with_voice_input_supervisor(ready_gateway_voice_supervisor("race transcript")),
    );
    let thread = start_thread_for_artifact_test(
        processor.as_ref(),
        connection_a,
        &mut rx_a,
        workspace_id.as_str(),
        "thr_voice_settings_race",
    )
    .await;

    let start_id = generate_test_request_id("voice_race", "start");
    let start_payload = json!({
        "jsonrpc": "2.0",
        "id": start_id.clone(),
        "method": "voice/session/start",
        "params": {
            "context": {
                "workspace_id": workspace_id,
                "thread_id": thread.thread.id,
                "turn_id": "turn_voice_settings_race"
            },
            "audio_format": {
                "sample_rate_hz": 16000,
                "channels": 1,
                "encoding": "pcm_s16_le"
            }
        }
    })
    .to_string();
    let race_barrier = Arc::new(tokio::sync::Barrier::new(3));
    let start_processor = processor.clone();
    let start_barrier = race_barrier.clone();
    let start_task = tokio::spawn(async move {
        start_barrier.wait().await;
        start_processor
            .process_request_for_connection(connection_a, start_payload.as_str())
            .await;
    });

    let update_id = generate_test_request_id("voice_race", "disable");
    let update_payload = json!({
        "jsonrpc": "2.0",
        "id": update_id.clone(),
        "method": "settings/update",
        "params": {
            "update": {
                "voice_input": { "enabled": false }
            }
        }
    })
    .to_string();
    let update_processor = processor.clone();
    let update_barrier = race_barrier.clone();
    let update_task = tokio::spawn(async move {
        update_barrier.wait().await;
        update_processor
            .process_request_for_connection(connection_b, update_payload.as_str())
            .await;
    });
    race_barrier.wait().await;

    tokio::time::timeout(std::time::Duration::from_secs(5), start_task)
        .await
        .expect("session start task must not deadlock")
        .expect("session start task");
    tokio::time::timeout(std::time::Duration::from_secs(5), update_task)
        .await
        .expect("settings update task must not deadlock")
        .expect("settings update task");
    let start_response: JsonValue = serde_json::from_str(
        recv_jsonrpc_payload_by_id(&mut rx_a, start_id.as_str())
            .await
            .as_str(),
    )
    .expect("session start JSON-RPC response");
    let update_response: JsonValue = serde_json::from_str(
        recv_jsonrpc_payload_by_id(&mut rx_b, update_id.as_str())
            .await
            .as_str(),
    )
    .expect("settings update JSON-RPC response");
    let start_succeeded = start_response.get("result").is_some();
    let update_succeeded = update_response.get("result").is_some();
    assert_ne!(
        start_succeeded, update_succeeded,
        "exactly one racing Voice Input operation must succeed"
    );

    let persisted = crate::settings::load_or_create_gateway_settings(
        settings_path.as_path(),
        config.gateway.settings_version,
        config.gateway.settings_file_name.as_str(),
    )
    .expect("settings after race");
    let snapshot = persisted.snapshot(&config.gateway);
    if start_succeeded {
        assert_eq!(
            update_response
                .pointer("/error/data/code")
                .and_then(JsonValue::as_str),
            Some("voice_reconfiguration_busy")
        );
        assert!(snapshot.voice_input.enabled);
        assert_eq!(
            snapshot.voice_input.model.as_deref(),
            Some("parakeet-tdt-0.6b-v3")
        );
    } else {
        assert_eq!(
            start_response
                .pointer("/error/data/kind")
                .and_then(JsonValue::as_str),
            Some("model_unavailable")
        );
        assert!(!snapshot.voice_input.enabled);
        assert_eq!(
            snapshot.voice_input.model.as_deref(),
            Some("parakeet-tdt-0.6b-v3")
        );
    }

    let _ = std::fs::remove_dir_all(runtime_home);
}

fn voice_test_frame(session_id: &str, sequence: u64, samples: usize, sample: i16) -> Vec<u8> {
    let mut pcm = Vec::with_capacity(samples * 2);
    for _ in 0..samples {
        pcm.extend_from_slice(&sample.to_le_bytes());
    }
    pioneer_protocol::encode_voice_chunk_frame(
        pioneer_protocol::VoiceChunkFrameHeader {
            session_id: session_id.to_owned(),
            sequence,
            sample_rate_hz: pioneer_protocol::VOICE_AUDIO_TARGET_SAMPLE_RATE_HZ,
            channels: pioneer_protocol::VOICE_AUDIO_TARGET_CHANNELS,
            encoding: pioneer_protocol::VoiceAudioEncoding::PcmS16Le,
            payload_len: 0,
            captured_at_unix_ms: Some(1_725_000_000_000),
            duration_ms: Some(60),
        },
        pcm.as_slice(),
    )
    .expect("voice test frame should encode")
}

fn upload_binary_test_frame<T: serde::Serialize>(
    magic: &[u8; 4],
    header: &T,
    chunk: &[u8],
) -> Vec<u8> {
    let header_bytes = serde_json::to_vec(header).expect("binary upload header should encode");
    let mut frame = Vec::with_capacity(8 + header_bytes.len() + chunk.len());
    frame.extend_from_slice(magic);
    frame.extend_from_slice(
        &u32::try_from(header_bytes.len())
            .expect("binary upload header length should fit u32")
            .to_be_bytes(),
    );
    frame.extend_from_slice(header_bytes.as_slice());
    frame.extend_from_slice(chunk);
    frame
}

fn malformed_binary_test_frame(magic: &[u8; 4]) -> Vec<u8> {
    let mut frame = Vec::with_capacity(8);
    frame.extend_from_slice(magic);
    frame.extend_from_slice(&64_u32.to_be_bytes());
    frame
}

async fn setup_binary_ingress_processor() -> (
    MessageProcessor,
    Arc<SessionManager>,
    ConnectionId,
    mpsc::Receiver<Message>,
    ConnectionId,
    mpsc::Receiver<Message>,
    Arc<CrudStore>,
    String,
    tempfile::TempDir,
) {
    let (owner_tx, owner_rx) = mpsc::channel(32);
    let (foreign_tx, foreign_rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let owner_connection_id =
        register_authenticated_test_connection(session_manager.as_ref(), owner_tx).await;
    let foreign_connection_id =
        register_authenticated_test_connection(session_manager.as_ref(), foreign_tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let skills_runtime = tempfile::tempdir().expect("binary ingress skills runtime");
    let system_root = skills_runtime.path().join("system");
    let user_root = skills_runtime.path().join("user");
    let workspace_root = skills_runtime.path().join("workspace");
    let registry_root = skills_runtime.path().join("registry");
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager.clone(),
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config_with_roots(
            system_root.as_path(),
            user_root.as_path(),
            workspace_root.as_path(),
            registry_root.as_path(),
        ),
    );

    (
        processor,
        session_manager,
        owner_connection_id,
        owner_rx,
        foreign_connection_id,
        foreign_rx,
        crud_store,
        workspace_id,
        skills_runtime,
    )
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn binary_ingress_rejects_unregistered_connections_before_decoding_every_family() {
    let (
        processor,
        _session_manager,
        owner_connection_id,
        _owner_rx,
        foreign_connection_id,
        _foreign_rx,
        _crud_store,
        _workspace_id,
        _skills_runtime,
    ) = setup_binary_ingress_processor().await;
    let unregistered_connection_id = foreign_connection_id.saturating_add(10_000);

    for (family, frame) in [
        (
            "artifact",
            malformed_binary_test_frame(super::artifacts::ARTIFACT_UPLOAD_CHUNK_FRAME_MAGIC),
        ),
        (
            "skill",
            malformed_binary_test_frame(super::skills::SKILL_UPLOAD_CHUNK_FRAME_MAGIC),
        ),
        (
            "voice",
            malformed_binary_test_frame(pioneer_protocol::VOICE_CHUNK_FRAME_MAGIC),
        ),
    ] {
        let error = processor
            .process_binary_frame_for_connection(unregistered_connection_id, frame.as_slice())
            .await
            .expect_err("unregistered binary ingress must be rejected before frame decoding");
        assert!(
            error.to_string().contains("unregistered connection"),
            "{family} binary ingress returned unexpected error: {error:#}"
        );
    }

    assert!(
        processor
            .session_manager
            .connection_context(owner_connection_id)
            .await
            .is_ok(),
        "registered control connection must remain available"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn authorization_gate_allows_superuser_and_denies_user_text_and_binary_dispatch() {
    let (superuser_tx, mut superuser_rx) = mpsc::channel(16);
    let (user_tx, mut user_rx) = mpsc::channel(16);
    let (roleless_tx, mut roleless_rx) = mpsc::channel(16);
    let session_manager = Arc::new(SessionManager::new());
    let superuser_connection_id =
        register_authenticated_test_connection(session_manager.as_ref(), superuser_tx).await;
    let mut user_principal = (*authenticated_test_superuser()).clone();
    user_principal.kind = pioneer_protocol::PrincipalKind::User;
    user_principal.role_key = Some(RoleKey::member());
    let user_connection_id = session_manager
        .register_connection(user_tx, Arc::new(user_principal))
        .await
        .unwrap();
    let mut roleless_principal = (*authenticated_test_superuser()).clone();
    roleless_principal.kind = pioneer_protocol::PrincipalKind::User;
    roleless_principal.role_key = None;
    let roleless_connection_id = session_manager
        .register_connection(roleless_tx, Arc::new(roleless_principal))
        .await
        .unwrap();
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager.clone(),
        crud_store,
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    );

    let allow_request_id = generate_test_request_id("authzallow", "list");
    processor
        .process_request_for_connection(
            superuser_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": allow_request_id,
                "method": "workspace/list",
                "params": {}
            })
            .to_string(),
        )
        .await;
    let allow_response = recv_response_by_id(&mut superuser_rx, allow_request_id.as_str()).await;
    let allow_payload: WorkspaceListResponse =
        serde_json::from_value(allow_response.result).expect("Superuser workspace/list response");
    assert!(
        allow_payload
            .workspaces
            .iter()
            .any(|workspace| workspace.id == workspace_id),
        "absolute Superuser allow-path must not require a workspace membership"
    );

    let unmapped_request_id = generate_test_request_id("authzdeny", "unknown");
    processor
        .process_request_for_connection(
            superuser_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": unmapped_request_id,
                "method": "future/unregistered",
                "params": {
                    "prompt": "must not reach any handler"
                }
            })
            .to_string(),
        )
        .await;
    let unmapped = recv_error_by_id(&mut superuser_rx, unmapped_request_id.as_str()).await;
    assert_eq!(unmapped.error.code, METHOD_NOT_FOUND_CODE);
    assert_eq!(unmapped.error.message, "method not found");

    let inaccessible_request_id = generate_test_request_id("authzscope", "empty");
    processor
        .process_request_for_connection(
            user_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": inaccessible_request_id,
                "method": "workspace/list",
                "params": {}
            })
            .to_string(),
        )
        .await;
    let inaccessible = recv_response_by_id(&mut user_rx, inaccessible_request_id.as_str()).await;
    let inaccessible: WorkspaceListResponse =
        serde_json::from_value(inaccessible.result).expect("decode scoped empty workspace list");
    assert!(
        inaccessible.workspaces.is_empty(),
        "Member without memberships must receive an empty collection"
    );
    let no_default_id = generate_test_request_id("authzscope", "nodefault");
    processor
        .process_request_for_connection(
            user_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": no_default_id,
                "method": "workspace/default",
                "params": {}
            })
            .to_string(),
        )
        .await;
    let no_default = recv_error_by_id(&mut user_rx, no_default_id.as_str()).await;
    assert_eq!(no_default.error.message, "not_found");
    assert_eq!(
        processor
            .session_manager
            .connection_workspace_id(user_connection_id)
            .await,
        None,
        "empty Member default must preserve no selected workspace"
    );

    let terminal_request_id = generate_test_request_id("authzdeny", "terminal");
    processor
        .process_request_for_connection(
            roleless_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": terminal_request_id,
                "method": "workspace/list",
                "params": {}
            })
            .to_string(),
        )
        .await;
    let terminal = recv_error_by_id(&mut roleless_rx, terminal_request_id.as_str()).await;
    assert_eq!(terminal.error.message, "authentication_terminal");
    let terminal_json = serde_json::to_string(&terminal).expect("serialize terminal response");
    assert!(!terminal_json.contains("unsupported_role"));

    let workspaces_before = workspace_manager
        .list_workspaces()
        .await
        .expect("workspace list before denied request");
    let deny_request_id = generate_test_request_id("authzdeny", "create");
    processor
        .process_request_for_connection(
            user_connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": deny_request_id,
                "method": "workspace/create",
                "params": {
                    "workspace_id": "ws_denied_authz",
                    "name": "must-not-be-created"
                }
            })
            .to_string(),
        )
        .await;
    let denied = recv_error_by_id(&mut user_rx, deny_request_id.as_str()).await;
    assert_eq!(denied.error.message, "forbidden");
    let denied_json = serde_json::to_string(&denied).expect("serialize forbidden response");
    assert!(!denied_json.contains("management_denied"));
    assert_eq!(
        workspace_manager
            .list_workspaces()
            .await
            .expect("workspace list after denied request"),
        workspaces_before,
        "denied text dispatch must not reach the mutating handler"
    );

    let chunk = b"denied binary mutation";
    let upload = processor
        .artifact_uploads
        .start(
            user_connection_id,
            ArtifactUploadStartParams {
                workspace_id: workspace_id.clone(),
                thread_id: None,
                planned_turn_id: None,
                client_attachment_id: "denied_binary".to_owned(),
                file_name: "denied.txt".to_owned(),
                mime_type: Some("text/plain".to_owned()),
                size_bytes: chunk.len() as u64,
                sha256: hex::encode(Sha256::digest(chunk)),
                source_kind: ArtifactUploadSourceKind::Api,
            },
            i64::MAX / 2,
        )
        .await
        .expect("control upload session should start");
    let frame = upload_binary_test_frame(
        super::artifacts::ARTIFACT_UPLOAD_CHUNK_FRAME_MAGIC,
        &ArtifactUploadChunkHeader {
            workspace_id: workspace_id.clone(),
            upload_id: upload.upload_id.clone(),
            offset: 0,
            len: chunk.len() as u64,
            chunk_sha256: Some(hex::encode(Sha256::digest(chunk))),
        },
        chunk,
    );
    processor
        .process_binary_frame_for_connection(user_connection_id, frame.as_slice())
        .await
        .expect("registered User reaches central binary authorization");
    assert!(
        timeout(Duration::from_millis(50), user_rx.recv())
            .await
            .is_err(),
        "denied binary dispatch must not send an upload ack"
    );
    assert!(
        processor
            .artifact_uploads
            .finish(
                user_connection_id,
                workspace_id.as_str(),
                upload.upload_id.as_str(),
                i64::MAX / 2,
            )
            .await
            .expect_err("denied binary dispatch must not mutate upload state")
            .to_string()
            .contains("incomplete")
    );
}

