#[test]
fn force_fail_tool_item_marks_in_progress_tool_as_failed() {
    let item = pioneer_protocol::TurnItem::CommandExecution {
        id: "item_1".to_owned(),
        tool_name: "exec_command".to_owned(),
        arguments: json!({}),
        status: pioneer_protocol::ToolCallStatus::InProgress,
        recovery_policy: None,
        output_policy: ToolOutputPolicySnapshot::for_tool_name("exec_command"),
        display: ToolDisplayPayload::Shell {
            stdout: None,
            stderr: None,
            aggregated_output: Some("partial output".to_owned()),
            exit_code: None,
            duration_ms: None,
            timed_out: None,
            truncated: false,
        },
        storage: ToolStoragePayload::Shell {
            stdout: None,
            stderr: None,
            aggregated_output: Some("partial output".to_owned()),
            exit_code: None,
            duration_ms: None,
            timed_out: None,
            truncated: false,
        },
        recovery: None,
        command: vec!["echo".to_owned(), "hello".to_owned()],
        cwd: None,
        success: None,
        outcome: None,
        observation: None,
    };
    let failed = MessageProcessor::force_fail_tool_item(item, "recovery attempts exhausted")
        .expect("tool item should be force-failed");
    match failed {
        pioneer_protocol::TurnItem::CommandExecution {
            status,
            success,
            display,
            ..
        } => {
            assert_eq!(status, pioneer_protocol::ToolCallStatus::Failed);
            assert_eq!(success, Some(false));
            let ToolDisplayPayload::Summary(summary) = display else {
                panic!("failed tool should contain summary display");
            };
            let text = summary.lines.join("\n");
            assert!(text.contains("partial output"));
            assert!(text.contains("recovery failed: recovery attempts exhausted"));
        }
        _ => panic!("unexpected turn item variant"),
    }
}

#[test]
fn review_disabled_immediate_task_agent_run_creates_child_thread_and_wait_returns_result() {
    run_standard_stack_message_test(
        "review-disabled immediate Task Agent run",
        review_disabled_immediate_task_agent_run_creates_child_thread_and_wait_returns_result_impl(
        ),
    );
}

async fn review_disabled_immediate_task_agent_run_creates_child_thread_and_wait_returns_result_impl()
 {
    let session_manager = Arc::new(SessionManager::new());
    let (tx, _rx) = mpsc::channel(8);
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = Arc::new(MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    ));
    processor.bind_task_bridge().await;

    let child_title = "Summarize child result";
    let mut params = test_task_create_params(
        workspace_id.as_str(),
        "thr_parent_task_test",
        "turn_parent_task_test",
        child_title,
        3,
    );
    params.delivery_policy = Some(TaskDeliveryPolicy {
        mode: TaskDeliveryMode::Thread,
        thread_target: Some(pioneer_protocol::TaskDeliveryThreadTarget::OriginThread),
        thread_id: Some("thr_parent_task_test".to_owned()),
        webhook_url: None,
        include_result: true,
        format: TaskDeliveryFormat::Summary,
    });
    if let Some(agent_spec) = params.agent_spec.as_mut() {
        agent_spec.tool_policy = Some(TaskAgentToolPolicy {
            allowed_tools: Vec::new(),
            denied_tools: Vec::new(),
            write_mode: TaskAgentWriteMode::ScopedWrite,
            allowed_paths: vec!["src".to_owned()],
            network_access: false,
        });
    }
    let response = create_task_for_test(&processor, params)
        .await
        .expect("task_create should start immediate child task");
    let run = response
        .run
        .clone()
        .expect("immediate task should create run");
    let lineage = wait_for_child_lineage_for_run(crud_store.clone(), run.id.as_str()).await;
    assert!(!lineage.child_turn_id.is_empty());
    assert_eq!(
        lineage.created_by_turn_id.as_deref(),
        Some("turn_parent_task_test"),
        "immediate attached subagent should stay under the live parent turn"
    );
    let binding = crud_store
        .get_task_run_primary_thread_binding(run.id.as_str())
        .await
        .expect("primary task run binding query should succeed")
        .expect("agent task start should create primary thread binding");
    assert_eq!(
        binding.binding_kind,
        TaskRunThreadBindingKind::PrimaryExecutor
    );
    assert_eq!(binding.thread_id, lineage.child_thread_id);
    let task_run_turn = crud_store
        .get_task_run_turn_by_turn(
            lineage.child_thread_id.as_str(),
            lineage.child_turn_id.as_str(),
        )
        .await
        .expect("task run turn query should succeed")
        .expect("agent task start should create initial task_run_turn");
    assert_eq!(task_run_turn.kind, TaskRunTurnKind::Initial);
    assert_eq!(task_run_turn.round, 0);
    assert_eq!(task_run_turn.sequence, 0);
    assert!(matches!(
        task_run_turn.status,
        TaskRunTurnStatus::InProgress | TaskRunTurnStatus::CandidateCreated
    ));

    let child_thread = crud_store
        .get_thread_model(lineage.child_thread_id.as_str())
        .await
        .expect("child thread query should succeed")
        .expect("child thread should be persisted");
    assert_eq!(
        child_thread.sidebar_visibility,
        ThreadSidebarVisibility::Hidden
    );
    assert_eq!(child_thread.name.as_deref(), Some(child_title));

    let tree_threads = processor
        .list_threads_snapshot_for_connection(workspace_id.as_str(), 100, connection_id)
        .await
        .expect("thread tree snapshot should load");
    assert!(
        tree_threads
            .iter()
            .all(|thread| thread.id != lineage.child_thread_id),
        "hidden child thread must not appear in sidebar thread tree"
    );

    let wait_response = wait_tasks_for_test(
        &processor,
        TaskWaitParams {
            task_ids: vec![response.task.id.clone()],
            run_ids: Vec::new(),
            timeout_ms: Some(5_000),
            return_completed: true,
            return_pending: true,
            ..Default::default()
        },
    )
    .await
    .expect("task_wait should succeed");
    assert!(
        !wait_response.completed.is_empty(),
        "child echo turn should complete the task"
    );
    let completed = &wait_response.completed[0];
    assert_eq!(
        completed.child_turn_id.as_deref(),
        Some(lineage.child_turn_id.as_str())
    );
    assert!(
        completed
            .run
            .as_ref()
            .and_then(|run| run.result.as_ref())
            .and_then(|result| result.summary.as_deref())
            .is_some(),
        "task_wait should return normalized run result"
    );
    let stored_task = crud_store
        .get_task(response.task.id.as_str())
        .await
        .expect("completed task should load")
        .expect("completed task should exist");
    assert_eq!(
        stored_task.task.status,
        pioneer_protocol::TaskStatus::Completed
    );
    assert_ne!(
        stored_task.task.status,
        pioneer_protocol::TaskStatus::WaitingReview,
        "review-disabled auto-approve must not enter waiting_review task state"
    );
    let stored_run = stored_task
        .runs
        .iter()
        .find(|stored_run| stored_run.id == run.id)
        .expect("completed run should remain visible");
    assert_eq!(stored_run.status, TaskRunStatus::Succeeded);
    assert_ne!(
        stored_run.status,
        TaskRunStatus::Waiting,
        "review-disabled auto-approve must not enter waiting_review/waiting run state"
    );
    assert_ne!(
        stored_run.status,
        TaskRunStatus::WaitingReview,
        "review-disabled auto-approve must not enter waiting_review run state"
    );
    let execution = crud_store
        .load_execution_for_run(run.id.as_str())
        .await
        .expect("execution should load")
        .expect("execution should exist");
    assert_ne!(
        execution.status,
        TaskRunExecutionStatus::WaitingReview,
        "review-disabled auto-approve must not leave execution waiting for review"
    );
    assert_eq!(stored_task.thread_lineage.len(), 1);
    assert_eq!(
        stored_task.thread_lineage[0].child_thread_id,
        lineage.child_thread_id
    );
    assert_eq!(
        stored_task.thread_lineage[0].created_by_turn_id.as_deref(),
        Some("turn_parent_task_test")
    );
    assert_eq!(stored_task.task_run_thread_bindings.len(), 1);
    assert_eq!(stored_task.task_run_thread_bindings[0], binding);
    assert_eq!(stored_task.task_run_turns.len(), 1);
    assert_eq!(stored_task.task_run_turns[0].turn_id, lineage.child_turn_id);
    let write_locks = crud_store
        .list_task_write_locks_by_run(run.id.as_str())
        .await
        .expect("write locks should list");
    assert!(
        !write_locks.is_empty(),
        "scoped-write task should acquire write locks"
    );
    assert!(
        write_locks
            .iter()
            .all(|lock| lock.status == TaskWriteLockStatus::Released),
        "auto-approved completion should release write locks through existing finalization"
    );
    let deliveries = processor
        .task_runtime
        .service()
        .list_deliveries(TaskDeliveriesParams {
            workspace_id: workspace_id.clone(),
            task_id: Some(response.task.id.clone()),
            run_id: Some(run.id.clone()),
            statuses: Vec::new(),
            limit: Some(10),
        })
        .await
        .expect("task deliveries should list");
    assert_eq!(deliveries.deliveries.len(), 1);
    assert_eq!(deliveries.deliveries[0].status, TaskDeliveryStatus::Pending);
    assert_eq!(
        deliveries.deliveries[0]
            .result_snapshot
            .as_ref()
            .and_then(|result| result.summary.as_deref()),
        completed
            .run
            .as_ref()
            .and_then(|run| run.result.as_ref())
            .and_then(|result| result.summary.as_deref())
    );
    let task_run_turns = crud_store
        .list_task_run_turns(run.id.as_str())
        .await
        .expect("task run turns should list");
    assert_eq!(
        task_run_turns.len(),
        1,
        "auto-approved initial run must not create duplicate task_run_turn rows"
    );
    assert_eq!(
        task_run_turns[0].status,
        TaskRunTurnStatus::CandidateCreated,
        "completed child turn should become a result candidate source"
    );
    let accepted_candidate = crud_store
        .get_accepted_task_result_candidate(run.id.as_str())
        .await
        .expect("accepted candidate query should succeed")
        .expect("auto-approved child result should create an accepted candidate");
    assert_eq!(
        accepted_candidate.status,
        TaskResultCandidateStatus::Accepted
    );
    assert!(
        crud_store
            .get_pending_task_result_candidate(run.id.as_str())
            .await
            .expect("pending candidate query should succeed")
            .is_none(),
        "review-disabled auto-approve must not create a pending review candidate"
    );
    assert_eq!(accepted_candidate.task_run_turn_id, task_run_turns[0].id);
    assert_eq!(accepted_candidate.thread_id, lineage.child_thread_id);
    assert_eq!(accepted_candidate.turn_id, lineage.child_turn_id);
    assert_eq!(
        accepted_candidate
            .result
            .as_ref()
            .and_then(|result| result.summary.as_deref()),
        completed
            .run
            .as_ref()
            .and_then(|run| run.result.as_ref())
            .and_then(|result| result.summary.as_deref())
    );
    assert!(accepted_candidate.final_review_event_id.is_some());
    let review_events = crud_store
        .list_task_result_review_events(accepted_candidate.id.as_str())
        .await
        .expect("review events should list");
    assert_eq!(review_events.len(), 1);
    assert_eq!(
        review_events[0].event_kind,
        TaskResultReviewEventKind::SystemAuto
    );
    assert_eq!(
        review_events[0].reviewer_kind,
        TaskResultReviewerKind::RuntimeAuto
    );
    assert_eq!(review_events[0].decision, TaskResultReviewDecision::Accept);
    assert_eq!(
        accepted_candidate.final_review_event_id.as_deref(),
        Some(review_events[0].id.as_str())
    );
    let stored_task = crud_store
        .get_task(response.task.id.as_str())
        .await
        .expect("completed task should reload")
        .expect("completed task should still exist");
    assert_eq!(stored_task.result_candidates.len(), 1);
    assert_eq!(stored_task.result_candidates[0], accepted_candidate);
    assert_eq!(stored_task.result_review_events.len(), 1);
    assert_eq!(stored_task.result_review_events[0], review_events[0]);

    let task_events = crud_store
        .get_task_events(response.task.id.as_str(), None)
        .await
        .expect("task events should load");
    let event_types = task_events
        .events
        .iter()
        .map(|event| event.event_type.as_str())
        .collect::<Vec<_>>();
    assert!(event_types.contains(&events::TASK_CREATED));
    assert!(event_types.contains(&events::TASK_RUN_CREATED));
    assert!(event_types.contains(&events::TASK_RUN_THREAD_BINDING_CREATED));
    assert!(event_types.contains(&events::TASK_RUN_TURN_STARTED));
    assert!(event_types.contains(&events::TASK_RUN_STARTED));
    assert!(event_types.contains(&events::TASK_RUN_TURN_COMPLETED));
    assert!(event_types.contains(&events::TASK_RESULT_CANDIDATE_CREATED));
    assert!(event_types.contains(&events::TASK_RESULT_REVIEW_EVENT_RECORDED));
    assert!(event_types.contains(&events::TASK_RESULT_CANDIDATE_ACCEPTED));
    assert!(event_types.contains(&events::TASK_RUN_COMPLETED));
    assert!(event_types.contains(&events::TASK_COMPLETED));
    assert!(!event_types.contains(&events::TASK_RUN_ENTERED_REVIEW));
    assert!(!event_types.contains(&events::TASK_RESULT_CANDIDATE_CANCELLED));
}

#[test]
fn review_enabled_child_completion_creates_pending_candidate_without_finalizing_run() {
    run_standard_stack_message_test(
        "review-enabled child Task completion",
        review_enabled_child_completion_creates_pending_candidate_without_finalizing_run_impl(),
    );
}

async fn review_enabled_child_completion_creates_pending_candidate_without_finalizing_run_impl() {
    let provider = Arc::new(DelayedProvider {
        delay: Duration::from_millis(0),
        text: r#"<task_result>{"summary":"ready for parent review","data":{"answer":"ok"}}</task_result>"#
            .to_owned(),
    });
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "openai", provider,
    ));
    let session_manager = Arc::new(SessionManager::new());
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = review_enabled_processor(
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store.clone(),
    );
    processor.bind_task_bridge().await;

    let mut params = test_task_create_params(
        workspace_id.as_str(),
        "thr_parent_review_success",
        "turn_parent_review_success",
        "Review child result",
        3,
    );
    params.delivery_policy = Some(TaskDeliveryPolicy {
        mode: TaskDeliveryMode::Thread,
        thread_target: Some(pioneer_protocol::TaskDeliveryThreadTarget::OriginThread),
        thread_id: Some("thr_parent_review_success".to_owned()),
        webhook_url: None,
        include_result: true,
        format: TaskDeliveryFormat::Summary,
    });
    params
        .agent_spec
        .as_mut()
        .expect("agent spec should exist")
        .review_policy = Some(TaskAgentReviewPolicy::parent_agent_default(2));

    let response = create_task_for_test(&processor, params)
        .await
        .expect("review-enabled task_create should start child task");
    let run = response
        .run
        .clone()
        .expect("immediate task should create run");
    let lineage = wait_for_child_lineage_for_run(crud_store.clone(), run.id.as_str()).await;
    let candidate = wait_for_result_candidate_status(
        crud_store.clone(),
        run.id.as_str(),
        TaskResultCandidateStatus::PendingReview,
    )
    .await;

    assert_eq!(candidate.thread_id, lineage.child_thread_id);
    assert_eq!(candidate.turn_id, lineage.child_turn_id);
    assert_eq!(
        candidate
            .result
            .as_ref()
            .and_then(|result| result.summary.as_deref()),
        Some("ready for parent review")
    );
    assert_eq!(
        wait_for_task_status(
            crud_store.clone(),
            response.task.id.as_str(),
            pioneer_protocol::TaskStatus::WaitingReview,
        )
        .await,
        pioneer_protocol::TaskStatus::WaitingReview
    );
    assert_eq!(
        wait_for_run_status(
            crud_store.clone(),
            run.id.as_str(),
            TaskRunStatus::WaitingReview,
        )
        .await,
        TaskRunStatus::WaitingReview
    );
    let execution = crud_store
        .load_execution_for_run(run.id.as_str())
        .await
        .expect("execution should load")
        .expect("execution should exist");
    assert_eq!(execution.status, TaskRunExecutionStatus::WaitingReview);
    let stored_run = crud_store
        .get_task_run(run.id.as_str())
        .await
        .expect("task run should load")
        .expect("task run should exist");
    assert!(stored_run.result.is_none());
    assert!(
        crud_store
            .get_accepted_task_result_candidate(run.id.as_str())
            .await
            .expect("accepted candidate query should succeed")
            .is_none()
    );
    let deliveries = processor
        .task_runtime
        .service()
        .list_deliveries(TaskDeliveriesParams {
            workspace_id: workspace_id.clone(),
            task_id: Some(response.task.id.clone()),
            run_id: Some(run.id.clone()),
            statuses: Vec::new(),
            limit: Some(10),
        })
        .await
        .expect("task deliveries should list");
    assert!(deliveries.deliveries.is_empty());
    let event_types = crud_store
        .get_task_events(response.task.id.as_str(), None)
        .await
        .expect("task events should load")
        .events
        .into_iter()
        .map(|event| event.event_type)
        .collect::<Vec<_>>();
    assert!(event_types.contains(&events::TASK_RUN_TURN_COMPLETED.to_owned()));
    assert!(event_types.contains(&events::TASK_RESULT_CANDIDATE_CREATED.to_owned()));
    assert!(event_types.contains(&events::TASK_RUN_ENTERED_REVIEW.to_owned()));
    assert!(!event_types.contains(&events::TASK_RESULT_CANDIDATE_ACCEPTED.to_owned()));
    assert!(!event_types.contains(&events::TASK_RUN_COMPLETED.to_owned()));
    assert!(!event_types.contains(&events::TASK_COMPLETED.to_owned()));
}

#[test]
fn review_enabled_window_continuation_does_not_create_revision_and_preserves_candidate() {
    run_standard_stack_message_test(
        "review-enabled execution-window continuation",
        review_enabled_window_continuation_does_not_create_revision_and_preserves_candidate_impl(),
    );
}

async fn review_enabled_window_continuation_does_not_create_revision_and_preserves_candidate_impl()
{
    let provider = Arc::new(HangingChildProvider::new());
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "openai",
        provider.clone(),
    ));
    let session_manager = Arc::new(SessionManager::new());
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = review_enabled_processor(
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store.clone(),
    );
    processor.bind_task_bridge().await;

    let mut params = test_task_create_params(
        workspace_id.as_str(),
        "thr_review_window_no_revision",
        "turn_review_window_no_revision",
        "Review child with execution window",
        3,
    );
    params
        .agent_spec
        .as_mut()
        .expect("agent spec should exist")
        .review_policy = Some(TaskAgentReviewPolicy::parent_agent_default(1));

    let response = create_task_for_test(&processor, params)
        .await
        .expect("review-enabled task_create should start child task");
    let run = response
        .run
        .clone()
        .expect("immediate task should create run");
    let lineage = wait_for_child_lineage_for_run(crud_store.clone(), run.id.as_str()).await;
    for _ in 0..100 {
        if provider.child_main_call_count() > 0 {
            break;
        }
        sleep(Duration::from_millis(25)).await;
    }
    assert!(
        provider.child_main_call_count() > 0,
        "child provider should be hanging before synthetic review completion"
    );

    processor
        .handle_durable_agent_event(AgentDurableEvent::TurnExecutionWindowStarted {
            notification: pioneer_protocol::TurnExecutionWindowStartedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: lineage.child_thread_id.clone(),
                turn_id: lineage.child_turn_id.clone(),
                window_id: "review_window_no_revision_1".to_owned(),
                window_index: 1,
                status: ExecutionWindowStatus::Running,
                started_at_unix_ms: 1_000,
            },
        })
        .await;
    processor
        .handle_durable_agent_event(AgentDurableEvent::TurnExecutionWindowExhausted {
            notification: pioneer_protocol::TurnExecutionWindowExhaustedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: lineage.child_thread_id.clone(),
                turn_id: lineage.child_turn_id.clone(),
                window_id: "review_window_no_revision_1".to_owned(),
                window_index: 1,
                status: ExecutionWindowStatus::Exhausted,
                exhaustion_reason: ExecutionWindowExhaustionReason::MaxAgentRoundsPerWindow,
                limit: 2,
                observed: 2,
                agent_round_count: 2,
                tool_call_count: 0,
                provider_token_count: None,
                started_at_unix_ms: 1_000,
                exhausted_at_unix_ms: 2_000,
                reason: "max_agent_rounds_per_window".to_owned(),
            },
        })
        .await;
    processor
        .handle_durable_agent_event(AgentDurableEvent::TurnExecutionWindowContinued {
            notification: pioneer_protocol::TurnExecutionWindowContinuedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: lineage.child_thread_id.clone(),
                turn_id: lineage.child_turn_id.clone(),
                window_id: "review_window_no_revision_2".to_owned(),
                window_index: 2,
                status: ExecutionWindowStatus::Continued,
                previous_window_id: "review_window_no_revision_1".to_owned(),
                previous_window_index: 1,
                checkpoint_id: "review_window_checkpoint_1".to_owned(),
                continued_at_unix_ms: 2_100,
            },
        })
        .await;

    let task_run_turns = crud_store
        .list_task_run_turns(run.id.as_str())
        .await
        .expect("task run turns should list after window continuation");
    assert_eq!(task_run_turns.len(), 1);
    assert_eq!(task_run_turns[0].kind, TaskRunTurnKind::Initial);
    assert_eq!(task_run_turns[0].status, TaskRunTurnStatus::InProgress);
    assert!(
        !task_run_turns
            .iter()
            .any(|turn| turn.kind == TaskRunTurnKind::Revision),
        "execution window continuation must not create semantic revision turns"
    );

    crud_store
        .materialize_item_completed(
            ItemCompletedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: lineage.child_thread_id.clone(),
                turn_id: lineage.child_turn_id.clone(),
                item: TurnItem::AgentMessage {
                    id: "item_review_candidate_after_window".to_owned(),
                    text: r#"<task_result>{"summary":"review after window","data":{"ok":true}}</task_result>"#
                        .to_owned(),
                    phase: Default::default(),
                    markdown: None,
                    markdown_version: None,
                },
            },
            super::now_timestamp_secs(),
        )
        .await
        .expect("synthetic review child result item should persist");
    processor
        .handle_durable_agent_event(AgentDurableEvent::TurnCompleted {
            thread_id: lineage.child_thread_id.clone(),
            turn_id: lineage.child_turn_id.clone(),
            recovery: None,
        })
        .await;

    let candidate = wait_for_result_candidate_status(
        crud_store.clone(),
        run.id.as_str(),
        TaskResultCandidateStatus::PendingReview,
    )
    .await;
    assert_eq!(candidate.thread_id, lineage.child_thread_id);
    assert_eq!(candidate.turn_id, lineage.child_turn_id);
    assert_eq!(
        candidate
            .result
            .as_ref()
            .and_then(|result| result.summary.as_deref()),
        Some("review after window")
    );
    assert_eq!(
        wait_for_run_status(
            crud_store.clone(),
            run.id.as_str(),
            TaskRunStatus::WaitingReview,
        )
        .await,
        TaskRunStatus::WaitingReview
    );
    let task_run_turns = crud_store
        .list_task_run_turns(run.id.as_str())
        .await
        .expect("task run turns should list after review candidate");
    assert_eq!(task_run_turns.len(), 1);
    assert_eq!(task_run_turns[0].kind, TaskRunTurnKind::Initial);
    assert_eq!(
        task_run_turns[0].status,
        TaskRunTurnStatus::CandidateCreated
    );
}

#[test]
fn task_accept_rpc_finalizes_review_candidate_and_queues_delivery() {
    run_standard_stack_message_test(
        "Task review accept and delivery",
        task_accept_rpc_finalizes_review_candidate_and_queues_delivery_impl(),
    );
}

async fn task_accept_rpc_finalizes_review_candidate_and_queues_delivery_impl() {
    let provider = Arc::new(DelayedProvider {
        delay: Duration::from_millis(0),
        text: r#"<task_result>{"summary":"ready for user approval","data":{"answer":"ok"}}</task_result>"#
            .to_owned(),
    });
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "openai", provider,
    ));
    let session_manager = Arc::new(SessionManager::new());
    let (tx, mut rx) = mpsc::channel(8);
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = review_enabled_processor(
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store.clone(),
    );
    processor.bind_task_bridge().await;
    ensure_test_superuser_execution_authority(crud_store.as_ref()).await;
    let principal = authenticated_test_superuser();
    let principal_actor =
        pioneer_protocol::PersistedActorRef::Principal(principal.principal_id.clone());
    let parent_author =
        super::message_turn::resolve_turn_author_snapshot(crud_store.as_ref(), &principal_actor)
            .await
            .expect("user-review parent author should resolve")
            .expect("user-review parent principal should have an author snapshot");

    let created_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| i64::try_from(duration.as_secs()).unwrap_or(i64::MAX))
        .unwrap_or(0);
    let parent_thread_id = "thr_user_review_accept";
    let parent_turn_id = "turn_user_review_accept";
    let parent_thread = Thread {
        workspace_id: workspace_id.clone(),
        id: parent_thread_id.to_owned(),
        name: Some("User review accept parent".to_owned()),
        preview: "review accept".to_owned(),
        preview_author: Some(parent_author.clone()),
        mode: ThreadMode::Agent,
        model: "test-model".to_owned(),
        model_provider: "openai".to_owned(),
        reasoning_effort: None,
        created_at,
        updated_at: created_at,
        status: ThreadStatus::Active,
        origin_kind: ThreadOriginKind::User,
        sidebar_visibility: ThreadSidebarVisibility::Visible,
        agent_nickname: None,
        agent_role: None,
        visibility: None,
        turns: Vec::new(),
    };
    let parent_turn = Turn {
        id: parent_turn_id.to_owned(),
        status: TurnStatus::Completed,
        turn_kind: Default::default(),
        origin: Default::default(),
        mode: Default::default(),
        author: Some(parent_author),
        reply_to_turn_id: None,
        mentions: Vec::new(),
        message_revision: 0,
        message_deleted: false,
        error: None,
        prompt_manifest: None,
        permission_profile: default_test_permission_profile(),
    };
    crud_store
        .materialize_turn_start(
            &parent_thread,
            SandboxMode::FullAccess,
            &Turn {
                status: TurnStatus::InProgress,
                ..parent_turn.clone()
            },
            &[],
            principal_actor,
        )
        .await
        .expect("parent turn start should persist");
    crud_store
        .materialize_turn_completed(
            TurnCompletedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: parent_thread_id.to_owned(),
                turn: parent_turn,
            },
            created_at,
        )
        .await
        .expect("parent turn completion should persist");

    let mut params = test_task_create_params(
        workspace_id.as_str(),
        parent_thread_id,
        parent_turn_id,
        "User accepts child result",
        3,
    );
    params.lifecycle_policy = Some(TaskLifecyclePolicy {
        attachment: TaskAttachmentMode::Detached,
        on_parent_cancel: TaskParentTerminalAction::KeepRunning,
        on_parent_failure: TaskParentTerminalAction::KeepRunning,
        completion: TaskCompletionBehavior::CompleteOnTerminalRun,
    });
    params.delivery_policy = Some(TaskDeliveryPolicy {
        mode: TaskDeliveryMode::Thread,
        thread_target: Some(pioneer_protocol::TaskDeliveryThreadTarget::OriginThread),
        thread_id: Some(parent_thread_id.to_owned()),
        webhook_url: None,
        include_result: true,
        format: TaskDeliveryFormat::Summary,
    });
    params
        .agent_spec
        .as_mut()
        .expect("agent spec should exist")
        .review_policy = Some(TaskAgentReviewPolicy {
        mode: TaskAgentReviewMode::UserApproval,
        max_revision_rounds: 2,
        require_explicit_acceptance: true,
        reviewers: Vec::new(),
        resolution_strategy: TaskResultReviewResolutionStrategy::UserFinal,
    });

    let response = create_task_for_test(&processor, params)
        .await
        .expect("review-enabled task_create should start child task");
    let run = response
        .run
        .clone()
        .expect("immediate task should create run");
    let candidate = wait_for_result_candidate_status(
        crud_store.clone(),
        run.id.as_str(),
        TaskResultCandidateStatus::PendingReview,
    )
    .await;
    let (_, occurrence_before_accept) = crud_store
        .get_turn(parent_thread_id, run.id.as_str())
        .await
        .expect("occurrence turn lookup before accept should succeed")
        .expect("occurrence turn should exist before accept");
    assert_eq!(occurrence_before_accept.turn_kind, TurnKind::TaskRun);
    assert_eq!(occurrence_before_accept.status, TurnStatus::InProgress);

    let request_id = generate_test_request_id("taskaccept", "rpc");
    let request = json!({
        "jsonrpc": "2.0",
        "id": request_id.clone(),
        "method": pioneer_protocol::constants::methods::TASK_ACCEPT,
        "params": {
            "taskId": response.task.id,
            "runId": run.id.clone(),
            "candidateId": candidate.id.clone(),
            "reason": "approved by user"
        }
    });
    processor
        .process_request_for_connection(connection_id, &request.to_string())
        .await;
    let rpc_response = recv_response_by_id(&mut rx, request_id.as_str()).await;
    let accepted: TaskAcceptResponse =
        serde_json::from_value(rpc_response.result).expect("task/accept response should decode");

    assert!(accepted.accepted);
    assert!(!accepted.already_accepted);
    assert_eq!(
        accepted.review_event.reviewer_kind,
        TaskResultReviewerKind::User
    );
    let expected_user_id = authenticated_test_superuser().principal_id.to_string();
    assert_eq!(
        accepted.review_event.reviewer_user_id.as_deref(),
        Some(expected_user_id.as_str())
    );
    assert_eq!(accepted.run.status, TaskRunStatus::Succeeded);
    assert_eq!(
        accepted.task.status,
        pioneer_protocol::TaskStatus::Completed
    );
    assert_eq!(
        accepted.candidate.status,
        TaskResultCandidateStatus::Accepted
    );
    assert_eq!(
        accepted.result.summary.as_deref(),
        Some("ready for user approval")
    );

    let deliveries = processor
        .task_runtime
        .service()
        .list_deliveries(TaskDeliveriesParams {
            workspace_id: workspace_id.clone(),
            task_id: Some(accepted.task.id.clone()),
            run_id: Some(accepted.run.id.clone()),
            statuses: Vec::new(),
            limit: Some(10),
        })
        .await
        .expect("task deliveries should list after accept");
    assert_eq!(deliveries.deliveries.len(), 1);
    assert_eq!(deliveries.deliveries[0].status, TaskDeliveryStatus::Pending);
    assert_eq!(
        deliveries.deliveries[0]
            .result_snapshot
            .as_ref()
            .and_then(|result| result.summary.as_deref()),
        Some("ready for user approval")
    );
    let run_completed_event = processor
        .task_runtime
        .service()
        .list_task_events_after(accepted.task.id.as_str(), 0)
        .await
        .expect("task events should list after accept")
        .into_iter()
        .find(|event| {
            matches!(
                &event.payload,
                TaskEventPayload::RunCompleted { run_id, .. } if run_id == &accepted.run.id
            )
        })
        .expect("accepted run should emit RunCompleted event");
    processor
        .emit_task_event(run_completed_event)
        .await
        .expect("run completed event should project occurrence turn");
    assert_eq!(
        crud_store
            .get_turn(parent_thread_id, accepted.run.id.as_str())
            .await
            .expect("occurrence turn lookup should succeed")
            .expect("occurrence turn should exist")
            .1
            .status,
        TurnStatus::InProgress,
        "accepted result must keep the parent occurrence active until delivery"
    );
    processor
        .process_due_task_deliveries(super::now_timestamp_secs().saturating_add(1), 10)
        .await
        .expect("accepted result delivery should run");
    assert_eq!(
        processor
            .reconcile_terminal_task_run_occurrence_turns(10)
            .await
            .expect("terminal occurrence reconciliation should succeed"),
        1,
        "durable delivery state must repair a missed live fanout"
    );
    assert_eq!(
        processor
            .reconcile_terminal_task_run_occurrence_turns(10)
            .await
            .expect("idempotent terminal occurrence reconciliation should succeed"),
        0,
        "an already repaired occurrence must not be counted or polled again"
    );
    let delivery_delivered_event = processor
        .task_runtime
        .service()
        .list_task_events_after(accepted.task.id.as_str(), 0)
        .await
        .expect("task events should list after delivery")
        .into_iter()
        .find(|event| {
            matches!(
                &event.payload,
                TaskEventPayload::DeliveryDelivered { delivery, .. }
                    if delivery.run_id == accepted.run.id
            )
        })
        .expect("accepted result should emit DeliveryDelivered");
    processor
        .emit_task_event(delivery_delivered_event)
        .await
        .expect("delivery event should complete occurrence turn");
    assert_eq!(
        wait_for_turn_status(
            crud_store.clone(),
            parent_thread_id,
            accepted.run.id.as_str(),
            TurnStatus::Completed,
        )
        .await,
        TurnStatus::Completed
    );
}

