async fn task_create_tool_idempotency_key_deduplicates_parallel_mutations_impl() {
    let (tx, mut rx) = mpsc::channel(128);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("test-model", "parent"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let child_title = "Idempotent delegated task";
    let task_arguments = json!({
        "title": child_title,
        "goal": "Return a short delegated result",
        "instructions": ["Return a concise final answer."],
        "background": true,
        "idempotencyKey": "same-task-create-key"
    })
    .to_string();
    let provider = Arc::new(SequencedToolProvider::new(
        vec![
            ProviderToolCall {
                id: "call_task_create_idem_1".to_owned(),
                name: "task_create".to_owned(),
                arguments: task_arguments.clone(),
            },
            ProviderToolCall {
                id: "call_task_create_idem_2".to_owned(),
                name: "task_create".to_owned(),
                arguments: task_arguments,
            },
        ],
        "parent observed child result",
    ));
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "parent",
        provider.clone(),
    ));
    provider_registry.insert("echo", Arc::new(EchoProvider::new()));
    let processor = Arc::new(MessageProcessor::new(
        thread_manager,
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    ));
    processor.start_resilience_workers().await;

    start_thread_and_turn(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        "thr_task_tool_idempotency",
        "turn_task_tool_idempotency",
        "Agent",
        "parent",
    )
    .await;
    let _ = recv_notification_by_method(&mut rx, events::TURN_COMPLETED).await;

    let turn_items = crud_store
        .get_turn_item_events("thr_task_tool_idempotency", "turn_task_tool_idempotency")
        .await
        .expect("turn items should load")
        .expect("turn should exist");
    let task_anchor_count = turn_items
        .events
        .iter()
        .filter(|event| {
            matches!(
                &event.payload,
                TurnItemEventPayload::ItemCompleted {
                    item: TurnItem::Task { item },
                    ..
                } if item.title == child_title
            )
        })
        .count();
    assert_eq!(
        task_anchor_count, 1,
        "same idempotency key in one provider round must create one durable task anchor"
    );
}

#[test]
fn task_delivery_worker_uses_lineage_parent_turn_for_origin_thread() {
    run_standard_stack_message_test(
        "Task delivery lineage parent turn",
        task_delivery_worker_uses_lineage_parent_turn_for_origin_thread_impl(),
    );
}

async fn task_delivery_worker_uses_lineage_parent_turn_for_origin_thread_impl() {
    let connection = Database::connect("sqlite::memory:")
        .await
        .expect("must connect to sqlite memory");
    Migrator::up(&connection, None)
        .await
        .expect("migrations must succeed");
    bootstrap(&connection)
        .await
        .expect("gateway bootstrap should create default workspace");

    let (tx, mut rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let workspace_manager = Arc::new(WorkspaceManager::new(connection.clone()));
    let workspace_id = workspace_manager
        .list_workspaces()
        .await
        .expect("workspace/list should succeed")
        .into_iter()
        .find(|workspace| workspace.is_active && workspace.is_current)
        .expect("default workspace should exist")
        .id;
    let crud_store = Arc::new(CrudStore::new(connection.clone()));
    let processor = MessageProcessor::with_agent_manager(
        thread_manager,
        Arc::new(AgentManager::new(test_provider(), test_tool_loop_config())),
        session_manager,
        workspace_manager,
        crud_store.clone(),
    );
    processor
        .task_runtime
        .register_executor(Arc::new(CompletingSystemExecutor))
        .await;

    let origin_thread_id = "thr_delivery_origin";
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": "taskdeliverythread001",
                "method": "thread/start",
                "params": {
                    "thread_id": origin_thread_id,
                    "workspace_id": workspace_id,
                    "mode": "Agent"
                }
            })
            .to_string(),
        )
        .await;
    let _ = recv_response_by_id(&mut rx, "taskdeliverythread001").await;

    let response = processor
        .task_runtime
        .service()
        .create_task(
            pioneer_tasks::TaskCreateContext::default(),
            TaskCreateParams {
                workspace_id: workspace_id.clone(),
                owner_kind: TaskOwnerKind::Thread,
                owner_id: Some(origin_thread_id.to_owned()),
                created_by_thread_id: Some(origin_thread_id.to_owned()),
                created_by_turn_id: None,
                parent_task_id: None,
                executor_kind: TaskExecutorKind::System,
                title: "Scheduled delivery".to_owned(),
                goal: "Deliver a scheduled result".to_owned(),
                priority: 0,
                trigger: TaskTriggerInput {
                    spec: TaskTriggerSpec::ScheduledAt {
                        scheduled_at: 4_000_000_000,
                        timezone: Some("UTC".to_owned()),
                        catch_up_policy: None,
                    },
                },
                launch: None,
                agent_spec: None,
                lifecycle_policy: None,
                delivery_policy: Some(TaskDeliveryPolicy {
                    mode: TaskDeliveryMode::Thread,
                    thread_target: Some(pioneer_protocol::TaskDeliveryThreadTarget::OriginThread),
                    thread_id: Some(origin_thread_id.to_owned()),
                    webhook_url: None,
                    include_result: true,
                    format: TaskDeliveryFormat::Summary,
                }),
                retry_policy: None,
                timeout_policy: None,
                concurrency_policy: None,
                metadata: None,
            },
        )
        .await
        .expect("task should create");
    let task_id = response.task.id.clone();

    processor
        .task_runtime
        .process_due_once(4_000_000_000)
        .await
        .expect("scheduled task should fire");

    let task_after_run = processor
        .crud_store
        .get_task(task_id.as_str())
        .await
        .expect("task should read")
        .expect("task should exist");
    let run = task_after_run
        .runs
        .last()
        .expect("scheduled run should exist")
        .clone();
    let parent_thread = processor
        .thread_manager
        .thread_get(origin_thread_id)
        .await
        .expect("owner thread should be loaded");
    let occurrence_turn = Turn {
        id: run.id.clone(),
        status: TurnStatus::Completed,
        turn_kind: TurnKind::TaskRun,
        origin: TurnOrigin::ScheduledTask,
        mode: Default::default(),
        author: None,
        reply_to_turn_id: None,
        mentions: Vec::new(),
        message_revision: 0,
        message_deleted: false,
        error: None,
        prompt_manifest: None,
        permission_profile: default_test_permission_profile(),
    };
    processor
        .crud_store
        .materialize_turn_start(
            &parent_thread,
            SandboxMode::FullAccess,
            &Turn {
                status: TurnStatus::InProgress,
                ..occurrence_turn.clone()
            },
            &[],
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("occurrence turn start should persist");
    processor
        .crud_store
        .materialize_turn_completed(
            TurnCompletedNotification {
                workspace_id: workspace_id.clone(),
                thread_id: origin_thread_id.to_owned(),
                turn: occurrence_turn,
            },
            4_000_000_000,
        )
        .await
        .expect("occurrence turn completion should persist");
    processor
        .crud_store
        .append_task_event(
            TaskEventPayload::TaskThreadLineageCreated {
                task_id: task_id.clone(),
                run_id: run.id.clone(),
                lineage: TaskThreadLineage {
                    child_thread_id: "child_delivery_thread_1".to_owned(),
                    parent_thread_id: origin_thread_id.to_owned(),
                    root_thread_id: origin_thread_id.to_owned(),
                    depth: 0,
                    origin_kind: Some("task_run".to_owned()),
                    created_by_thread_id: Some(origin_thread_id.to_owned()),
                    created_by_turn_id: Some(run.id.clone()),
                    created_at: 4_000_000_000,
                },
            },
            4_000_000_000,
        )
        .await
        .expect("lineage should persist");
    processor
        .crud_store
        .upsert_task_run_thread_binding(TaskRunThreadBinding {
            id: "binding_delivery_1".to_owned(),
            task_id: task_id.clone(),
            run_id: run.id.clone(),
            execution_id: None,
            thread_id: "child_delivery_thread_1".to_owned(),
            binding_kind: TaskRunThreadBindingKind::PrimaryExecutor,
            created_at: 4_000_000_000,
        })
        .await
        .expect("task run thread binding should persist");
    processor
        .crud_store
        .upsert_task_run_turn(TaskRunTurn {
            id: "turn_delivery_1".to_owned(),
            task_id: task_id.clone(),
            run_id: run.id.clone(),
            execution_id: None,
            thread_id: "child_delivery_thread_1".to_owned(),
            turn_id: "child_delivery_turn_1".to_owned(),
            kind: TaskRunTurnKind::Initial,
            round: 0,
            sequence: 0,
            status: TaskRunTurnStatus::CandidateCreated,
            reviews_candidate_id: None,
            requested_by_candidate_id: None,
            requested_by_review_event_id: None,
            created_at: 4_000_000_000,
            started_at: Some(4_000_000_000),
            completed_at: Some(4_000_000_000),
        })
        .await
        .expect("task run turn should persist");

    let delivery_ingestor = Arc::new(RecordingThreadEpisodicIngestor::default());
    processor
        .set_thread_episodic_ingestor_for_test(delivery_ingestor.clone())
        .await;
    processor
        .process_due_task_deliveries(4_000_000_000, 10)
        .await
        .expect("delivery worker should run");

    let deliveries = processor
        .task_runtime
        .service()
        .list_deliveries(TaskDeliveriesParams {
            workspace_id: workspace_id.clone(),
            task_id: Some(task_id.clone()),
            run_id: None,
            statuses: Vec::new(),
            limit: Some(10),
        })
        .await
        .expect("deliveries should read");
    let delivery = deliveries
        .deliveries
        .first()
        .expect("delivery should exist");
    assert_eq!(
        delivery.status,
        TaskDeliveryStatus::Delivered,
        "delivery failed: {:?}",
        delivery.last_error
    );
    let delivered_result = delivery
        .result_snapshot
        .as_ref()
        .expect("summary delivery should retain a result snapshot");
    assert_eq!(
        delivered_result.summary.as_deref(),
        Some("delivered scheduled result")
    );
    assert!(delivered_result.data.is_none());
    assert!(delivered_result.artifacts.is_empty());
    let delivered_turn_id = delivery
        .delivered_turn_id
        .as_deref()
        .expect("owner thread delivery should record turn id");
    assert_eq!(
        delivered_turn_id,
        run.id.as_str(),
        "owner thread delivery must use target binding -> lineage created_by turn instead of creating a delivery turn"
    );
    let items = crud_store
        .get_turn_item_events(origin_thread_id, delivered_turn_id)
        .await
        .expect("items should read")
        .expect("occurrence turn should exist");
    assert!(
        !items.events.iter().any(|event| {
            matches!(
                &event.payload,
                TurnItemEventPayload::ItemStarted {
                    item: TurnItem::Task { .. },
                    ..
                } | TurnItemEventPayload::ItemCompleted {
                    item: TurnItem::Task { .. },
                    ..
                }
            )
        }),
        "delivery turn should not duplicate the scheduled run task anchor"
    );
    assert!(items.events.iter().any(|event| {
        matches!(
            &event.payload,
            TurnItemEventPayload::ItemStarted {
                item: TurnItem::AgentMessage { text, .. },
                ..
            } if text == "delivered scheduled result"
        )
    }));
    assert!(items.events.iter().any(|event| {
        matches!(
            &event.payload,
            TurnItemEventPayload::ItemCompleted {
                item: TurnItem::AgentMessage { text, .. },
                ..
            } if text == "delivered scheduled result"
        )
    }));
    let ingestion_calls = delivery_ingestor.calls.lock().await;
    assert_eq!(ingestion_calls.len(), 1);
    let delivered_call = &ingestion_calls[0];
    assert_eq!(delivered_call.workspace_id, workspace_id);
    assert_eq!(delivered_call.thread_id, origin_thread_id);
    assert_eq!(delivered_call.turn_id, run.id);
    assert_eq!(delivered_call.item_type, TurnItemType::AgentMessage);
    assert_eq!(
        delivered_call.source_context,
        pioneer_protocol::ThreadEpisodicSourceContext::UserVisibleThreadItem
    );
    assert!(matches!(
        &delivered_call.item,
        TurnItem::AgentMessage { text, .. }
            if text == "delivered scheduled result"
    ));
    drop(ingestion_calls);
    let origin_thread = crud_store
        .get_thread_model(origin_thread_id)
        .await
        .expect("owner thread should read")
        .expect("owner thread should still exist");
    assert_eq!(origin_thread.mode, ThreadMode::Agent);

    let deliveries_request = json!({
        "jsonrpc": "2.0",
        "id": "taskdeliveriesrpc0001",
        "method": "task/deliveries",
        "params": {
            "workspaceId": workspace_id,
            "taskId": task_id,
            "statuses": ["delivered"],
            "limit": 10
        }
    });
    processor
        .process_request_for_connection(connection_id, &deliveries_request.to_string())
        .await;
    let deliveries_response = recv_response_by_id(&mut rx, "taskdeliveriesrpc0001").await;
    let deliveries_payload: PublicTaskDeliveriesResponse =
        serde_json::from_value(deliveries_response.result)
            .expect("task/deliveries response should decode");
    assert_eq!(deliveries_payload.deliveries.len(), 1);
    assert_eq!(
        deliveries_payload.deliveries[0].status,
        TaskDeliveryStatus::Delivered
    );

    let agenda_request = json!({
        "jsonrpc": "2.0",
        "id": "taskagendarpc00000001",
        "method": "task/agenda",
        "params": {
            "workspaceId": workspace_id,
            "ownerKind": "thread",
            "ownerId": origin_thread_id,
            "includeCompleted": true,
            "limit": 10
        }
    });
    processor
        .process_request_for_connection(connection_id, &agenda_request.to_string())
        .await;
    let agenda_response = recv_response_by_id(&mut rx, "taskagendarpc00000001").await;
    let agenda_payload: PublicTaskAgendaResponse =
        serde_json::from_value(agenda_response.result).expect("task/agenda response should decode");
    let agenda_item = agenda_payload
        .items
        .iter()
        .find(|item| item.task.id == deliveries_payload.deliveries[0].task_id)
        .expect("agenda should include completed scheduled delivery when requested");
    assert_eq!(
        agenda_item
            .latest_delivery
            .as_ref()
            .map(|delivery| delivery.status),
        Some(TaskDeliveryStatus::Delivered)
    );
    assert_eq!(
        agenda_item.result_preview.as_deref(),
        Some("delivered scheduled result")
    );
}

