#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn internal_llm_context_event_persists_without_websocket_notification() {
    let (tx, mut rx) = mpsc::channel(8);
    let session_manager = Arc::new(SessionManager::new());
    let _connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let agent_manager = Arc::new(AgentManager::new(test_provider(), test_tool_loop_config()));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = MessageProcessor::with_agent_manager(
        thread_manager,
        agent_manager,
        session_manager,
        workspace_manager,
        crud_store.clone(),
    );
    ensure_test_superuser_execution_turn(
        &processor,
        workspace_id.as_str(),
        "thread_llm_ctx",
        "turn_llm_ctx",
    )
    .await;

    let assistant_round = ChatMessage::assistant_tool_calls_with_reasoning(
        None::<String>,
        Some("SECRET_REASONING_SENTINEL"),
        vec![ProviderToolCall {
            id: "item_llm_ctx".to_owned(),
            name: "read_file".to_owned(),
            arguments: "{}".to_owned(),
        }],
    );
    let assistant_round_payload = serde_json::to_value(&assistant_round).unwrap();
    assert!(
        processor
            .handle_durable_agent_event(AgentDurableEvent::TurnProviderHistoryAppended {
                thread_id: "thread_llm_ctx".to_owned(),
                turn_id: "turn_llm_ctx".to_owned(),
                item_id: "reasoning_llm_ctx".to_owned(),
                sequence: 0,
                payload: assistant_round_payload.clone(),
            })
            .await
    );
    assert!(
        processor
            .handle_durable_agent_event(AgentDurableEvent::TurnProviderHistoryAppended {
                thread_id: "thread_llm_ctx".to_owned(),
                turn_id: "turn_llm_ctx".to_owned(),
                item_id: "reasoning_llm_ctx".to_owned(),
                sequence: 0,
                payload: assistant_round_payload,
            })
            .await,
        "an exact provider-history replay must be idempotent"
    );

    assert!(
        processor
            .handle_durable_agent_event(AgentDurableEvent::TurnLlmContextAppended {
                thread_id: "thread_llm_ctx".to_owned(),
                turn_id: "turn_llm_ctx".to_owned(),
                item_id: "item_llm_ctx".to_owned(),
                attempt_id: Some("1".to_owned()),
                sequence: 7,
                source: "tool_result".to_owned(),
                tool_name: "read_file".to_owned(),
                payload: ToolResultView::Json {
                    value: json!({
                        "output": "SECRET_LLM_CONTEXT_SENTINEL"
                    }),
                    truncated: false,
                },
                output_policy_snapshot: ToolOutputPolicySnapshot::for_tool_name("read_file"),
            })
            .await
    );

    assert!(
        !processor
            .handle_durable_agent_event(AgentDurableEvent::TurnProviderHistoryAppended {
                thread_id: "thread_llm_ctx".to_owned(),
                turn_id: "turn_llm_ctx".to_owned(),
                item_id: "reasoning_llm_ctx".to_owned(),
                sequence: 0,
                payload: serde_json::json!({"conflicting": true}),
            })
            .await,
        "the same provider-history identity must reject conflicting content"
    );

    let rows = crud_store
        .list_turn_llm_context("turn_llm_ctx")
        .await
        .expect("llm context rows should be readable");
    assert_eq!(rows.len(), 2);
    assert_eq!(rows[0].source, "assistant_round");
    assert!(rows[0].payload.contains("SECRET_REASONING_SENTINEL"));
    assert_eq!(rows[1].source, "tool_result");
    assert!(rows[1].payload.contains("SECRET_LLM_CONTEXT_SENTINEL"));
    assert!(
        rows.iter().all(|row| row.expires_at.is_none()),
        "active-turn provider history must remain recoverable for the entire turn lifetime"
    );

    let unexpected = timeout(Duration::from_millis(100), rx.recv()).await;
    assert!(
        unexpected.is_err(),
        "internal llm context event must not be forwarded to websocket"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn turn_mcp_persistence_durable_capability_event_is_read_only() {
    let session_manager = Arc::new(SessionManager::new());
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let agent_manager = Arc::new(AgentManager::new(test_provider(), test_tool_loop_config()));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let crud_store_for_assert = crud_store.clone();
    let processor = MessageProcessor::with_agent_manager(
        thread_manager,
        agent_manager.clone(),
        session_manager,
        workspace_manager,
        crud_store,
    );

    let thread_id = "thr_capabilities_durable_1";
    let turn_id = "turn_capabilities_durable_1";
    ensure_test_superuser_execution_turn(&processor, workspace_id.as_str(), thread_id, turn_id)
        .await;
    agent_manager
        .ensure_thread(thread_id, workspace_id.as_str())
        .await
        .expect("agent thread should be registered for committed subscription");
    let mut committed_rx = agent_manager
        .subscribe_committed(thread_id)
        .await
        .expect("committed subscription should exist");

    processor
        .handle_durable_agent_event(AgentDurableEvent::TurnCapabilitiesResolved {
            thread_id: thread_id.to_owned(),
            turn_id: turn_id.to_owned(),
            accepted: vec![TurnAcceptedCapability {
                id: "skill:DDDDDDDDDDDDDDDDDDDDD".to_owned(),
                label: Some("docs".to_owned()),
                kind: TurnCapabilityKind::Skill {
                    skill_id: pioneer_protocol::SkillId::new("DDDDDDDDDDDDDDDDDDDDD")
                        .expect("valid docs SkillId"),
                    pack_id: None,
                },
                reason: TurnCapabilityAcceptedReason::ExplicitComposerCapability,
            }],
            rejected: vec![TurnRejectedCapability {
                id: "skill:MMMMMMMMMMMMMMMMMMMMM".to_owned(),
                label: Some("missing".to_owned()),
                kind: TurnCapabilityKind::Skill {
                    skill_id: pioneer_protocol::SkillId::new("MMMMMMMMMMMMMMMMMMMMM")
                        .expect("valid missing SkillId"),
                    pack_id: None,
                },
                reason: TurnCapabilityRejectedReason::NotFound,
                message: "Skill `missing` is not installed or not available in this workspace."
                    .to_owned(),
            }],
            mcp_bindings: vec![McpTurnBindingSummary {
                server_installation_id: "mcp_server_resend_001".to_owned(),
                server_name: "resend".to_owned(),
                raw_tool_name: "send".to_owned(),
                callable_name: "mcp_resend_send".to_owned(),
                catalog_version: "catalog-v1".to_owned(),
                fingerprint: "fingerprint-resend".to_owned(),
                selection_reason: "explicit_composer_capability".to_owned(),
                capability_id: Some("mcp-tool:workspace:resend:send".to_owned()),
            }],
        })
        .await;

    let mcp_bindings = crud_store_for_assert
        .list_turn_mcp_bindings(turn_id)
        .await
        .expect("turn MCP bindings query should succeed after durable event");
    assert!(
        mcp_bindings.is_empty(),
        "durable capability event must not write projection bindings"
    );
    assert!(
        crud_store_for_assert
            .get_turn_mcp_projection(turn_id)
            .await
            .expect("turn MCP projection query should succeed")
            .is_none(),
        "durable capability event must not create a projection header"
    );

    let committed = timeout(Duration::from_secs(1), committed_rx.recv())
        .await
        .expect("committed notification should arrive")
        .expect("committed lane should stay open");
    match committed {
        AgentDurableEvent::TurnCapabilitiesResolved {
            turn_id: committed_turn_id,
            accepted,
            rejected,
            mcp_bindings,
            ..
        } => {
            assert_eq!(committed_turn_id, turn_id);
            assert_eq!(accepted.len(), 1);
            assert_eq!(accepted[0].id, "skill:DDDDDDDDDDDDDDDDDDDDD");
            assert_eq!(
                accepted[0].reason,
                TurnCapabilityAcceptedReason::ExplicitComposerCapability
            );
            assert_eq!(rejected.len(), 1);
            assert_eq!(rejected[0].reason, TurnCapabilityRejectedReason::NotFound);
            assert!(
                rejected[0]
                    .message
                    .contains("not installed or not available")
            );
            assert_eq!(mcp_bindings.len(), 1);
            assert_eq!(
                mcp_bindings[0].selection_reason,
                "explicit_composer_capability"
            );
            assert_eq!(
                mcp_bindings[0].capability_id.as_deref(),
                Some("mcp-tool:workspace:resend:send")
            );
            let committed_json =
                serde_json::to_string(&AgentDurableEvent::TurnCapabilitiesResolved {
                    thread_id: thread_id.to_owned(),
                    turn_id: committed_turn_id,
                    accepted,
                    rejected,
                    mcp_bindings,
                })
                .expect("committed capability event should serialize");
            assert!(committed_json.contains("explicit_composer_capability"));
            assert!(committed_json.contains("mcp-tool:workspace:resend:send"));
        }
        other => panic!("expected TurnCapabilitiesResolved committed event, got {other:?}"),
    }
}

