#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_runtime_stale_silent_running_binding_schedules_recovery() {
    let (tx, mut rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let provider_registry = Arc::new(pioneer_provider::ProviderRegistry::with_provider(
        "openai",
        Arc::new(DelayedProvider {
            delay: Duration::from_secs(30),
            text: "late".to_owned(),
        }),
    ));
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let cli_manager = test_cli_runtime_manager(cli_session.clone());
    let processor = MessageProcessor::new(
        thread_manager,
        provider_registry,
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_cli_runtime_manager_for_tests(cli_manager.clone());

    start_loaded_thread_and_turn_for_cli_runtime_test(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        "thread_cli_stale",
        "turn_cli_stale",
    )
    .await;

    let old = chrono::Utc::now().fixed_offset() - chrono::Duration::milliseconds(180_000);
    crud_store
        .upsert_cli_runtime_turn_binding(NewCliRuntimeTurnBinding {
            turn_id: "turn_cli_stale".to_owned(),
            thread_id: "thread_cli_stale".to_owned(),
            continuation_thread_id: "thread_cli_stale".to_owned(),
            workspace_id: workspace_id.clone(),
            runtime_id: "codex".to_owned(),
            runtime_kind: "codex".to_owned(),
            native_thread_id: "codex-thread-stale".to_owned(),
            native_turn_id: Some("codex-turn-stale".to_owned()),
            request_id: None,
            status: crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_RUNNING.to_owned(),
            model: Some("gpt-5".to_owned()),
            cwd: Some("/tmp/project".to_owned()),
            sandbox_json: None,
            approval_policy: None,
            input_mapping_json: "{}".to_owned(),
            created_at: old,
            updated_at: old,
        })
        .await
        .expect("turn binding should upsert");

    let key = CLIAgentRuntimeSessionKey::new(workspace_id.clone(), "codex", "thread_cli_stale")
        .expect("session key should build");
    cli_manager
        .get_or_start(key)
        .await
        .expect("test CLI runtime session should start");

    processor
        .fail_stale_cli_runtime_turns(
            chrono::Utc::now()
                .fixed_offset()
                .timestamp_millis()
                .saturating_add(20 * 60 * 1_000),
        )
        .await;

    let (_workspace_id, turn) = crud_store
        .get_turn("thread_cli_stale", "turn_cli_stale")
        .await
        .expect("turn lookup should succeed")
        .expect("turn should exist");
    assert_eq!(turn.status, TurnStatus::InProgress);
    assert!(
        turn.error.is_none(),
        "recoverable stale runtime must not terminalize the turn: {:?}",
        turn.error,
    );
    let binding = crud_store
        .get_cli_runtime_turn_binding("turn_cli_stale")
        .await
        .expect("binding lookup should succeed")
        .expect("binding should exist");
    assert_eq!(
        binding.status,
        crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_RUNNING
    );
    let pending_jobs = crud_store
        .find_recovery_jobs_by_turn_and_status("turn_cli_stale", RecoveryJobStatus::Pending)
        .await
        .expect("pending recovery jobs should load");
    assert_eq!(pending_jobs.len(), 1);
    assert_eq!(pending_jobs[0].trigger, RecoveryTrigger::RuntimeFailure);
    assert_eq!(pending_jobs[0].action, RecoveryAction::RehydrateTurnState);
    assert!(cli_session.interrupts.lock().await.is_empty());
    assert_eq!(cli_session.closes.load(Ordering::SeqCst), 0);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn codex_transport_observation_gap_enqueues_recovery_without_terminalizing_turn() {
    let (tx, mut rx) = mpsc::channel(32);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let cli_manager = test_cli_runtime_manager(cli_session.clone());
    let processor = with_enabled_test_cli_runtime_catalog(
        MessageProcessor::new(
            thread_manager,
            test_provider(),
            session_manager,
            workspace_manager,
            crud_store.clone(),
            test_gateway_secrets(),
            test_summary_config(),
            test_context_budget(),
            test_tool_loop_config(),
        )
        .with_cli_runtime_manager_for_tests(cli_manager.clone()),
    );

    let thread_id = "thread_codex_transport_gap";
    let turn_id = "turn_codex_transport_gap";
    start_loaded_thread_and_turn_for_cli_runtime_test(
        &processor,
        connection_id,
        &mut rx,
        workspace_id.as_str(),
        thread_id,
        turn_id,
    )
    .await;
    persist_test_cli_execution_authorization_context(
        crud_store.as_ref(),
        workspace_id.as_str(),
        thread_id,
        turn_id,
        "codex",
        "codex",
    )
    .await;
    persist_test_cli_instruction_projection(
        crud_store.as_ref(),
        turn_id,
        CLIAgentRuntimeKind::Codex,
    )
    .await;
    let durable_cwd = load_persisted_security_snapshot(crud_store.as_ref(), turn_id)
        .await
        .sandbox
        .cwd;

    let now = chrono::Utc::now().fixed_offset();
    let (_, native_attempt) = crud_store
        .prepare_cli_runtime_initial_turn_attempt(
            NewCliRuntimeTurnBinding {
                turn_id: turn_id.to_owned(),
                thread_id: thread_id.to_owned(),
                continuation_thread_id: thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                runtime_id: "codex".to_owned(),
                runtime_kind: "codex".to_owned(),
                native_thread_id: "native-thread-transport-gap".to_owned(),
                native_turn_id: None,
                request_id: None,
                status: crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_STARTING
                    .to_owned(),
                model: Some("gpt-5".to_owned()),
                cwd: Some(durable_cwd),
                sandbox_json: None,
                approval_policy: None,
                input_mapping_json: "{}".to_owned(),
                created_at: now,
                updated_at: now,
            },
            "cli_attempt_transport_gap_1".to_owned(),
            1,
        )
        .await
        .expect("turn binding and native attempt should persist");
    crud_store
        .activate_cli_runtime_turn_attempt_owned(
            turn_id,
            native_attempt.id.as_str(),
            "native-turn-transport-gap",
            None,
            now,
            processor.turn_execution_owner_id.as_ref(),
            now + chrono::Duration::seconds(super::TURN_EXECUTION_OWNER_LEASE_SECONDS),
        )
        .await
        .expect("native attempt should activate");

    let key = CLIAgentRuntimeSessionKey::new(workspace_id.clone(), "codex", thread_id)
        .expect("session key should build");
    let handle = cli_manager
        .get_or_start(key.clone())
        .await
        .expect("test CLI runtime session should start");
    processor
        .enqueue_codex_transport_session_recovery(
            handle.instance(),
            "oversized frame exceeded the finite spool budget",
        )
        .await;
    cli_manager
        .close_session(&key)
        .await
        .expect("observation-gap test process should close before recovery");

    let (_workspace_id, turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("turn lookup should succeed")
        .expect("turn should exist");
    assert_eq!(turn.status, TurnStatus::InProgress);
    assert!(turn.error.is_none());
    let pending_jobs = crud_store
        .find_recovery_jobs_by_turn_and_status(turn_id, RecoveryJobStatus::Pending)
        .await
        .expect("pending recovery jobs should load");
    assert_eq!(pending_jobs.len(), 1);
    assert_eq!(pending_jobs[0].trigger, RecoveryTrigger::RuntimeFailure);
    assert_eq!(pending_jobs[0].action, RecoveryAction::RehydrateTurnState);
    let gap_events = crud_store
        .list_cli_runtime_native_events(CliRuntimeNativeEventListFilter {
            runtime_id: Some("codex".to_owned()),
            thread_id: Some(thread_id.to_owned()),
            limit: Some(10),
            ..Default::default()
        })
        .await
        .expect("durable observation gap should load");
    let gap = gap_events
        .iter()
        .find(|event| event.native_method == "observation_gap")
        .expect("transport loss must create a durable observation gap");
    let gap_payload: JsonValue = serde_json::from_str(gap.payload_redacted_json.as_str())
        .expect("observation gap payload should be valid JSON");
    assert_eq!(gap_payload["runtimeId"], json!("codex"));
    assert_eq!(gap_payload["continuationThreadId"], json!(thread_id));
    assert_eq!(gap_payload["activeTurnIds"], json!([turn_id]));

    *cli_session.turn_observation.lock().await = Some(CLIAgentRuntimeTurnObservation {
        status: CLIAgentRuntimeObservedTurnStatus::Completed,
        message: None,
        reconciliation_events: vec![RuntimeEvent::ItemCompleted(RuntimeItemCompleted {
            native_thread_id: Some("native-thread-transport-gap".to_owned()),
            native_turn_id: "native-turn-transport-gap".to_owned(),
            native_item_id: "transport_gap_final_item".to_owned(),
            item_kind: "agentMessage".to_owned(),
            text: Some("recovered after observation gap".to_owned()),
            summary: Vec::new(),
            content: Vec::new(),
            phase: RuntimeAgentMessagePhase::FinalAnswer,
            metadata: None,
            native_item_redacted: None,
            native: None,
        })],
    });
    let events = processor
        .recovery_coordinator
        .run_ready_jobs(pending_jobs[0].scheduled_at_unix.saturating_add(10), 1)
        .await
        .expect("terminal reconciliation recovery should start");
    assert!(matches!(
        events.as_slice(),
        [
            crate::resilience::RecoveryCoordinatorEvent::CliRuntimeTerminalReconciliationRequested(
                _
            )
        ]
    ));
    for event in events {
        assert!(
            processor
                .handle_recovery_event(event, chrono::Utc::now().timestamp())
                .await
        );
    }
    let (_workspace_id, turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("reconciled Turn lookup should succeed")
        .expect("reconciled Turn should exist");
    assert_eq!(
        turn.status,
        TurnStatus::Completed,
        "terminal reconciliation error: {:?}",
        turn.error
    );
    assert!(
        crud_store
            .has_turn_finalization_intent(turn_id)
            .await
            .expect("terminal reconciliation finalization intent should load")
    );
    assert!(cli_session.turn_starts.lock().await.is_empty());
}

