fn run_interrupted_cli_runtime_turn_recovery_test(
    name: &str,
    reconcile_from_runtime_observation: bool,
    fail_after_confirmation: bool,
    detached_child_owner: bool,
    invalid_durable_cwd: bool,
) {
    let thread = std::thread::Builder::new()
        .name(name.to_owned())
        .stack_size(8 * 1024 * 1024)
        .spawn(move || {
            let runtime = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("CLI recovery test runtime should build");
            runtime.block_on(message_future(
                run_interrupted_cli_runtime_turn_recovery_scenario(
                    reconcile_from_runtime_observation,
                    fail_after_confirmation,
                    detached_child_owner,
                    invalid_durable_cwd,
                ),
            ));
        })
        .expect("CLI recovery test thread should start");
    thread
        .join()
        .expect("CLI recovery test thread should finish");
}

async fn run_interrupted_cli_runtime_turn_recovery_scenario(
    reconcile_from_runtime_observation: bool,
    fail_after_confirmation: bool,
    detached_child_owner: bool,
    invalid_durable_cwd: bool,
) {
    let (tx, _rx) = mpsc::channel(64);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let launch_specs = Arc::new(TokioMutex::new(Vec::new()));
    let cli_manager =
        test_cli_runtime_manager_with_launch_specs(cli_session.clone(), Some(launch_specs.clone()));
    let processor = with_enabled_test_cli_runtime_catalog(
        MessageProcessor::new(
            thread_manager.clone(),
            test_provider(),
            session_manager,
            workspace_manager,
            crud_store.clone(),
            test_gateway_secrets(),
            test_summary_config(),
            test_context_budget(),
            test_tool_loop_config(),
        )
        .with_cli_runtime_manager_for_tests(cli_manager.clone()),
    );
    let thread_id = "thread_cli_interrupted_recovery";
    let continuation_thread_id = if detached_child_owner {
        "thread_cli_interrupted_recovery_parent"
    } else {
        thread_id
    };
    let turn_id = "turn_cli_interrupted_recovery";
    let native_thread_id = "native_thread_cli_interrupted_recovery";
    let initial_native_turn_id = "native_turn_cli_interrupted_recovery_1";
    thread_manager
        .thread_start_seeded(
            connection_id,
            workspace_id.clone(),
            ThreadStartParams {
                thread_id: thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                name: Some("CLI recovery".to_owned()),
                model: Some("o4-mini".to_owned()),
                model_provider: Some("openai".to_owned()),
                sandbox: Some(SandboxMode::FullAccess),
                mode: Some(ThreadMode::Agent),
                origin_kind: None,
                sidebar_visibility: None,
                visibility: None,
                agent_nickname: None,
                agent_role: None,
            },
            None,
            None,
        )
        .await
        .expect("CLI recovery thread should load");
    let turn_outcome = thread_manager
        .turn_start(
            connection_id,
            pioneer_protocol::TurnStartParams {
                agent_delegation_routes: Vec::new(),
                thread_id: thread_id.to_owned(),
                turn_id: turn_id.to_owned(),
                input: vec![UserInput::Text {
                    text: "complete the interrupted CLI task".to_owned(),
                    text_elements: Vec::new(),
                }],
                capabilities: Vec::new(),
                model: None,
                model_provider: None,
                sandbox_policy: None,
                mode: None,
                agent_launch: None,
                reply_to_turn_id: None,
                mentioned_principal_ids: Vec::new(),
                execution_backend: Some(AgentExecutionBackend::CLIAgentRuntime {
                    runtime_id: "codex".to_owned(),
                    runtime_kind: CLIAgentRuntimeKind::Codex,
                }),
                reasoning: None,
                permission_profile: Some(pioneer_protocol::TurnPermissionProfileSelection {
                    mode: pioneer_protocol::TurnPermissionMode::Supervised,
                }),
                cli_runtime_options: None,
            },
        )
        .await
        .expect("CLI recovery turn should load");
    crud_store
        .materialize_turn_start(
            &turn_outcome.materialization.thread,
            turn_outcome.materialization.sandbox_mode,
            &turn_outcome.materialization.turn,
            &turn_outcome.materialization.input,
            pioneer_protocol::PersistedActorRef::Principal(
                authenticated_test_superuser().principal_id.clone(),
            ),
        )
        .await
        .expect("CLI recovery turn should materialize");
    if detached_child_owner {
        let now = super::now_timestamp_secs();
        crud_store
            .upsert_thread_model(
                &Thread {
                    workspace_id: workspace_id.clone(),
                    id: continuation_thread_id.to_owned(),
                    name: Some("CLI recovery parent".to_owned()),
                    preview: String::new(),
                    preview_author: None,
                    mode: ThreadMode::Agent,
                    model: "o4-mini".to_owned(),
                    model_provider: "openai".to_owned(),
                    reasoning_effort: None,
                    created_at: now,
                    updated_at: now,
                    status: ThreadStatus::Active,
                    origin_kind: ThreadOriginKind::User,
                    sidebar_visibility: ThreadSidebarVisibility::Visible,
                    agent_nickname: None,
                    agent_role: None,
                    visibility: None,
                    turns: Vec::new(),
                },
                pioneer_protocol::PersistedActorRef::System,
            )
            .await
            .expect("detached recovery parent should materialize");
        crud_store
            .database_connection()
            .execute_unprepared(&format!(
                "UPDATE thread SET access_class='private' WHERE id='{continuation_thread_id}';\
                 UPDATE thread SET access_class='internal', origin_kind='task_run', \
                    sidebar_visibility='hidden' WHERE id='{thread_id}';\
                 INSERT INTO thread_lineage(\
                    child_thread_id,parent_thread_id,root_thread_id,depth,created_at,\
                    origin_kind,created_by_thread_id,created_by_turn_id\
                 ) VALUES(\
                    '{thread_id}','{continuation_thread_id}','{continuation_thread_id}',1,\
                    CURRENT_TIMESTAMP,'task_run','{continuation_thread_id}',NULL\
                 );"
            ))
            .await
            .expect("detached recovery lineage should materialize");
    }
    persist_test_cli_execution_authorization_context(
        crud_store.as_ref(),
        workspace_id.as_str(),
        continuation_thread_id,
        turn_id,
        "codex",
        "codex",
    )
    .await;

    persist_test_cli_instruction_projection(
        crud_store.as_ref(),
        turn_id,
        CLIAgentRuntimeKind::Codex,
    )
    .await;

    let now = chrono::Utc::now().fixed_offset();
    let (_, initial_attempt) = crud_store
        .prepare_cli_runtime_initial_turn_attempt(
            NewCliRuntimeTurnBinding {
                turn_id: turn_id.to_owned(),
                thread_id: thread_id.to_owned(),
                continuation_thread_id: continuation_thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                runtime_id: "codex".to_owned(),
                runtime_kind: "codex".to_owned(),
                native_thread_id: native_thread_id.to_owned(),
                native_turn_id: None,
                request_id: None,
                status: crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_STARTING
                    .to_owned(),
                model: Some("o4-mini".to_owned()),
                cwd: Some(
                    if invalid_durable_cwd {
                        "/tmp/different-project"
                    } else {
                        "/tmp/project"
                    }
                    .to_owned(),
                ),
                sandbox_json: None,
                approval_policy: Some("on-request".to_owned()),
                input_mapping_json: "{}".to_owned(),
                created_at: now,
                updated_at: now,
            },
            "cli_attempt_recovery_1".to_owned(),
            1,
        )
        .await
        .expect("initial CLI attempt should prepare");
    crud_store
        .activate_cli_runtime_turn_attempt_owned(
            turn_id,
            initial_attempt.id.as_str(),
            initial_native_turn_id,
            None,
            now,
            processor.turn_execution_owner_id.as_ref(),
            now + chrono::Duration::seconds(super::TURN_EXECUTION_OWNER_LEASE_SECONDS),
        )
        .await
        .expect("initial CLI attempt should activate");
    assert!(
        processor
            .handle_durable_agent_event(AgentDurableEvent::TurnExecutionWindowStarted {
                notification: pioneer_protocol::TurnExecutionWindowStartedNotification {
                    workspace_id: workspace_id.clone(),
                    thread_id: thread_id.to_owned(),
                    turn_id: turn_id.to_owned(),
                    window_id: initial_attempt.id.clone(),
                    window_index: 1,
                    status: ExecutionWindowStatus::Running,
                    started_at_unix_ms: now.timestamp_millis(),
                },
            })
            .await
    );
    let key = CLIAgentRuntimeSessionKey::new(workspace_id.clone(), "codex", continuation_thread_id)
        .expect("session key should build");

    if reconcile_from_runtime_observation {
        *cli_session.turn_observation.lock().await = Some(CLIAgentRuntimeTurnObservation {
            status: CLIAgentRuntimeObservedTurnStatus::Interrupted,
            message: Some("native process disconnected".to_owned()),
            reconciliation_events: Vec::new(),
        });
        processor
            .fail_stale_cli_runtime_turns(
                chrono::Utc::now()
                    .fixed_offset()
                    .timestamp_millis()
                    .saturating_add(20 * 60 * 1_000),
            )
            .await;
        assert!(
            cli_session.turn_starts.lock().await.is_empty(),
            "observation-gap reconciliation must inspect the durable native turn, not start another user execution"
        );
    } else {
        processor
            .handle_cli_runtime_timeline_event(
                &key,
                RuntimeEvent::TurnInterrupted(RuntimeTurnInterrupted {
                    native_thread_id: Some(native_thread_id.to_owned()),
                    native_turn_id: initial_native_turn_id.to_owned(),
                    reason: "native process disconnected".to_owned(),
                    native: None,
                }),
            )
            .await;
    }

    let (_, interrupted_turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("interrupted Pioneer turn should load")
        .expect("interrupted Pioneer turn should exist");
    assert_eq!(interrupted_turn.status, TurnStatus::InProgress);
    let closed_initial = crud_store
        .get_cli_runtime_turn_attempt(initial_attempt.id.as_str())
        .await
        .expect("initial attempt should load")
        .expect("initial attempt should exist");
    assert_eq!(
        closed_initial.status,
        if reconcile_from_runtime_observation {
            CliRuntimeTurnAttemptStatus::Running
        } else {
            CliRuntimeTurnAttemptStatus::Interrupted
        }
    );
    let pending_jobs = crud_store
        .find_recovery_jobs_by_turn_and_status(turn_id, RecoveryJobStatus::Pending)
        .await
        .expect("pending recovery jobs should load");
    assert_eq!(pending_jobs.len(), 1);
    cli_manager
        .close_session(&key)
        .await
        .expect("interrupted test process should close before recovery");

    let recovery_events = processor
        .recovery_coordinator
        .run_ready_jobs(pending_jobs[0].scheduled_at_unix.saturating_add(10), 1)
        .await
        .expect("CLI recovery should claim its job");
    assert_eq!(recovery_events.len(), 1);
    let recovery_event = recovery_events
        .into_iter()
        .next()
        .expect("CLI recovery event should exist");
    processor
        .handle_recovery_event(recovery_event.clone(), chrono::Utc::now().timestamp())
        .await;
    processor
        .handle_recovery_event(recovery_event, chrono::Utc::now().timestamp())
        .await;

    let recovery_job = if reconcile_from_runtime_observation {
        assert!(
            cli_session.turn_starts.lock().await.is_empty(),
            "terminal observation reconciliation must not start another user execution"
        );
        let observation_launch = launch_specs
            .lock()
            .await
            .last()
            .cloned()
            .expect("observation-gap reconciliation should restore a typed process launch");
        assert_eq!(
            observation_launch.options.cwd.as_deref(),
            Some(std::path::Path::new("/tmp/project")),
            "observation-gap reconciliation must restore the authorized working directory"
        );
        assert_eq!(
            observation_launch.options.approval_policy.as_deref(),
            Some("on-request")
        );
        assert_eq!(
            observation_launch.continuation,
            CliProviderContinuation::CodexRpcThread {
                native_thread_id: Some(native_thread_id.to_owned()),
            },
            "observation-gap reconciliation must bind the durable native thread before process allocation"
        );
        let reconciled_attempt = crud_store
            .get_cli_runtime_turn_attempt(initial_attempt.id.as_str())
            .await
            .expect("reconciled native attempt should load")
            .expect("reconciled native attempt should exist");
        assert_eq!(
            reconciled_attempt.status,
            CliRuntimeTurnAttemptStatus::Interrupted
        );
        cli_manager
            .close_session(&key)
            .await
            .expect("observation process should close before retry");
        let observation_job = crud_store
            .get_recovery_job(pending_jobs[0].id.as_str())
            .await
            .expect("observation recovery job should load")
            .expect("observation recovery job should exist");
        assert_eq!(observation_job.status, RecoveryJobStatus::Succeeded);
        let mut restart_jobs = crud_store
            .find_recovery_jobs_by_turn_and_status(turn_id, RecoveryJobStatus::Pending)
            .await
            .expect("runtime restart recovery job should load");
        assert_eq!(restart_jobs.len(), 1);
        let retry_job = restart_jobs.remove(0);
        assert_ne!(retry_job.id, observation_job.id);
        let retry_events = processor
            .recovery_coordinator
            .run_ready_jobs(retry_job.next_run_at_unix.saturating_add(10), 1)
            .await
            .expect("reconciled CLI recovery should claim its retry");
        assert_eq!(retry_events.len(), 1);
        let retry_event = retry_events
            .into_iter()
            .next()
            .expect("reconciled CLI recovery retry should exist");
        processor
            .handle_recovery_event(retry_event.clone(), chrono::Utc::now().timestamp())
            .await;
        processor
            .handle_recovery_event(retry_event, chrono::Utc::now().timestamp())
            .await;
        retry_job
    } else {
        pending_jobs[0].clone()
    };

    if invalid_durable_cwd {
        assert!(cli_session.thread_resumes.lock().await.is_empty());
        assert!(cli_session.turn_starts.lock().await.is_empty());
        assert!(launch_specs.lock().await.is_empty());
        let blocked_job = crud_store
            .get_recovery_job(pending_jobs[0].id.as_str())
            .await
            .expect("invalid recovery job should load")
            .expect("invalid recovery job should exist");
        assert_eq!(blocked_job.status, RecoveryJobStatus::Blocked);
        let (_, blocked_turn) = crud_store
            .get_turn(thread_id, turn_id)
            .await
            .expect("invalid recovery Turn should load")
            .expect("invalid recovery Turn should exist");
        assert_eq!(blocked_turn.status, TurnStatus::Blocked);
        assert!(
            blocked_turn
                .error
                .as_deref()
                .unwrap_or_default()
                .contains("working directory differs")
        );
        return;
    }

    let resumes = cli_session.thread_resumes.lock().await.clone();
    assert_eq!(resumes.len(), 1);
    assert_eq!(resumes[0].0, native_thread_id);
    let launches = launch_specs.lock().await.clone();
    let recovery_launch = launches
        .last()
        .expect("recovery should allocate a typed CLI process");
    assert_eq!(recovery_launch.mcp, CliMcpSessionLaunch::Disabled);
    assert_eq!(
        recovery_launch.continuation,
        CliProviderContinuation::CodexRpcThread {
            native_thread_id: Some(native_thread_id.to_owned()),
        },
        "recovery must bind the durable Codex thread before process allocation"
    );
    assert_eq!(
        recovery_launch.options.cwd.as_deref(),
        Some(std::path::Path::new("/tmp/project"))
    );
    let starts = cli_session.turn_starts.lock().await.clone();
    let diagnostic_attempt = crud_store
        .latest_cli_runtime_turn_attempt(turn_id)
        .await
        .expect("diagnostic CLI recovery attempt should load");
    let diagnostic_window = crud_store
        .latest_turn_execution_window(turn_id)
        .await
        .expect("diagnostic CLI execution window should load");
    assert_eq!(
        starts.len(),
        1,
        "CLI recovery did not submit its native turn; latest attempt: {diagnostic_attempt:?}; latest execution window: {diagnostic_window:?}"
    );
    assert_eq!(starts[0].native_thread_id, native_thread_id);
    assert_eq!(
        cli_session.goal_resets.lock().await.as_slice(),
        &[native_thread_id.to_owned()],
        "Codex recovery must clear stale Goal state before submitting a new attempt"
    );
    assert!(
        starts[0]
            .elevated_instructions
            .text()
            .contains("## Pioneer CLI Runtime Instructions")
    );
    assert!(
        starts[0]
            .input
            .to_string()
            .contains("Continue the interrupted task")
    );
    let history = crud_store
        .get_thread_history(thread_id, Some(64))
        .await
        .expect("CLI recovery history should load")
        .expect("CLI recovery history should exist");
    let retry_started_count = history
        .events
        .iter()
        .filter(|event| {
            matches!(
                &event.payload,
                ThreadHistoryEventPayload::ItemRetryAttemptStarted {
                    recovery_job_id,
                    ..
                } if recovery_job_id == &recovery_job.id
            )
        })
        .count();
    assert_eq!(retry_started_count, 1);
    let recovery_attempt = crud_store
        .latest_cli_runtime_turn_attempt(turn_id)
        .await
        .expect("recovery attempt should load")
        .expect("recovery attempt should exist");
    assert_eq!(recovery_attempt.attempt_index, 2);
    assert_eq!(
        recovery_attempt.status,
        CliRuntimeTurnAttemptStatus::Running
    );
    assert_eq!(
        recovery_attempt.native_turn_id.as_deref(),
        Some("native_turn_default")
    );
    assert!(recovery_attempt.recovery_attempt_id.is_some());
    assert!(recovery_attempt.recovery_confirmed_at.is_none());
    let active_job = crud_store
        .get_recovery_job(recovery_job.id.as_str())
        .await
        .expect("active CLI recovery job should load")
        .expect("active CLI recovery job should exist");
    assert_eq!(active_job.status, RecoveryJobStatus::Active);
    let binding = crud_store
        .get_cli_runtime_turn_binding(turn_id)
        .await
        .expect("recovered binding should load")
        .expect("recovered binding should exist");
    assert_eq!(binding.native_thread_id, native_thread_id);
    assert_eq!(binding.thread_id, thread_id);
    assert_eq!(binding.continuation_thread_id, continuation_thread_id);
    if detached_child_owner {
        let child_key = CLIAgentRuntimeSessionKey::new(workspace_id.clone(), "codex", thread_id)
            .expect("child session key should build");
        assert!(
            cli_manager.existing_session(&child_key).await.is_none(),
            "recovery must not create a second native conversation owned by the hidden child"
        );
        assert!(
            cli_manager.existing_session(&key).await.is_some(),
            "recovery must resume the parent-owned native continuation"
        );
    }
    assert_eq!(
        binding.native_turn_id.as_deref(),
        Some("native_turn_default")
    );
    let latest_window = crud_store
        .latest_turn_execution_window(turn_id)
        .await
        .expect("recovery execution window should load")
        .expect("recovery execution window should exist");
    assert_eq!(latest_window.window_index, 2);
    assert_eq!(latest_window.status, ExecutionWindowStatus::Running);

    processor
        .handle_cli_runtime_timeline_event(
            &key,
            RuntimeEvent::ItemStarted(RuntimeItemStarted {
                native_thread_id: Some(native_thread_id.to_owned()),
                native_turn_id: "native_turn_default".to_owned(),
                native_item_id: "recovery_user_echo".to_owned(),
                item_kind: "userMessage".to_owned(),
                title: None,
                phase: RuntimeAgentMessagePhase::FinalAnswer,
                metadata: None,
                native_item_redacted: None,
                native: None,
            }),
        )
        .await;
    let still_active_job = crud_store
        .get_recovery_job(recovery_job.id.as_str())
        .await
        .expect("CLI recovery job should load after user echo")
        .expect("CLI recovery job should exist after user echo");
    assert_eq!(still_active_job.status, RecoveryJobStatus::Active);

    if reconcile_from_runtime_observation {
        let recovery = pioneer_protocol::RecoveryAttemptContext {
            job_id: recovery_attempt
                .recovery_job_id
                .clone()
                .expect("recovery job id should exist"),
            attempt_id: recovery_attempt
                .recovery_attempt_id
                .clone()
                .expect("recovery attempt id should exist"),
        };
        let crash_gap_events = processor
            .recovery_coordinator
            .succeed_active_recovery_attempt(turn_id, &recovery, chrono::Utc::now().timestamp())
            .await
            .expect("recovery job should succeed before simulated crash");
        assert_eq!(crash_gap_events.len(), 1);
        let marker_before_repair = crud_store
            .latest_cli_runtime_turn_attempt(turn_id)
            .await
            .expect("recovery attempt should load before marker repair")
            .expect("recovery attempt should exist before marker repair");
        assert!(marker_before_repair.recovery_confirmed_at.is_none());
    }

    processor
        .handle_cli_runtime_timeline_event(
            &key,
            RuntimeEvent::ItemStarted(RuntimeItemStarted {
                native_thread_id: Some(native_thread_id.to_owned()),
                native_turn_id: "native_turn_default".to_owned(),
                native_item_id: "recovery_reasoning".to_owned(),
                item_kind: "reasoning".to_owned(),
                title: None,
                phase: RuntimeAgentMessagePhase::FinalAnswer,
                metadata: None,
                native_item_redacted: None,
                native: None,
            }),
        )
        .await;

    let confirmed_attempt = crud_store
        .latest_cli_runtime_turn_attempt(turn_id)
        .await
        .expect("confirmed recovery attempt should load")
        .expect("confirmed recovery attempt should exist");
    assert!(confirmed_attempt.recovery_confirmed_at.is_some());
    let succeeded_before_completion = crud_store
        .get_recovery_job(recovery_job.id.as_str())
        .await
        .expect("confirmed CLI recovery job should load")
        .expect("confirmed CLI recovery job should exist");
    assert_eq!(
        succeeded_before_completion.status,
        RecoveryJobStatus::Succeeded
    );
    let watchdog_events = processor
        .recovery_coordinator
        .run_ready_jobs(recovery_job.scheduled_at_unix.saturating_add(181), 16)
        .await
        .expect("recovery watchdog should run after the original wall-clock budget");
    assert!(watchdog_events.is_empty());
    let (_, running_turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("recovered turn should load after the recovery budget")
        .expect("recovered turn should exist after the recovery budget");
    assert_eq!(running_turn.status, TurnStatus::InProgress);
    let running_window = crud_store
        .latest_turn_execution_window(turn_id)
        .await
        .expect("running recovery execution window should load")
        .expect("running recovery execution window should exist");
    assert_eq!(running_window.status, ExecutionWindowStatus::Running);

    if fail_after_confirmation {
        processor
            .handle_cli_runtime_timeline_event(
                &key,
                RuntimeEvent::TurnFailed(RuntimeTurnFailed {
                    native_thread_id: Some(native_thread_id.to_owned()),
                    native_turn_id: Some("native_turn_default".to_owned()),
                    message: "recovered native turn failed later".to_owned(),
                    code: Some("runtime_failure".to_owned()),
                    native: None,
                }),
            )
            .await;

        let (_, retrying_turn) = crud_store
            .get_turn(thread_id, turn_id)
            .await
            .expect("later failed turn should load")
            .expect("later failed turn should exist");
        assert_eq!(retrying_turn.status, TurnStatus::InProgress);
        let next_jobs = crud_store
            .find_recovery_jobs_by_turn_and_status(turn_id, RecoveryJobStatus::Pending)
            .await
            .expect("next recovery job should load");
        assert_eq!(next_jobs.len(), 1);
        assert_ne!(next_jobs[0].id, recovery_job.id);
        let prior_job = crud_store
            .get_recovery_job(recovery_job.id.as_str())
            .await
            .expect("prior recovery job should load")
            .expect("prior recovery job should exist");
        assert_eq!(prior_job.status, RecoveryJobStatus::Succeeded);
        return;
    }

    processor
        .handle_cli_runtime_timeline_event(
            &key,
            RuntimeEvent::TurnCompleted(RuntimeTurnCompleted {
                native_thread_id: Some(native_thread_id.to_owned()),
                native_turn_id: "native_turn_default".to_owned(),
                status: "completed".to_owned(),
                native: None,
            }),
        )
        .await;

    let (_, completed_turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("completed recovered turn should load")
        .expect("completed recovered turn should exist");
    assert_eq!(completed_turn.status, TurnStatus::Completed);
    let completed_attempt = crud_store
        .latest_cli_runtime_turn_attempt(turn_id)
        .await
        .expect("completed recovery attempt should load")
        .expect("completed recovery attempt should exist");
    assert_eq!(
        completed_attempt.status,
        CliRuntimeTurnAttemptStatus::Completed
    );
    let succeeded_job = crud_store
        .get_recovery_job(recovery_job.id.as_str())
        .await
        .expect("succeeded CLI recovery job should load")
        .expect("succeeded CLI recovery job should exist");
    assert_eq!(succeeded_job.status, RecoveryJobStatus::Succeeded);
    let completed_window = crud_store
        .latest_turn_execution_window(turn_id)
        .await
        .expect("completed recovery execution window should load")
        .expect("completed recovery execution window should exist");
    assert_eq!(completed_window.window_index, 2);
    assert_eq!(completed_window.status, ExecutionWindowStatus::Completed);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_runtime_terminal_cleanup_keeps_session_open_for_other_active_turn() {
    let (tx, _rx) = mpsc::channel(16);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    session_manager
        .set_connection_workspace(connection_id, Some(workspace_id.clone()))
        .await;
    let cli_session = Arc::new(RecordingCliRuntimeSession::default());
    let cli_manager = test_cli_runtime_manager(cli_session.clone());
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    )
    .with_cli_runtime_manager_for_tests(cli_manager.clone());

    let thread_id = "thread_cli_terminal_cleanup_other_active";
    let old_turn_id = "turn_cli_terminal_cleanup_old";
    let active_turn_id = "turn_cli_terminal_cleanup_active";
    let now = chrono::Utc::now().fixed_offset();
    for (turn_id, native_thread_id, native_turn_id) in [
        (
            old_turn_id,
            "codex-thread-terminal-cleanup-old",
            "codex-turn-terminal-cleanup-old",
        ),
        (
            active_turn_id,
            "codex-thread-terminal-cleanup-active",
            "codex-turn-terminal-cleanup-active",
        ),
    ] {
        crud_store
            .upsert_cli_runtime_turn_binding(NewCliRuntimeTurnBinding {
                turn_id: turn_id.to_owned(),
                thread_id: thread_id.to_owned(),
                continuation_thread_id: thread_id.to_owned(),
                workspace_id: workspace_id.clone(),
                runtime_id: "codex".to_owned(),
                runtime_kind: "codex".to_owned(),
                native_thread_id: native_thread_id.to_owned(),
                native_turn_id: Some(native_turn_id.to_owned()),
                request_id: None,
                status: crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_RUNNING
                    .to_owned(),
                model: Some("gpt-5".to_owned()),
                cwd: Some("/tmp/project".to_owned()),
                sandbox_json: None,
                approval_policy: None,
                input_mapping_json: "{}".to_owned(),
                created_at: now,
                updated_at: now,
            })
            .await
            .expect("CLI runtime turn binding should upsert");
    }

    let key = CLIAgentRuntimeSessionKey::new(workspace_id.clone(), "codex", thread_id)
        .expect("session key should build");
    cli_manager
        .get_or_start(key.clone())
        .await
        .expect("test CLI runtime session should start");

    processor
        .ensure_cli_runtime_turn_blocked_cleanup(thread_id, old_turn_id, Some("test block"))
        .await;

    assert_eq!(
        *cli_session.interrupts.lock().await,
        vec![(
            Some("codex-thread-terminal-cleanup-old".to_owned()),
            Some("codex-turn-terminal-cleanup-old".to_owned())
        )]
    );
    assert_eq!(cli_session.closes.load(Ordering::SeqCst), 0);
    assert!(
        cli_manager.existing_session(&key).await.is_some(),
        "terminal cleanup for one turn must not close another active turn session"
    );

    let old_binding = crud_store
        .get_cli_runtime_turn_binding(old_turn_id)
        .await
        .expect("old binding should load")
        .expect("old binding should exist");
    assert_eq!(
        old_binding.status,
        crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_BLOCKED
    );
    let active_binding = crud_store
        .get_cli_runtime_turn_binding(active_turn_id)
        .await
        .expect("active binding should load")
        .expect("active binding should exist");
    assert_eq!(
        active_binding.status,
        crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_RUNNING
    );
}

