#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_runtime_command_approval_rejects_legacy_session_scope() {
    let (processor, connection_id, mut rx, workspace_id, crud_store, cli_session) =
        cli_runtime_approval_processor().await;
    let opened =
        open_test_codex_command_approval(&processor, &mut rx, workspace_id.as_str(), json!(777))
            .await;

    assert_eq!(opened.request.kind, CLIRuntimeRequestKind::CommandApproval);
    assert_eq!(opened.request.native_request_id.as_deref(), Some("777"));
    assert_eq!(
        opened
            .request
            .payload
            .as_ref()
            .and_then(|payload| payload.get("command"))
            .and_then(JsonValue::as_str),
        Some("cargo test")
    );
    assert_eq!(
        opened
            .request
            .payload
            .as_ref()
            .and_then(|payload| payload.get("cwd"))
            .and_then(JsonValue::as_str),
        Some("/tmp/project")
    );

    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": "cmdapproval_session01",
                "method": pioneer_protocol::constants::methods::CLI_RUNTIME_REQUEST_RESPOND,
                "params": {
                    "workspace_id": workspace_id,
                    "runtime_id": "codex",
                    "request_id": opened.request_id,
                    "resolution": {
                        "status": "answered",
                        "response": { "decision": "allow_for_session" }
                    }
                }
            })
            .to_string(),
        )
        .await;

    let error = recv_error_by_id(&mut rx, "cmdapproval_session01").await;
    assert_eq!(error.error.code, INVALID_PARAMS_CODE);
    assert_public_error(
        &error,
        PublicErrorCode::InvalidInput,
        PublicErrorStage::Execution,
    );

    let responses = cli_session.responses.lock().await;
    assert!(responses.is_empty());
    assert!(cli_session.interrupts.lock().await.is_empty());
    let pending = crud_store
        .get_cli_runtime_pending_request(opened.request_id.as_str())
        .await
        .expect("pending request should load")
        .expect("pending request should remain");
    assert_eq!(
        pending.status,
        pioneer_crud::CliRuntimePendingRequestStatus::Pending
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_runtime_command_approval_denied_resolves_and_sends_decline() {
    let (processor, connection_id, mut rx, workspace_id, crud_store, cli_session) =
        cli_runtime_approval_processor().await;
    let opened = open_test_codex_command_approval(
        &processor,
        &mut rx,
        workspace_id.as_str(),
        json!("approval-native-1"),
    )
    .await;

    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": "cmdapproval_deny00001",
                "method": pioneer_protocol::constants::methods::CLI_RUNTIME_REQUEST_RESPOND,
                "params": {
                    "workspace_id": workspace_id,
                    "runtime_id": "codex",
                    "request_id": opened.request_id,
                    "resolution": {
                        "status": "denied",
                        "reason": "unsafe command"
                    }
                }
            })
            .to_string(),
        )
        .await;

    let (response, resolved) = recv_response_and_notification_by_id_method(
        &mut rx,
        "cmdapproval_deny00001",
        events::CLI_RUNTIME_REQUEST_RESOLVED,
    )
    .await;
    let result: CLIRuntimeRequestRespondResponse =
        serde_json::from_value(response.result).expect("respond result should decode");
    assert_eq!(result.status, CLIRuntimePendingRequestStatus::Answered);
    assert_eq!(
        result.resolution,
        CLIRuntimeRequestResolution::Denied {
            reason: Some("unsafe command".to_owned())
        }
    );

    let resolved_payload: CLIRuntimeRequestResolvedNotification =
        serde_json::from_value(resolved.params.expect("request_resolved params"))
            .expect("request_resolved payload should decode");
    assert_eq!(
        resolved_payload.resolution,
        CLIRuntimeRequestResolution::Denied {
            reason: Some("unsafe command".to_owned())
        }
    );

    let responses = cli_session.responses.lock().await;
    assert_eq!(responses.len(), 1);
    assert_eq!(responses[0].0, json!("approval-native-1"));
    assert_eq!(responses[0].1, json!({"decision": "decline"}));
    assert!(cli_session.interrupts.lock().await.is_empty());

    let stored = crud_store
        .get_cli_runtime_pending_request(opened.request_id.as_str())
        .await
        .expect("pending request lookup should succeed")
        .expect("pending request should remain durable");
    assert_eq!(
        stored.status,
        pioneer_crud::CliRuntimePendingRequestStatus::Answered
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn grandchild_cli_runtime_approval_projects_to_root_and_root_denial_reaches_origin_session() {
    let (processor, connection_id, mut rx, workspace_id, crud_store, cli_session) =
        cli_runtime_approval_processor().await;
    let root_thread_id = "thread_cli_approval_root";
    let root_turn_id = "turn_cli_approval_root";
    let child_thread_id = "thread_cli_approval_child";
    let child_turn_id = "turn_cli_approval_child";
    let grandchild_thread_id = "thread_cli_command_approval";
    let grandchild_turn_id = "codex-turn-command";

    materialize_cli_runtime_approval_turn(
        crud_store.as_ref(),
        workspace_id.as_str(),
        root_thread_id,
        root_turn_id,
    )
    .await;
    materialize_cli_runtime_approval_turn(
        crud_store.as_ref(),
        workspace_id.as_str(),
        child_thread_id,
        child_turn_id,
    )
    .await;
    crud_store
        .append_task_event(
            TaskEventPayload::TaskThreadLineageCreated {
                task_id: "task_cli_approval_child".to_owned(),
                run_id: "run_cli_approval_child".to_owned(),
                lineage: TaskThreadLineage {
                    child_thread_id: child_thread_id.to_owned(),
                    parent_thread_id: root_thread_id.to_owned(),
                    root_thread_id: root_thread_id.to_owned(),
                    depth: 1,
                    origin_kind: Some("task_run".to_owned()),
                    created_by_thread_id: Some(root_thread_id.to_owned()),
                    created_by_turn_id: Some(root_turn_id.to_owned()),
                    created_at: 10,
                },
            },
            10,
        )
        .await
        .expect("child task lineage should persist");
    crud_store
        .append_task_event(
            TaskEventPayload::TaskThreadLineageCreated {
                task_id: "task_cli_approval_grandchild".to_owned(),
                run_id: "run_cli_approval_grandchild".to_owned(),
                lineage: TaskThreadLineage {
                    child_thread_id: grandchild_thread_id.to_owned(),
                    parent_thread_id: child_thread_id.to_owned(),
                    root_thread_id: root_thread_id.to_owned(),
                    depth: 2,
                    origin_kind: Some("task_run".to_owned()),
                    created_by_thread_id: Some(child_thread_id.to_owned()),
                    created_by_turn_id: Some(child_turn_id.to_owned()),
                    created_at: 11,
                },
            },
            11,
        )
        .await
        .expect("grandchild task lineage should persist");
    crud_store
        .database_connection()
        .execute_unprepared(&format!(
            "UPDATE thread SET access_class='internal', origin_kind='task_run', \
             sidebar_visibility='hidden' WHERE id IN ('{child_thread_id}','{grandchild_thread_id}')"
        ))
        .await
        .expect("approval child threads should use the production internal access class");
    persist_test_cli_execution_authorization_context(
        crud_store.as_ref(),
        workspace_id.as_str(),
        root_thread_id,
        grandchild_turn_id,
        "codex",
        "codex",
    )
    .await;

    let opened = open_test_codex_command_approval(
        &processor,
        &mut rx,
        workspace_id.as_str(),
        json!("grandchild-native-approval"),
    )
    .await;
    let page_before = request_thread_timeline_page_for_test(
        &processor,
        connection_id,
        &mut rx,
        root_thread_id,
        "clipermrootbefore0001",
    )
    .await;
    let proxy = page_before
        .blocks
        .iter()
        .find(|block| {
            matches!(
                &block.kind,
                pioneer_protocol::TimelineBlockKind::PendingRequest {
                    request_id,
                    status: pioneer_protocol::CLIRuntimePendingRequestStatus::Pending,
                    ..
                } if request_id == &opened.request_id
            )
        })
        .expect("root timeline should contain the grandchild approval proxy");
    assert_eq!(proxy.thread_id, grandchild_thread_id);
    assert_eq!(proxy.turn_id.as_deref(), Some(grandchild_turn_id));

    let respond_request_id = "clipermrootdeny000001";
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": respond_request_id,
                "method": pioneer_protocol::constants::methods::CLI_RUNTIME_REQUEST_RESPOND,
                "params": {
                    "workspace_id": workspace_id,
                    "runtime_id": "codex",
                    "request_id": opened.request_id,
                    "resolution": {
                        "status": "denied",
                        "reason": "denied from root parent"
                    }
                }
            })
            .to_string(),
        )
        .await;
    let (response, _) = recv_response_and_notification_by_id_method(
        &mut rx,
        respond_request_id,
        events::CLI_RUNTIME_REQUEST_RESOLVED,
    )
    .await;
    let result: CLIRuntimeRequestRespondResponse =
        serde_json::from_value(response.result).expect("respond result should decode");
    assert_eq!(
        result.resolution,
        CLIRuntimeRequestResolution::Denied {
            reason: Some("denied from root parent".to_owned())
        }
    );

    let responses = cli_session.responses.lock().await;
    assert_eq!(
        responses.as_slice(),
        [(
            json!("grandchild-native-approval"),
            json!({ "decision": "decline" })
        )]
    );
    drop(responses);

    let page_after = request_thread_timeline_page_for_test(
        &processor,
        connection_id,
        &mut rx,
        root_thread_id,
        "clipermrootafter00001",
    )
    .await;
    assert!(
        page_after.blocks.iter().all(|block| {
            !matches!(
                &block.kind,
                pioneer_protocol::TimelineBlockKind::PendingRequest { request_id, .. }
                    if request_id == &opened.request_id
            )
        }),
        "resolved grandchild approval must disappear from the root timeline"
    );
}

