async fn send_epic6_test_message(
    processor: &MessageProcessor,
    connection_id: ConnectionId,
    rx: &mut mpsc::Receiver<Message>,
    thread_id: &str,
    turn_id: &str,
    text: &str,
) {
    let request_id = generate_test_request_id("epic6batchsend", turn_id);
    processor
        .process_request_for_connection(
            connection_id,
            &json!({
                "jsonrpc": "2.0",
                "id": request_id,
                "method": "turn/start",
                "params": {
                    "thread_id": thread_id,
                    "turn_id": turn_id,
                    "mode": "Message",
                    "input": [{"type": "text", "text": text}]
                }
            })
            .to_string(),
        )
        .await;
    let _ =
        recv_response_and_notification_by_id_method(rx, request_id.as_str(), events::TURN_STARTED)
            .await;
    let _ = recv_notification_by_method(rx, events::TURN_COMPLETED).await;
    let _ = recv_notification_by_method(rx, events::THREAD_TIMELINE_BLOCKS_CHANGED).await;
}

