fn completed_command_execution_item(item_id: &str) -> TurnItem {
    let mut item = command_execution_item(item_id);
    if let TurnItem::CommandExecution {
        status,
        display,
        storage,
        success,
        ..
    } = &mut item
    {
        *status = ToolCallStatus::Completed;
        *success = Some(true);
        if let ToolDisplayPayload::Shell { exit_code, .. } = display {
            *exit_code = Some(0);
        }
        if let ToolStoragePayload::Shell { exit_code, .. } = storage {
            *exit_code = Some(0);
        }
    }
    item
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn recovery_lifecycle_notification_is_persisted_for_history_replay() {
    let (tx, mut rx) = mpsc::channel(16);
    let session_manager = Arc::new(SessionManager::new());
    let connection_id = register_authenticated_test_connection(session_manager.as_ref(), tx).await;
    let thread_manager = Arc::new(ThreadManager::new("o4-mini", "openai"));
    let (workspace_manager, crud_store, workspace_id) = setup_workspace_manager().await;
    let processor = MessageProcessor::new(
        thread_manager,
        test_provider(),
        session_manager,
        workspace_manager,
        crud_store.clone(),
        test_gateway_secrets(),
        test_summary_config(),
        test_context_budget(),
        test_tool_loop_config(),
    );

    let thread_start_request = json!({
        "jsonrpc": "2.0",
        "id": "aaaaaaaaaaaaaaaaaaa99",
        "method": "thread/start",
        "params": {
            "thread_id": "thr_000000000000000099",
            "workspace_id": workspace_id
        }
    });
    processor
        .process_request_for_connection(connection_id, &thread_start_request.to_string())
        .await;
    let response = recv_response_by_id(&mut rx, "aaaaaaaaaaaaaaaaaaa99").await;
    let thread_start: ThreadStartResponse =
        serde_json::from_value(response.result).expect("thread/start result should decode");

    let turn = Turn {
        id: "turn_000000000000000099".to_owned(),
        status: TurnStatus::InProgress,
        turn_kind: Default::default(),
        origin: Default::default(),
        mode: Default::default(),
        author: None,
        reply_to_turn_id: None,
        mentions: Vec::new(),
        message_revision: 0,
        message_deleted: false,
        error: None,
        prompt_manifest: None,
        permission_profile: default_test_permission_profile(),
    };
    crud_store
        .materialize_turn_start(
            &thread_start.thread,
            SandboxMode::FullAccess,
            &turn,
            &[UserInput::Text {
                text: "recover me".to_owned(),
                text_elements: Vec::new(),
            }],
            pioneer_protocol::PersistedActorRef::System,
        )
        .await
        .expect("turn start should persist");

    processor
        .handle_recovery_event(
            crate::resilience::RecoveryCoordinatorEvent::RecoveryOpened {
                job_id: "recovery_job_history".to_owned(),
                turn_id: turn.id.clone(),
                item_id: "reasoning_history".to_owned(),
                item_type: TurnItemType::Reasoning,
                trigger: RecoveryTrigger::ProviderError,
                action: RecoveryAction::RetryWithBackoff,
                attempt_number: 1,
            },
            1_700_000_001,
        )
        .await;

    let opened = recv_notification_by_method(&mut rx, events::ITEM_RECOVERY_OPENED).await;
    assert_eq!(
        opened
            .params
            .and_then(|params| params.get("recovery_job_id").cloned()),
        Some(json!("recovery_job_history"))
    );

    let history = crud_store
        .get_thread_history(thread_start.thread.id.as_str(), Some(16))
        .await
        .expect("thread history should load")
        .expect("thread history should exist");
    assert!(history.events.iter().any(|event| matches!(
        &event.payload,
        ThreadHistoryEventPayload::ItemRecoveryOpened {
            recovery_job_id,
            trigger,
            action,
            attempt_number,
            ..
        } if recovery_job_id == "recovery_job_history"
            && *trigger == RecoveryTrigger::ProviderError
            && *action == RecoveryAction::RetryWithBackoff
            && *attempt_number == 1
    )));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn recovery_blocked_event_marks_turn_blocked_and_closes_active_window() {
    let thread_id = "thr_recovery_blocked_missing_snapshot";
    let turn_id = "turn_recovery_blocked_missing_snapshot";
    let (processor, crud_store, workspace_id) =
        setup_execution_window_terminal_turn(thread_id, turn_id).await;

    start_terminal_test_execution_window(
        &processor,
        workspace_id.as_str(),
        thread_id,
        turn_id,
        "runtime_win_recovery_blocked_missing_snapshot",
    )
    .await;

    let block_reason = "cannot restore recovery after agent loop loss because durable turn runtime snapshot is missing";
    let job = crud_store
        .enqueue_recovery_job(
            turn_id.to_owned(),
            "tool_missing_snapshot".to_owned(),
            TurnItemType::WebFetch,
            None,
            RecoveryTrigger::Timeout,
            RecoveryAction::RetryAttempt,
            Some("tool idle timeout".to_owned()),
            None,
            None,
            None,
            0,
            2,
            json!({}),
            json!({
                "base_backoff_secs": 0,
                "max_wall_clock_secs": 60,
                "no_progress_limit": 3,
            }),
            1_700_000_010,
        )
        .await
        .expect("recovery job should enqueue");
    crud_store
        .mark_recovery_job_terminal(
            job.id.as_str(),
            RecoveryJobStatus::Blocked,
            Some(block_reason.to_owned()),
            1_700_000_011,
        )
        .await
        .expect("recovery job should be blocked before event dispatch");

    processor
        .handle_recovery_event(
            crate::resilience::RecoveryCoordinatorEvent::RecoveryBlocked {
                job_id: job.id.clone(),
                turn_id: turn_id.to_owned(),
                reason: block_reason.to_owned(),
            },
            1_700_000_012,
        )
        .await;

    let (_workspace_id, turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("turn should load")
        .expect("turn should exist");
    assert_eq!(turn.status, TurnStatus::Blocked);
    assert!(
        turn.error
            .as_deref()
            .unwrap_or_default()
            .contains("runtime snapshot is missing")
    );

    let window = crud_store
        .latest_turn_execution_window(turn_id)
        .await
        .expect("latest window should load")
        .expect("window should exist");
    assert_eq!(window.status, ExecutionWindowStatus::Blocked);
    assert_eq!(window.metadata_json["terminalStatus"], "blocked");
    assert_eq!(
        window.metadata_json["terminalSource"],
        "turn_terminal_event"
    );

    let history = crud_store
        .get_thread_history(thread_id, Some(16))
        .await
        .expect("thread history should load")
        .expect("thread history should exist");
    assert!(history.events.iter().any(|event| matches!(
        &event.payload,
        ThreadHistoryEventPayload::TurnBlocked {
            turn,
            resume: Some(resume),
            ..
        } if turn.status == TurnStatus::Blocked
            && resume.blocked_recovery_job_id.as_deref() == Some(job.id.as_str())
            && !resume.can_resume_same_turn
            && resume.resume_requirements.iter().any(|requirement| {
                requirement.contains("no durable turn runtime snapshot")
            })
    )));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cli_recovery_blocked_event_surfaces_projection_root_cause() {
    let thread_id = "thr_cli_recovery_blocked_root_cause";
    let turn_id = "turn_cli_recovery_blocked_root_cause";
    let (processor, crud_store, workspace_id) =
        setup_execution_window_terminal_turn(thread_id, turn_id).await;

    start_terminal_test_execution_window(
        &processor,
        workspace_id.as_str(),
        thread_id,
        turn_id,
        "runtime_win_cli_recovery_blocked_root_cause",
    )
    .await;

    let now = chrono::Utc::now().fixed_offset();
    crud_store
        .upsert_cli_runtime_turn_binding(NewCliRuntimeTurnBinding {
            turn_id: turn_id.to_owned(),
            thread_id: thread_id.to_owned(),
            continuation_thread_id: thread_id.to_owned(),
            workspace_id: workspace_id.clone(),
            runtime_id: "codex".to_owned(),
            runtime_kind: "codex".to_owned(),
            native_thread_id: "codex-thread-root-cause".to_owned(),
            native_turn_id: Some("codex-turn-root-cause".to_owned()),
            request_id: None,
            status: crate::cli_runtime::turn_binding::CLI_RUNTIME_TURN_STATUS_RUNNING.to_owned(),
            model: Some("gpt-5".to_owned()),
            cwd: Some("/tmp/project".to_owned()),
            sandbox_json: None,
            approval_policy: None,
            input_mapping_json: "{}".to_owned(),
            created_at: now,
            updated_at: now,
        })
        .await
        .expect("CLI runtime turn binding should upsert");

    let root_reason = "failed to persist item/started: tool item `mcp:Resend/send-email` display payload must be hidden for metadata-only/hidden timeline policy";
    let blocked_reason = "cannot restore recovery after agent loop loss because durable turn runtime snapshot is missing";
    let job = crud_store
        .enqueue_recovery_job(
            turn_id.to_owned(),
            "mcp_resend_send_email".to_owned(),
            TurnItemType::DynamicToolCall,
            None,
            RecoveryTrigger::ProviderError,
            RecoveryAction::RetryAttempt,
            Some(root_reason.to_owned()),
            None,
            None,
            None,
            0,
            2,
            json!({}),
            json!({
                "base_backoff_secs": 0,
                "max_wall_clock_secs": 60,
                "no_progress_limit": 3,
            }),
            1_700_000_020,
        )
        .await
        .expect("recovery job should enqueue");
    crud_store
        .mark_recovery_job_terminal(
            job.id.as_str(),
            RecoveryJobStatus::Blocked,
            Some(blocked_reason.to_owned()),
            1_700_000_021,
        )
        .await
        .expect("recovery job should be blocked before event dispatch");

    processor
        .handle_recovery_event(
            crate::resilience::RecoveryCoordinatorEvent::RecoveryBlocked {
                job_id: job.id.clone(),
                turn_id: turn_id.to_owned(),
                reason: blocked_reason.to_owned(),
            },
            1_700_000_022,
        )
        .await;

    let (_workspace_id, turn) = crud_store
        .get_turn(thread_id, turn_id)
        .await
        .expect("turn should load")
        .expect("turn should exist");
    assert_eq!(turn.status, TurnStatus::Blocked);
    let turn_error = turn.error.as_deref().unwrap_or_default();
    assert!(
        turn_error.contains(root_reason),
        "turn error should surface root cause, got {turn_error}"
    );
    assert!(
        !turn_error.contains(blocked_reason),
        "turn error should not make the secondary recovery failure primary: {turn_error}"
    );

    let history = crud_store
        .get_thread_history(thread_id, Some(16))
        .await
        .expect("thread history should load")
        .expect("thread history should exist");
    assert!(history.events.iter().any(|event| matches!(
        &event.payload,
        ThreadHistoryEventPayload::TurnBlocked {
            turn,
            resume: Some(resume),
            ..
        } if turn.status == TurnStatus::Blocked
            && resume.blocked_recovery_job_id.as_deref() == Some(job.id.as_str())
            && resume.human_message == root_reason
            && !resume.can_resume_same_turn
    )));
}

